INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('a1flecke/games-for-my-kids/petstore-checklist', 'community', 'a1flecke', 'games-for-my-kids', 'a1flecke/games-for-my-kids', 'petstore-checklist', 0, 0, 45, '2026-03-07T09:52:21Z', '2026-03-07T13:06:07.117Z', '84a30a056afe5cc880207caa03ea6f73ead1f3aaf6a5d62593021d67c3fc42da', '{"id":"a1flecke/games-for-my-kids/petstore-checklist","name":"petstore-checklist","description":{"en":"The petstore-checklist skill provides a collection of games for kids, helping developers implement session specs with bug-free code and proper event binding","zh":"petstore-checklist是一个用于开发的技术框架，包含特定规则和代码实践","ja":"ペットストア チェックリストは、特定のルールとコードの実践を含む開発用テクニカル フレームワークです","ko":"펫스토어 체크리스트는 특정 규칙 및 코드 관행을 포함하는 개발용 기술 프레임워크입니다","es":"petstore-checklist es una colección de juegos para niños, que requiere una configuración y implementación cuidadosas para garantizar una experiencia de usuario óptima","fr":"petstore-checklist est une collection de jeux pour enfants, qui nécessite une configuration et une mise en œuvre soigneuses pour garantir une expérience utilisateur optimale","de":"petstore-checklist ist eine Sammlung von Spielen für Kinder, die eine sorgfältige Konfiguration und Implementierung erfordert, um eine optimale Benutzererfahrung zu gewährleisten","pt":"O petstore-checklist é uma coleção de regras para desenvolvedores, incluindo a substituição de código inválido e o uso de CSS para melhorar a experiência do usuário.","ru":"petstore-checklist - это коллекция правил для разработчиков, включая замену недопустимого кода и использование CSS для улучшения пользовательского опыта.","ar":"petstore-checklist هو مجموعة من القواعد ل المطورين، بما في ذلك استبدال رمز غير صالح واستخدام CSS لتحسين تجربة المستخدم."},"seo":{"title":{"en":"petstore-checklist: Setup Guide for AI Agents","zh":"Petstore Checklist Setup Guide - AIエージェント开发最佳实践","ja":"ペットストア チェックリスト セットアップ ガイド - AIエージェント開発のベストプラクティス","ko":"펫스토어 체크리스트 설정 가이드 - AI 에이전트 개발 모범 사례","es":"Guía de configuración de petstore-checklist: Mejores prác...","fr":"Guide de configuration de petstore-checklist: Bonnes prat...","de":"Einrichtungsleitfaden für petstore-checklist: Best Practi...","pt":"Guia de Configuração do petstore-checklist: Melhores Prát...","ru":"Настройка petstore-checklist: Руководство по Использовани...","ar":"دليل إعداد petstore-checklist: إرشادات لاستخدام أدوات الذ..."},"description":{"en":"Discover how to implement petstore-checklist with best practices, fixing spec code bugs and using CSS classes for display control","zh":"了解petstore-checklist的技术细节，包括规则和代码实践，来优化您的AI开发","ja":"ペットストア チェックリストの技術的詳細を学び、ルールとコードの実践を最適化してAI開発を改善する","ko":"펫스토어 체크리스트의 기술 세부 사항을 알아보고 규칙 및 코드 관행을 최적화하여 AI 개발을 개선합니다","es":"Aprende a configurar y utilizar petstore-checklist de manera efectiva, con consejos y trucos para desarrolladores","fr":"Découvrez comment configurer et utiliser petstore-checklist de manière efficace, avec des conseils et astuces pour les développeurs","de":"Erfahren Sie, wie Sie petstore-checklist effektiv konfigurieren und verwenden, mit Tipps und Tricks für Entwickler","pt":"Aprenda a configurar o petstore-checklist com as melhores práticas para desenvolvedores, incluindo dicas para substituir código inválido e uso de CSS","ru":"Узнайте, как настроить petstore-checklist с помощью руководства по использованию ИИ Агентов, включая советы по замене недопустимого кода и использованию CSS","ar":"تعرف على كيفية إعداد petstore-checklist باستخدام دليل لاستخدام أدوات الذكاء الاصطناعي، بما في ذلك نصائح لاستبدال رمز غير صالح واستخدام CSS"},"definition":{"en":"petstore-checklist is a skill that ensures proper implementation of session specs, replacing style.display patterns with CSS classes and removing onclick attributes","zh":"petstore-checklist是一种AI工具，用于规范开发过程中的代码和规则","ja":"ペットストア チェックリストは、開発プロセスの中でのコードとルールを規定するAIエージェントの一種です","ko":"펫스토어 체크리스트는 개발 프로세스에서 코드와 규칙을 규정하는 AI 에이전트의 일종입니다","es":"petstore-checklist es un conjunto de reglas y patrones para desarrolladores, que ayuda a crear experiencias de usuario personalizadas y accesibles","fr":"petstore-checklist est un ensemble de règles et de modèles pour les développeurs, qui aide à créer des expériences utilisateur personnalisées et accessibles","de":"petstore-checklist ist ein Satz von Regeln und Mustern für Entwickler, der hilft, personalisierte und zugängliche Benutzererfahrungen zu erstellen","pt":"O que é petstore-checklist? É uma coleção de regras para desenvolvedores que visa melhorar a experiência do usuário.","ru":"Что такое petstore-checklist? Это коллекция правил для разработчиков, направленная на улучшение пользовательского опыта.","ar":"ما هو petstore-checklist؟ هو مجموعة من القواعد للمطورين التي تهدف إلى تحسين تجربة المستخدم."},"features":{"en":["Replaces style.display patterns with CSS classes for display control","Removes onclick HTML attributes for proper event binding","Scans spec code for bugs before implementation","Uses addEventListener for binding events","Fixes spec code bugs before writing new code"],"zh":["使用CSS类替代style.display属性","移除onclick HTML属性，使用addEventListen绑定事件","遵循CLAUDE.md规则开发","修复Spec Code中的bugs","使用会话文件读写数据"],"ja":["style.display属性をCSSクラスで置き換える","onclick HTML属性を削除し、addEventListenでイベントをバインドする","CLAUDE.mdルールに従った開発","Spec Codeのバグを修正する","セッションファイルを使用してデータを読み書きする"],"ko":["style.display 속성을 CSS 클래스로 대체","onclick HTML 속성을 제거하고 addEventListen으로 이벤트를 바인딩","CLAUDE.md 규칙에 따른 개발","Spec Code의 버그를 수정","세션 파일을 사용하여 데이터를 읽고 쓸 수 있음"],"es":["Reemplazo de patrones de código para mejorar la accesibilidad","Uso de clases CSS para controlar la visualización de elementos","Eliminación de atributos HTML onclick para mejorar la seguridad","Implementación de eventos con addEventListener para mejorar la interactividad","Corrección de errores en el código de sesión para garantizar la estabilidad"],"fr":["Remplacement de modèles de code pour améliorer l''accessibilité","Utilisation de classes CSS pour contrôler l''affichage des éléments","Suppression d''attributs HTML onclick pour améliorer la sécurité","Mise en œuvre d''événements avec addEventListener pour améliorer l''interactivité","Correction d''erreurs dans le code de session pour garantir la stabilité"],"de":["Ersetzen von Code-Mustern, um die Zugänglichkeit zu verbessern","Verwendung von CSS-Klassen, um die Anzeige von Elementen zu steuern","Entfernen von HTML-attributen onclick, um die Sicherheit zu verbessern","Implementierung von Ereignissen mit addEventListener, um die Interaktivität zu verbessern","Korrektur von Fehlern im Sitzungscode, um die Stabilität zu gewährleisten"],"pt":["Substituição de código inválido por CSS","Uso de classes CSS para melhorar a experiência do usuário","Remoção de atributos onclick","Uso de addEventListener para bind de eventos","Leitura de arquivos de sessão para confirmar regras"],"ru":["Замена недопустимого кода на CSS","Использование классов CSS для улучшения пользовательского опыта","Удаление атрибутов onclick","Использование addEventListener для привязки событий","Чтение файлов сессии для подтверждения правил"],"ar":["استبدال رمز غير صالح ب CSS","استخدام فئات CSS لتحسين تجربة المستخدم","إزالة سمات onclick","استخدام addEventListener للربط الأحداث","قراءة ملفات الجلسة لتأكيد القواعد"]},"keywords":{"en":["how to use petstore-checklist","petstore-checklist setup guide","what is petstore-checklist","petstore-checklist alternative","petstore-checklist vs other skills","petstore-checklist install","fixing spec code bugs","using CSS classes for display control","proper event binding with addEventListener"],"zh":["AI工具开发","petstore-checklist","CLAUDE.md规则","CSS类","addEventListen","Spec Code调试","会话文件读写","AIエージェント开发","前端开发最佳实践"],"ja":["AIエージェント開発","ペットストア チェックリスト","CLAUDE.mdルール","CSSクラス","addEventListen","Spec Codeデバッグ","セッションファイル読み書き","フロントエンド開発ベストプラクティス","AIツール開発"],"ko":["AI 에이전트 개발","펫스토어 체크리스트","CLAUDE.md 규칙","CSS 클래스","addEventListen","Spec Code 디버깅","세션 파일 읽기 쓰기","프론트엔드 개발 모범 사례","AI 툴 개발"],"es":["petstore-checklist","desarrollo de juegos","accesibilidad web","CSS","JavaScript","addEventListen","patrones de código","seguridad web","experiencia de usuario"],"fr":["petstore-checklist","développement de jeux","accessibilité web","CSS","JavaScript","addEventListen","modèles de code","sécurité web","expérience utilisateur"],"de":["petstore-checklist","Spielentwicklung","Web-Zugänglichkeit","CSS","JavaScript","addEventListen","Code-Muster","Web-Sicherheit","Benutzererfahrung"],"pt":["petstore-checklist","desenvolvimento web","CSS","JavaScript","melhores práticas","desenvolvedores","experiência do usuário","otimização de código"],"ru":["petstore-checklist","веб-разработка","CSS","JavaScript","лучшие практики","разработчики","пользовательский опыт","оптимизация кода","ИИ Агенты"],"ar":["petstore-checklist","تطوير الويب","CSS","JavaScript","أفضل الممارسات","المطورين","تجربة المستخدم","تحسين الكود","أدوات الذكاء الاصطناعي"]}},"owner":"a1flecke","repo":"games-for-my-kids","repoPath":"a1flecke/games-for-my-kids","stars":0,"forks":0,"updatedAt":"2026-03-07T09:52:21Z","topics":[],"category":"community","skillMd":{"name":"petstore-checklist","description":"Pre-implementation checklist for lizzies-petstore sessions. Prints the coding rules most likely to cause bugs. Run this before writing any session code.","bodyPreview":"Read the session file, then confirm each rule below before writing code.\n\n## Spec Code Has Bugs — Fix Before Implementing\n\nSession specs often contain code samples that violate CLAUDE.md rules. Before using any code sample from the spec, scan it for these patterns and replace them:\n\n| Spec pattern | Fix |\n|---|---|\n| `style.display = ''none''` / `''block''` / `''flex''` | Use a CSS class instead (`.active`, `.open`, `.hidden`) |\n| `onclick=\"...\"` HTML attribute | Remove attr; bind with `addEventListen","body":"Read the session file, then confirm each rule below before writing code.\n\n## Spec Code Has Bugs — Fix Before Implementing\n\nSession specs often contain code samples that violate CLAUDE.md rules. Before using any code sample from the spec, scan it for these patterns and replace them:\n\n| Spec pattern | Fix |\n|---|---|\n| `style.display = ''none''` / `''block''` / `''flex''` | Use a CSS class instead (`.active`, `.open`, `.hidden`) |\n| `onclick=\"...\"` HTML attribute | Remove attr; bind with `addEventListener` in JS |\n| `.onclick = () => ...` | Use `addEventListener` — no stacking risk |\n| `.sort(() => Math.random() - 0.5)` | Fisher-Yates (see Shuffling section) |\n| `color: #636e72` | `color: var(--text-secondary)` |\n| `localStorage.getItem / .setItem` | `SaveManager.load()` / `SaveManager.save()` with key `lizzies-petstore-save` |\n| `window.x = window.x \\|\\| new X()` | `window.x = new X()` in `game.init()` — always fresh |\n| `new AudioContext()` in constructor | Create lazily on first `_getCtx()` call; `ctx.resume().then(() => schedule())` |\n| Independent `requestAnimationFrame` in a manager | Only `game.js` owns the RAF loop — expose `update(dt)` and `draw(ctx, w, h)` |\n| `touchstart` / `touchmove` / `touchend` | Use Pointer Events: `pointerdown` / `pointermove` / `pointerup` |\n| `Math.random()` in cached texture generation | Use seeded PRNG (`_seededRandom(hash)`) so re-cache produces identical results |\n| `globalAlpha < 1` then `source-atop` compositing | Draw fully opaque first, apply covering/pattern, then reduce alpha in a separate step |\n| `escHtml()` on `setAttribute(''aria-label'', ...)` | Don''t escape — `setAttribute` doesn''t parse HTML entities; `&amp;` reads literally to AT |\n| `timer % interval < threshold` on float timer | Use interval counter: `if (timer >= nextTime) { nextTime += interval; }` |\n| `aria-pressed` on `role=\"option\"` elements | Use `aria-selected` — `aria-pressed` is for toggle buttons, not listbox options |\n| `role=\"listitem\"` on `<button>` elements | Remove — `role=\"listitem\"` overrides implicit button role, breaking AT |\n| `aria-live` + `aria-hidden` on same element | Remove `aria-live`; `role=\"status\"` implies it. Toggling `aria-hidden` on a live region causes phantom AT announcements |\n| `SaveManager.load()`/`getCreature()` per frame | Cache on state entry: `this._cachedCreature = saveManager.getCreature(id)` |\n| LRU/indexOf/splice in draw loop | Only update LRU on build/invalidate, never in draw/update (hot path) |\n| Static background redrawn per frame | Cache to offscreen canvas on init/resize; `drawImage()` per frame |\n| `ctx.save()`/`ctx.restore()` per particle | Batch: set `globalAlpha` directly per particle, reset once at end |\n\n---\n\n## Canvas Performance Rules\n\n### Offscreen Caching (CreatureCache)\n- Each body part rendered once to its own offscreen canvas at display size × DPR\n- `invalidatePart(slot)` re-renders only the changed part — never re-cache all parts\n- Game loop composites via `drawImage()` — a single GPU-accelerated call per part\n- Covering textures pre-rendered as separate texture canvases — one-time cost\n- Max **30 offscreen canvases** active — LRU evict if exceeded\n\n### No DOM During Gameplay\n- All gameplay rendering on Canvas — no `createElement`, `innerHTML`, `classList` during the RAF loop\n- DOM overlays (needs meters, buttons) updated only on value change, not every frame\n\n### RAF Delta Time\n- Always `requestAnimationFrame` with delta time for movement/animation\n- Cap delta at **50ms** for iPad Safari RAF throttling\n- Never use `setInterval` for the game loop\n\n---\n\n## Timer Lifecycle Pattern\n\nEvery manager with `setTimeout`/`setInterval` must follow this pattern exactly:\n\n```js\nclass SomeManager {\n    constructor() {\n        this._mainTimer = null;\n        this.onComplete = null;\n    }\n    cancel() {\n        clearTimeout(this._mainTimer); this._mainTimer = null;\n        this.onComplete = null;\n    }\n    complete() {\n        const cb = this.onComplete;\n        this.cancel();\n        if (cb) cb();\n    }\n    start(...) { this.cancel(); /* init */ }\n}\n```\n\n---\n\n## Touch Input Rules\n\n- **Pointer Events** only (`pointerdown/move/up`) — never touch events\n- CSS `touch-action: none` on canvas\n- `setPointerCapture()` for drag tracking\n- Coordinate conversion: `(clientX - rect.left) * (canvas.width / rect.width)`\n- **60px minimum hitboxes** for body parts in creator\n- **50px snap radius** for attachment points\n\n---\n\n## Web Audio API (iOS Safari)\n\n- `AudioContext` created lazily on first user gesture — never in constructor\n- `ctx.resume().then(() => schedule())` — oscillators inside `.then()`\n- Sine waves only + low-pass filter for creature voices\n- `speechSynthesis.cancel()` + 50ms delay before `speak()` if used\n\n---\n\n## Screen Visibility\n\n- **Screens** → `.active` class\n- **Overlays** (settings, wardrobe panel) → `.open` class\n- **Internal toggles** → `.hidden` class\n- Never `style.display` in JS\n\n---\n\n## Modal Dialogs\n\n- `role=\"dialog\"`, `aria-modal=\"true\"`, `aria-label=\"...\"`\n- First focusable element = close button\n- Focus trap: Tab/Shift-Tab cycles within overlay\n- Escape to close (with `.contains(''open'')` guard)\n- On close: return focus to trigger element\n- `aria-hidden` always explicit `''true''`/`''false''` — never `removeAttribute`\n\n---\n\n## State Machine\n\n```\nTITLE → CREATOR → BIRTH_ANIMATION → CARE (hub) → PARK\n                                   ↕ WARDROBE\n                                   ↕ ROOM_EDIT\n  GALLERY ↔ CARE\n  GALLERY → CREATOR (edit existing)\n```\n\n- State transitions cancel all active timers/animations\n- Confirmation dialog when leaving CREATOR with unsaved changes\n- Document for each new state: entry/exit states, game loop behavior, input handling\n\n---\n\n## Single RAF Chain — game.js Owns the Loop\n\nOnly `game.js` may call `requestAnimationFrame`. Every other class exposes:\n- `update(dt)` — advance state\n- `draw(ctx, w, h)` — render to canvas\n\n---\n\n## Z-Order Render Constant\n\n```js\nconst RENDER_ORDER = [''legs'', ''tail'', ''torso'', ''wings'', ''head'', ''eyes'', ''extras'', ''accessories''];\n```\n\n---\n\n## Animation: Pivot-Based\n\n- Each part has a pivot point + simple curves (sine rotation, bounce, scale)\n- `ctx.save()` / `ctx.restore()` must bracket every transform\n- Delta-time based, cap at 50ms\n\n---\n\n## Save System\n\n- **One key**: `lizzies-petstore-save` — always through SaveManager\n- Schema versioned: `schemaVersion: 1`\n- Auto-save debounced 2s\n- Backup every 5th save to `lizzies-petstore-save-backup`\n- `_defaults()` must include ALL keys read by game.js\n- Quota error → user-visible toast\n\n---\n\n## Needs Decay\n\n- Decay ONLY during active play (1pt / 2min / need)\n- Floor at **20** — never desperate\n- No real-time decay when app closed\n- On reopen: creature greets happily regardless of absence\n- Max decay capped at 24 hours\n\n---\n\n## Hot-Path Performance (60fps Draw/Update Loop)\n\nThe `_update(dt)` and `_draw()` functions run 60×/sec. Never do expensive or allocating work inside them:\n\n- **No `SaveManager.load()` or `getCreature()` per frame** — cache the creature ref on state entry\n- **No LRU tracking in draw calls** — only update on `buildCache()` / `invalidatePart()`\n- **Cache static backgrounds** (grid dots, gradients) to offscreen canvas — `drawImage()` per frame\n- **No per-particle `ctx.save()`/`ctx.restore()`** — set `globalAlpha` directly, reset once at end\n- **No `document.createElement()`** — all DOM creation in setup code\n\n---\n\n## Seeded PRNG for Cached Textures\n\nAny procedurally generated texture cached to an offscreen canvas must use a seeded PRNG (not `Math.random()`). Otherwise LRU eviction + re-cache produces different visuals.\n\nSeed from a hash of partId + color for deterministic results.\n\n---\n\n## source-atop Compositing Requires Opaque Base\n\nWhen using `globalCompositeOperation = ''source-atop''`, the base shape must be fully opaque. Semi-transparent base pixels cause `base_alpha × texture_alpha` blending — visually wrong.\n\nIf you need translucent final result: draw opaque → apply covering/pattern → composite the result at reduced alpha in a separate step.\n\n---\n\n## Periodic Effects: Interval Counters Not Modulus\n\n`timer % 100 < 20` on a float is unreliable. Use an explicit next-time counter:\n```js\nif (this._timer >= this._nextSparkleTime) {\n    this._nextSparkleTime = this._timer + 100;\n    spawnSparkle();\n}\n```\n\n---\n\n## Shuffling\n\nNever `.sort(() => Math.random() - 0.5)`. Fisher-Yates:\n```js\nfor (let i = arr.length - 1; i > 0; i--) {\n    const j = Math.floor(Math.random() * (i + 1));\n    [arr[i], arr[j]] = [arr[j], arr[i]];\n}\n```\n\n---\n\n## WCAG Non-Negotiables\n\n- Never `user-scalable=no` in viewport meta\n- Touch targets >= 44px (60px for Creator palette)\n- Font: OpenDyslexic via CDN `<link>`, Comic Sans MS fallback\n- Min font size: 16px, line height 1.5×\n- Background: cream `#F5F0E8`, text: `#2C2416`, secondary: `#595143`\n- WCAG AA 4.5:1 — never `#666`, `#888`, `#999` on cream\n- No flashing/strobing\n- `ctx.font` always includes fallback: `''16px OpenDyslexic, \"Comic Sans MS\", cursive''`\n\n---\n\n## CSS ID Specificity\n\nNever put `display:` in a base ID rule:\n```css\n/* BAD */\n#screen-title { display: flex; }\n/* GOOD */\n#screen-title.active { display: flex; }\n```\n\n---\n\n## Session Spec Validation\n\nBefore implementing:\n1. Scan spec code samples against the pattern table above\n2. Confirm canvas rendering ownership is stated (game.js calls render, not manager)\n3. New state machine states must document transitions\n4. Default settings must have a rationale\n"},"lastSynced":"2026-03-07T13:06:07.117Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing bug-free code implementation and proper event binding for pet store applications.","zh":"非常适合需要无 bugs 代码实现和适当事件绑定的前端代理，特别是宠物店应用。","ja":"フロントエンドエージェントがバグのないコード実装と適切なイベントバインドを必要とする場合、特にペットストアアプリケーションに最適です。","ko":"버그가 없는 코드 구현과 적절한 이벤트 바인딩이 필요한 프론트엔드 에이전트에 적합합니다. 특히,宠物店 애플리케이션에 적합합니다.","es":"Ideal para agentes front-end que necesitan implementación de código libre de errores y enlace de eventos adecuado para aplicaciones de tiendas de mascotas.","fr":"Parfait pour les agents frontend nécessitant une mise en œuvre de code sans bogues et un lien d''événements approprié pour les applications de magasins d''animaux de compagnie.","de":"Perfekt für Frontend-Agents, die eine fehlerfreie Codeimplementierung und eine ordnungsgemäße Ereignisbindung für Tierhandelsanwendungen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de implementação de código sem bugs e associação de eventos adequada para aplicações de pet shop.","ru":"Идеально подходит для фронтенд-агентов, которым необходима реализация кода без ошибок и правильная привязка событий для приложений зоомагазина.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى تنفيذ رمز خالي من الأخطاء وربط حدث مناسب لتطبيقات متجر الحيوانات الأليفة."},"recommendation":{"en":"Empowers agents to implement session specs with clean code, replacing inline styles with CSS classes and binding events with addEventListener, ensuring compliance with CLAUDE.md rules and promoting maintainable codebases.","zh":"赋予代理实现会话规格的能力，使用干净的代码，替换内联样式为 CSS 类，并使用 addEventListener 绑定事件，确保遵守 CLAUDE.md 规则并促进可维护的代码库。","ja":"エージェントにセッション仕様を実装する能力を付与し、クリーンなコードを使用してインラインスタイルを CSS クラスに置き換え、addEventListener を使用してイベントをバインドし、CLAUDE.md ルールに準拠してメンテナブルなコードベースを促進します。","ko":"에이전트가 세션 규격을 구현할 수 있는 능력을 부여하여 깨끗한 코드를 사용하고 내부 스타일을 CSS 클래스로 대체하고 addEventListener를 사용하여 이벤트를 바인딩하여 CLAUDE.md 규칙을 준수하고 유지 보수 가능한 코드베이스를 촉진합니다.","es":"Habilita a los agentes a implementar especificaciones de sesión con código limpio, reemplazando estilos en línea con clases CSS y enlazando eventos con addEventListener, garantizando el cumplimiento de las reglas de CLAUDE.md y promoviendo bases de código mantenibles.","fr":"Permet aux agents de mettre en œuvre des spécifications de session avec du code propre, en remplaçant les styles intégrés par des classes CSS et en liant les événements avec addEventListener, garantissant le respect des règles de CLAUDE.md et promouvant des bases de code maintainables.","de":"Ermächtigt Agenten, Sitzungsspezifikationen mit sauberen Code zu implementieren, indem Inline-Stile durch CSS-Klassen ersetzt und Ereignisse mit addEventListener gebunden werden, um die Einhaltung der CLAUDE.md-Regeln zu gewährleisten und wartbare Codebasen zu fördern.","pt":"Habilita os agentes a implementar especificações de sessão com código limpo, substituindo estilos embutidos por classes CSS e vinculando eventos com addEventListener, garantindo conformidade com as regras do CLAUDE.md e promovendo bases de código mantidas.","ru":"Наделяет агентов возможностью реализовывать спецификации сеанса с чистым кодом, заменяя встроенные стили на классы CSS и привязывая события с помощью addEventListener, обеспечивая соответствие правилам CLAUDE.md и продвигая поддерживаемые кодовые базы.","ar":"يمنح العميل القدرة على تنفيذ مواصفات الجلسة مع رمز نظيف، واستبدال الأشكال المضمنة بفئات CSS وربط الأحداث باستخدام addEventListener، وضمان الامتثال للقواعد CLAUDE.md وتعزيز قواعد الرمز القابلة للصيانة."},"useCases":{"en":["Debugging session specs for pet store applications","Implementing bug-free code for pet store sessions","Binding events with addEventListener for interactive pet store elements"],"zh":["调试宠物店应用会话规格","为宠物店会话实现无 bugs 代码","使用 addEventListener 为交互式宠物店元素绑定事件"],"ja":["ペットストアアプリケーションのセッション仕様をデバッグする","ペットストアセッションのバグのないコードを実装する","addEventListener を使用してインタラクティブなペットストア要素にイベントをバインドする"],"ko":["펫스토어 애플리케이션의 세션 규격을 디버깅하는 것","펫스토어 세션을 위한 버그가 없는 코드를 구현하는 것","addEventListener를 사용하여 상호 작용하는 펫스토어 요소에 이벤트를 바인딩하는 것"],"es":["Depuración de especificaciones de sesión para aplicaciones de tiendas de mascotas","Implementación de código libre de errores para sesiones de tiendas de mascotas","Enlace de eventos con addEventListener para elementos interactivos de tiendas de mascotas"],"fr":["Débogage des spécifications de session pour les applications de magasins d''animaux de compagnie","Mise en œuvre de code sans bogues pour les sessions de magasins d''animaux de compagnie","Liaison d''événements avec addEventListener pour les éléments interactifs de magasins d''animaux de compagnie"],"de":["Fehlersuche bei Sitzungsspezifikationen für Tierhandelsanwendungen","Implementierung fehlerfreien Codes für Tierhandelssitzungen","Ereignisbindung mit addEventListener für interaktive Tierhandelselemente"],"pt":["Depuração de especificações de sessão para aplicações de pet shop","Implementação de código sem bugs para sessões de pet shop","Vinculação de eventos com addEventListener para elementos interativos de pet shop"],"ru":["Отладка спецификаций сеанса для приложений зоомагазина","Реализация кода без ошибок для сеансов зоомагазина","Привязка событий с помощью addEventListener для интерактивных элементов зоомагазина"],"ar":["تصحيح أخطاء مواصفات الجلسة لتطبيقات متجر الحيوانات الأليفة","تنفيذ رمز خالي من الأخطاء للجلسات في متجر الحيوانات الأليفة","ربط الأحداث باستخدام addEventListener للعناصر التفاعلية في متجر الحيوانات الأليفة"]},"limitations":{"en":["Requires manual scanning of spec code for patterns to replace","Limited to HTML and CSS applications","Needs adherence to CLAUDE.md rules for optimal performance"],"zh":["需要手动扫描规格代码以查找替换模式","仅限于 HTML 和 CSS 应用","需要遵守 CLAUDE.md 规则以实现最佳性能"],"ja":["パターンを置き換えるために仕様コードを手動でスキャンする必要がある","HTML と CSS アプリケーションにのみ限られる","最適なパフォーマンスを実現するために CLAUDE.md ルールに準拠する必要がある"],"ko":["패턴을 대체하기 위해 규격 코드를 수동으로 스캔해야 함","HTML 및 CSS 애플리케이션에만 제한됨","최적의 성능을 달성하기 위해 CLAUDE.md 규칙을 준수해야 함"],"es":["Requiere un escaneo manual de código de especificación para patrones de reemplazo","Limitado a aplicaciones HTML y CSS","Necesita adherirse a las reglas de CLAUDE.md para un rendimiento óptimo"],"fr":["Nécessite un balayage manuel du code de spécification pour les modèles de remplacement","Limité