INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ngocsangyem/todos-app-playwright/ck:skill-creator', 'ck:skill-creator', 'ngocsangyem', 'todos-app-playwright', 'community', 'ck:skill-creator ngocsangyem todos-app-playwright community 使用Playwright构建Todos App，实现自动化测试和高效开发。 Playwrightを使用してTodos Appを構築し、自動化テストと効率的な開発を実現します。 Playwright를 사용하여 Todos App을 구축하고 자동화 테스트 및 효율적인 개발을 실현합니다. La aplicación de lista de tareas utiliza Playwright para pruebas automatizadas, permitiendo a los desarrolladores crear aplicaciones más robustas L''application de liste de tâches utilise Playwright pour des tests automatisés, permettant aux développeurs de créer des applications plus robustes Die Todo-App verwendet Playwright für automatisierte Tests, damit Entwickler robustere Anwendungen erstellen können A ferramenta de IA ck:skill-creator permite criar aplicações de Todos com testes automatizados utilizando Playwright ИИ Агент ck:skill-creator позволяет создавать приложения для тестирования с автоматизированными тестами на Playwright أداة الذكاء الاصطناعي ck:skill-creator تمكن من إنشاء تطبيقات اختبار التطبيقات مع اختبارات آلية باستخدام Playwright A Todos App using Playwright for testing 如何使用Playwright 什么是AI智能工具 Todos App构建方法 Playwright自动化测试 AI智能工具安装 Playwright vs Selenium Todos App开发教程 A Todos App using Playwright for testing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lorehq/lore/lore-field-repair', 'community', 'lorehq', 'lore', 'lorehq/lore', 'lore-field-repair', 16, 0, 45, '2026-03-03T08:44:10Z', '2026-03-04T01:54:27.901Z', '320d35c5943671f857f8bca68d4c47ca1319c6f0311bb483c92532a179effdf1', '{"id":"lorehq/lore/lore-field-repair","name":"lore-field-repair","description":{"zh":"lore-field-repair帮助您的AI智能代理在会话间保留知识，解决遗忘问题","ja":"lore-field-repairは、会話間でAIエージェントの知識を保持し、忘却問題を解決します","ko":"lore-field-repair는 세션 간에 AI 에이전트의 지식을 유지하고 잊어버림 문제를 해결합니다","es":"Lore-field-repair es una solución para agentes de codificación AI que olvidan todo entre sesiones. Mejora la productividad y el rendimiento con esta herramienta de desarrollo innovadora","fr":"Lore-field-repair est une solution pour les agents de codage IA qui oublient tout entre les sessions. Améliorez la productivité et les performances avec cet outil de développement innovant","de":"Lore-field-repair ist eine Lösung für KI-Coding-Agents, die alles zwischen den Sitzungen vergessen. Steigern Sie die Produktivität und Leistung mit diesem innovativen Entwicklungstool","pt":"O reparo de campo de conhecimento resolve o problema de esquecimento do agente de codificação entre sessões.","ru":"Ремонт полей знаний решает проблему забывания кодировочного агента между сессиями.","ar":"إصلاح حقل المعرفة يحل مشكلة نسيان وكيل الترميز بين الجلسات.","en":"Your coding agent forgets everything between sessions. Lore fixes that."},"seo":{"title":{"zh":"AI智能代理lore-field-repair","ja":"AIエージェントの知識管理：lore-field-repair","ko":"AI 에이전트를 위한 지식 관리: lore-field-repair","es":"Agente AI: Reparación de lore-field para desarrolladores","fr":"Agent IA : Réparation de lore-field pour les développeurs","de":"KI-Agent: Lore-Field-Reparatur für Entwickler","pt":"Reparo de Campo de Conhecimento - Ferramentas de Agente d...","ru":"ИИ Агенты: Ремонт Полей Знаний","ar":"إصلاح حقل المعرفة - أدوات وكلاء الذكاء الاصطناعي","en":"lore-field-repair"},"description":{"zh":"lore-field-repair帮助您的AI智能代理在会话间保留知识，解决遗忘问题","ja":"lore-field-repairは、会話間でAIエージェントの知識を保持し、忘却問題を解決します","ko":"lore-field-repair는 세션 간에 AI 에이전트의 지식을 유지하고 잊어버림 문제를 해결합니다","es":"Lore-field-repair es una solución para agentes de codificación AI que olvidan todo entre sesiones. Mejora la productividad y el rendimiento con esta herramie...","fr":"Lore-field-repair est une solution pour les agents de codage IA qui oublient tout entre les sessions. Améliorez la productivité et les performances avec cet ...","de":"Lore-field-repair ist eine Lösung für KI-Coding-Agents, die alles zwischen den Sitzungen vergessen. Steigern Sie die Produktivität und Leistung mit diesem in...","pt":"O reparo de campo de conhecimento resolve o problema de esquecimento do agente de codificação entre sessões.","ru":"Ремонт полей знаний решает проблему забывания кодировочного агента между сессиями.","ar":"إصلاح حقل المعرفة يحل مشكلة نسيان وكيل الترميز بين الجلسات.","en":"Your coding agent forgets everything between sessions. Lore fixes that."},"definition":{"en":"Your coding agent forgets everything between sessions. Lore fixes that."},"features":{"zh":["会话间知识保留","AI智能代理的知识管理","解决遗忘问题","增强开发效率","支持多种开发框架"],"ja":["会話間の知識の保持","AIエージェントの知識管理","忘却問題の解決","開発効率の向上","多種の開発フレームワークのサポート"],"ko":["세션 간 지식 유지","AI 에이전트의 지식 관리","잊어버림 문제 해결","개발 효율성 향상","다양한 개발 프레임워크 지원"],"es":["Solución para el olvido de sesiones en agentes de codificación AI","Mejora de la productividad y el rendimiento","Integración con herramientas de desarrollo innovadoras","Compatibilidad con frameworks y bibliotecas populares","Fácil instalación y configuración","Soporte técnico y documentación detallada"],"fr":["Solution pour le problème d''oubli de sessions dans les agents de codage IA","Amélioration de la productivité et des performances","Intégration avec des outils de développement innovants","Compatibilité avec des frameworks et des bibliothèques populaires","Installation et configuration faciles","Support technique et documentation détaillée"],"de":["Lösung für das Problem des Sitzungsverlusts in KI-Coding-Agents","Steigerung der Produktivität und Leistung","Integration mit innovativen Entwicklungstools","Kompatibilität mit beliebten Frameworks und Bibliotheken","Einfache Installation und Konfiguration","Technischer Support und detaillierte Dokumentation"],"pt":["Manutenção do conhecimento adquirido","Melhoria da produtividade do agente de codificação","Integração com ferramentas de desenvolvimento","Suporte a múltiplos ambientes de codificação","Facilidade de uso e configuração"],"ru":["Сохранение приобретенных знаний","Улучшение производительности кодировочного агента","Интеграция с инструментами разработки","Поддержка нескольких сред кодирования","Легкость использования и настройки"],"ar":["الحفاظ على المعرفة المكتسبة","تحسين إنتاجية وكيل الترميز","التكامل مع أدوات التطوير","دعم بيئات ترميز متعددة","سهولة الاستخدام والتكوين"]},"keywords":{"zh":["AI智能代理","知识管理工具","会话间知识保留","如何使用lore-field-repair","lore-field-repair安装指南","AI智能代理的优点"],"ja":["AIエージェント","知識管理ツール","会話間の知識の保持","lore-field-repairの使い方","lore-field-repairのインストールガイド","AIエージェントのメリット"],"ko":["AI 에이전트","지식 관리 도구","세션 간 지식 유지","lore-field-repair 사용법","lore-field-repair 설치 가이드","AI 에이전트의 이점"],"es":["agente AI","herramientas de desarrollo","codificación AI","lore-field-repair","productividad","rendimiento","frameworks","bibliotecas","instalación","configuración","soporte técnico"],"fr":["agent IA","outils de développement","codage IA","lore-field-repair","productivité","performances","frameworks","bibliothèques","installation","configuration","support technique"],"de":["KI-Agent","Entwicklungstools","KI-Codierung","lore-field-repair","Produktivität","Leistung","Frameworks","Bibliotheken","Installation","Konfiguration","technischer Support"],"pt":["ferramentas de agente de ia","reparo de campo de conhecimento","como usar agente de codificação","o que é agente de ia","alternativas de agente de codificação","guia de instalação de agente de ia"],"ru":["инструменты ии агентов","ремонт полей знаний","как использовать кодировочный агент","что такое ии агент","альтернативы кодировочного агента","руководство по установке ии агента"],"ar":["أدوات وكلاء الذكاء الاصطناعي","إصلاح حقل المعرفة","كيفية استخدام وكيل الترميز","ما هو وكيل الذكاء الاصطناعي","بديلات وكيل الترميز","دليل تثبيت وكيل الذكاء الاصطناعي"]}},"owner":"lorehq","repo":"lore","repoPath":"lorehq/lore","stars":16,"forks":0,"updatedAt":"2026-03-03T08:44:10Z","topics":["ai","ai-agent","claude","coding-agent","cursor","developer-tools","framework","harness-engineering","knowledge-management","opencode"],"category":"community","skillMd":{"name":"lore-field-repair","description":"Guided workflow for diagnosing and fixing harness bugs in deployed instances","bodyPreview":"## MANDATES & CONSTRAINTS\n# Documentation Site Structure\n\nHow to organize navigation and content for the public documentation site (MkDocs Material).\n\n## 1. Use Diátaxis as a Writing Discipline\n\n**Every page serves one purpose: tutorial, how-to, reference, or explanation. Don''t mix them.**\n\n- **Tutorials** teach. The author leads, the reader follows. \"Build your first X\" — learning-oriented, step-by-step, always involves doing something concrete.\n- **How-to guides** solve. The reader has a goal,","body":"## MANDATES & CONSTRAINTS\n# Documentation Site Structure\n\nHow to organize navigation and content for the public documentation site (MkDocs Material).\n\n## 1. Use Diátaxis as a Writing Discipline\n\n**Every page serves one purpose: tutorial, how-to, reference, or explanation. Don''t mix them.**\n\n- **Tutorials** teach. The author leads, the reader follows. \"Build your first X\" — learning-oriented, step-by-step, always involves doing something concrete.\n- **How-to guides** solve. The reader has a goal, the guide assists. \"How to deploy to production\" — assumes competence, task-oriented, no hand-holding.\n- **Reference** describes. Exhaustive, factual, austere. Parameters, return types, defaults, examples. Consulted, not read.\n- **Explanation** clarifies. Background, architecture, design decisions, \"why.\" Deepens understanding without prescribing action.\n\nWhen a page feels bloated, you''re mixing types. A how-to guide that stops to explain architecture should link to an explanation page instead. A tutorial that lists every config option should link to the reference.\n\n## 2. Organize Navigation for the Reader, Not the Codebase\n\n**Users navigate by task and intent, not by your internal file structure.**\n\n- Top-level sections map to user intent: \"I''m new\" (Getting Started), \"I need to do X\" (Guides), \"I need the spec\" (Reference), \"I want to understand why\" (Concepts).\n- Don''t mirror your source tree, team structure, or module hierarchy in navigation. These force users to learn your internals before finding content.\n- Group by what users are trying to accomplish, not by what component implements it.\n\nStandard top-level sections, in order:\n\n| Section | Diátaxis Type | Content |\n|---------|---------------|---------|\n| Getting Started | Tutorial | Installation, first working example, core workflow. Under 5 minutes to \"aha.\" |\n| Guides | How-to | Task-oriented walkthroughs. One guide per goal. Assumes the reader finished Getting Started. |\n| Concepts | Explanation | Architecture, design decisions, mental models. No steps — just understanding. |\n| Reference | Reference | CLI commands, configuration options, API surface. Mirrors the structure of the thing it describes. |\n\nAdd sections only when the content doesn''t fit the four above. Changelog, migration guides, and troubleshooting are common additions. Don''t invent sections preemptively.\n\n## 3. Keep the Sidebar Shallow\n\n**Two sidebar levels. Three at most. Beyond that, users lose orientation.**\n\n- Use MkDocs Material''s `navigation.tabs` to render top-level sections as horizontal tabs. This adds one navigation level without deepening the sidebar.\n- Within each tab, the sidebar should be scannable at a glance — no scrolling to see the full list. If it scrolls, the section is too large; split it.\n- Group sidebar items into 5–8 item clusters using section headers. A wall of 30+ ungrouped links overwhelms.\n- Never nest deeper than 3 levels total (tab → section → page). Use section index pages to add breadth instead of depth.\n\n## 4. Give Every Section a Landing Page\n\n**Clicking a section should orient, not dump the reader on the first child page.**\n\n- Every `nav` section gets an `index.md` that explains what''s in the section and links to key pages.\n- Landing pages surface the 20% of pages that serve 80% of visits. Put the most-used links at the top.\n- Use MkDocs Material''s `navigation.indexes` feature to attach index pages to sections.\n\n## 5. Size Pages for Comprehension\n\n**One topic per page. 800–3,000 words. Enough to be useful, short enough to finish.**\n\n- If a page covers two unrelated things, split it. If two pages cover the same thing, merge and redirect.\n- Under 800 words usually means the page is a fragment that should be folded into a parent page.\n- Over 3,000 words usually means the page mixes Diátaxis types or covers multiple topics.\n- Link aggressively. Every mention of a concept, command, or component that has its own page should be a link.\n- End pages with \"Next steps\" or related links. Users should always know where to go from here.\n\n## 6. Make Getting Started Ruthlessly Short\n\n**One \"aha moment.\" Under 5 minutes. Nothing else.**\n\n- Installation, one working example, done. The quickstart is not a feature tour.\n- Cut prerequisites to the minimum. If the reader needs three tools installed before starting, provide a single copy-paste block.\n- Defer everything that isn''t required for the first success: configuration options, advanced features, architecture explanations. Link to them.\n- Test the quickstart on a clean machine. If any step fails or confuses, fix it before publishing anything else.\n\n## 7. Structure Reference to Mirror the System\n\n**Reference architecture follows the thing it describes, not the reader''s workflow.**\n\n- CLI reference mirrors the command tree. Config reference mirrors the config file structure. API reference mirrors the endpoint hierarchy.\n- Every entry: name, description, parameters/options, defaults, types, one example. Consistent format across all entries.\n- Don''t narrate. Reference is looked up, not read. Save the storytelling for explanation pages.\n- Keep reference auto-generated where possible. Hand-written reference drifts from the source.\n\n## 8. Configure MkDocs Material for This\n\n**Use the theme features that support this structure. Skip the ones that fight it.**\n\nEnable:\n\n- `navigation.tabs` + `navigation.tabs.sticky` — top-level sections as persistent horizontal tabs.\n- `navigation.sections` — visual grouping in the sidebar.\n- `navigation.indexes` — section landing pages.\n- `navigation.path` — breadcrumbs for orientation in deep structures.\n- `navigation.instant` — SPA-like page transitions (requires `site_url`).\n- `navigation.prune` — only render visible nav items. Essential past 100 pages.\n- `toc.follow` — auto-scroll the table of contents to the active heading.\n\nAvoid:\n\n- `navigation.expand` — auto-expands all sidebar sections. Defeats scanability on sites with more than a handful of pages.\n- `toc.integrate` — moves the table of contents into the sidebar. Incompatible with section indexes and clutters the nav.\n\n# Lore HQ\n\nKnowledge headquarters for the Lore project. Not a source repo — no published code lives here.\n\n## About\n\nThis is the operational brain for the entire Lore ecosystem. It tracks:\n\n- **Source repos:** lore (framework), create-lore (installer), lore-docs (docs site)\n- **Infrastructure:** GitHub org (`lorehq`), npm account, Cloudflare domain/DNS, Docker Hub namespace\n- **CI/CD:** GitHub Actions workflows across all repos, release processes, npm publishing\n- **Ecosystem mapping:** account ownership, identity separation, platform support matrix\n- **Work:** roadmaps, plans, brainstorms, and operational knowledge\n\nAll application/framework code changes happen in source repos. This repo holds the knowledge, tracks the work, and maps the ecosystem.\n\n## Agent Behavior\n\n- Be direct and concise. No filler, no hedging.\n- Code changes go in source repos, not here (unless it''s hooks or skills for this workspace).\n- You are responsible for the full operational surface: software development, devops, infrastructure, and ecosystem mapping.\n- Check `~/.lore/knowledge-base/environment/repo-relationships.md` for repo paths and roles.\n- Check `~/.lore/knowledge-base/environment/identity-separation.md` for accounts and ownership.\n- When in doubt about which repo to modify, ask.\n\n## Contributions vs Syncs\n\nSource code changes (hooks, scripts, skills, tests) go directly in the **lore source repo** (`/home/andrew/Github/lore`). Commit and push there first.\n\nTo pull framework updates INTO this instance (or any Lore instance), use `/lore-update` from the instance. Never run `sync-framework.sh` ad-hoc — it copies FROM the `<source>` argument INTO `$(pwd)`, and running it from the wrong directory silently overwrites source files with stale copies.\n\n- **Contributing:** Edit files in lore source → commit → push\n- **Syncing:** From the instance, run `/lore-update` (clones latest, syncs safely)\n- **Never:** `cd lore && bash scripts/sync-framework.sh /path/to/instance` — this goes backwards\n\n# Rules\n\nOperator preferences for how work is done. Each page covers a specific domain.\n\n# Security\n\nEvery file you write could be committed, leaked, or read by another agent. Act accordingly.\n\n## 1. Reference, Don''t Embed\n\n**Reference vaults and env var names — repos get leaked, and secrets in version history are permanent.**\n\n- This applies to passwords, API keys, tokens, private keys, and connection strings. Store the location (vault path, env var name, secret manager key), not the value itself.\n- `.env` files, credential JSONs, and key files belong in `.gitignore`. Before creating one, verify it''s listed.\n- If you encounter an exposed secret, flag it to the operator immediately. Don''t commit over it or move it.\n\nGood:\n- `DATABASE_URL` stored in Vaultwarden under \"app-database\" — load via `bw get`\n\nBad:\n- `DATABASE_URL=postgres://admin:s3cret@db.internal:5432/app`\n\n## 2. Sanitize What You Generate\n\n**Use obviously fake placeholders in examples and configs — generated values that look real become real problems.**\n\n- Use `example.com`, `TOKEN_HERE`, `<your-api-key>`, `sk-test-xxx` — patterns that are clearly not real.\n- When conversation context contains secrets (API keys, tokens, connection strings), reference the source instead of echoing values into files.\n- When delegating to workers, pass secret references (env var names, vault paths) — not values.\n- Don''t embed URLs containing auth tokens or session IDs.\n\n## 3. Validate at Boundaries\n\n**Trust internal code. Verify external input.**\n\n- Validate user input, API request bodies, webhook payloads, and anything from outside the system boundary.\n- Parameterize database queries. Escape output for the rendering context (HTML, shell, SQL).\n- Don''t add defensive validation inside internal function calls you control.\n\n## 4. Escalate Uncertainty\n\n**When uncertain whether data is sensitive, ask the operator before writing.**\n\n- Borderline cases — internal URLs, infrastructure hostnames, non-production credentials — are judgment calls. Escalate them.\n- When in doubt about whether a file should be gitignored, ask rather than guess.\n- If a task requires handling actual secrets, confirm the approach with the operator first.\n\n# Rules\n\nOperational rules and standards for this environment. Each page covers a specific domain.\n\n# ▆▆▆ [LORE-SECURITY-PROTOCOL] ▆▆▆\n\n## 1. Credential Protection\nEvery file you write could be committed, leaked, or read by another agent. Act accordingly.\n\n## 2. Reference, Don''t Embed\n**Reference vaults and env var names — repos get leaked, and secrets in version history are permanent.**\n- This applies to passwords, API keys, tokens, private keys, and connection strings. Store the location (vault path, env var name, secret manager key), not the value itself.\n- `.env` files, credential JSONs, and key files belong in `.gitignore`. Before creating one, verify it''s listed.\n- If you encounter an exposed secret, flag it to the operator immediately. Don''t commit over it or move it.\n\n## 3. Sanitize What You Generate\n**Use obviously fake placeholders in examples and configs — generated values that look real become real problems.**\n- Use `example.com`, `TOKEN_HERE`, `<your-api-key>`, `sk-test-xxx` — patterns that are clearly not real.\n- When conversation context contains secrets (API keys, tokens, connection strings), reference the source instead of echoing values into files.\n- When delegating to workers, pass secret references (env var names, vault paths) — not values.\n- Don''t embed URLs containing auth tokens or session IDs.\n\n## 4. Validate at Boundaries\n**Trust internal code. Verify external input.**\n- Validate user input, API request bodies, webhook payloads, and anything from outside the system boundary.\n- Parameterize database queries. Escape output for the rendering context (HTML, shell, SQL).\n- Don''t add defensive validation inside internal function calls you control.\n\n## 5. Escalate Uncertainty\n**When uncertain whether data is sensitive, ask the operator before writing.**\n- Borderline cases — internal URLs, infrastructure hostnames, non-production credentials — are judgment calls. Escalate them.\n- When in doubt about whether a file should be gitignored, ask rather than guess.\n- If a task requires handling actual secrets, confirm the approach with the operator first.\n\n# ▆▆▆ [LORE-SECURITY-PROTOCOL-END] ▆▆▆\n\n## USAGE\n# Field Repair\n\nDiagnose and fix a harness bug using the field repair workflow.\n\n## When to Use\n\nThe operator types `/lore-field-repair` when a hook, script, skill, or rule is broken in the current instance or a deployed instance reports a failure.\n\n## Process\n\n1. Load the field-repair rule: `.lore/rules/field-repair.md`\n2. Ask the operator:\n   - **What''s broken?** (hook error, skill failure, script crash, bad behavior)\n   - **How to reproduce?** (exact trigger — slash command, tool call, event)\n   - **Which repo likely owns this?** (lore, create-lore, lore-docker, lore-docs)\n3. Follow the rule steps in order:\n   - Reproduce → Isolate → Fix in source → Test → Push and sync → Report → Capture\n4. Use TaskCreate to track each step if the repair spans multiple turns\n\n## Snags\n\n- Debug output goes to `/tmp`, never stderr — stderr corrupts hook responses\n- Copy fixed files into the instance for testing, but revert before syncing\n- Always fix in the source repo, never patch the instance directly\n- Run `/lore-update` from the instance after pushing — never run sync scripts ad-hoc\n- The operator is your eyes — ask them to confirm behavior you can''t observe"},"lastSynced":"2026-03-04T01:54:27.901Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents needing persistent knowledge retention between sessions.","zh":"适用于需要在会话之间保留持久知识的编码代理。","ja":"セッション間で持続的な知識の保持が必要なコーディングエージェントに適しています。","ko":"세션 간 지속적인 지식 보유가 필요한 코딩 에이전트에 적합합니다.","es":"Perfecto para agentes de codificación que necesitan retención de conocimiento persistente entre sesiones.","fr":"Parfait pour les agents de codage nécessitant une rétention de connaissances persistante entre sessions.","de":"Perfekt für Codierungsagenten, die eine persistente Wissensspeicherung zwischen Sitzungen benötigen.","pt":"Perfeito para Agentes de Codificação que necessitam de retenção de conhecimento persistente entre sessões.","ru":"Идеально для Кодировочных Агентов, которым требуется постоянное сохранение знаний между сессиями.","ar":"مثالي لعمليات الترميز التي تتطلب استمرار الحفظ المعرفي بين الجلسات."},"recommendation":{"en":"Empowers agents to maintain a persistent knowledge base using Diátaxis writing discipline, organizing content into tutorials, how-to guides, reference, and explanation pages, and leveraging MkDocs Material for documentation site structure.","zh":"启用代理使用 Diátaxis 写作纪律维护持久的知识库，组织内容到教程、操作指南、参考和解释页面，并利用 MkDocs Material 进行文档站点结构。","ja":"Diátaxis 書き方規則を使用して、エージェントが持続的な知識ベースを維持できるようにし、コンテンツをチュートリアル、方法ガイド、リファレンス、説明ページに組織し、MkDocs Material を使用してドキュメント サイト構造を構築します。","ko":"에이전트가 Diátaxis 작성 규칙을 사용하여 지속적인 지식 베이스를 유지하도록 하며, 콘텐츠를 튜토리얼, 방법 가이드, 참조 및 설명 페이지로 구성하며, MkDocs Material을 사용하여 문서 사이트 구조를 구축합니다.","es":"Permite a los agentes mantener una base de conocimiento persistente utilizando la disciplina de escritura Diátaxis, organizando el contenido en tutoriales, guías de cómo hacer, referencia y páginas de explicación, y aprovechando MkDocs Material para la estructura del sitio de documentación.","fr":"Permet aux agents de maintenir une base de connaissances persistante en utilisant la discipline d''écriture Diátaxis, en organisant le contenu en tutoriels, guides de démarrage, référence et pages d''explication, et en exploitant MkDocs Material pour la structure du site de documentation.","de":"Ermöglicht es den Agenten, eine persistente Wissensbasis mithilfe der Diátaxis-Schreibdisziplin zu erhalten, indem sie den Inhalt in Tutorials, Anleitungen, Referenzen und Erklärungsseiten organisieren und MkDocs Material für die Struktur der Dokumentationswebsite nutzen.","pt":"Habilita os agentes a manter uma base de conhecimento persistente usando a disciplina de escrita Diátaxis, organizando o conteúdo em tutoriais, guias de como fazer, referência e páginas de explicação, e aproveitando o MkDocs Material para a estrutura do site de documentação.","ru":"Наделяет агентов возможностью поддерживать постоянную базу знаний с помощью дисциплины диатаксиса, организуя содержание в виде уроков, руководств, справочных материалов и страниц объяснений, а также использует MkDocs Material для структуры документационного сайта.","ar":"تمكّن الوكلاء من الحفاظ على قاعدة معرفية مستمرة باستخدام انضباط كتابة دياطاكسيس، وتنظيم المحتوى في دروس ومرشدين وكشافات وتفسيرات، واستغلال MkDocs Material لهيكل موقع الوثائق."},"useCases":{"en":["Organizing documentation sites with Diátaxis framework","Creating persistent knowledge bases for coding agents","Structuring navigation and content for public documentation sites"],"zh":["使用 Diátaxis 框架组织文档站点","为编码代理创建持久的知识库","为公共文档站点结构化导航和内容"],"ja":["Diátaxis フレームワークを使用してドキュメント サイトを整理する","コーディング エージェントのための持続的な知識ベースを作成する","パブリック ドキュメント サイトのナビゲーションとコンテンツを構造化する"],"ko":["Diátaxis 프레임워크를 사용하여 문서 사이트를 구성하는 것","코딩 에이전트를 위한 지속적인 지식 베이스 생성","공개 문서 사이트의 내비게이션 및 콘텐츠 구조화"],"es":["Organizar sitios de documentación con el framework Diátaxis","Crear bases de conocimiento persistentes para agentes de codificación","Estructurar la navegación y el contenido para sitios de documentación públicos"],"fr":["Organiser des sites de documentation avec le framework Diátaxis","Créer des bases de connaissances persistantes pour les agents de codage","Structurer la navigation et le contenu pour les sites de documentation publics"],"de":["Dokumentationsseiten mit dem Diátaxis-Framework organisieren","Persistente Wissensbasen für Codierungsagenten erstellen","Navigation und Inhalt für öffentliche Dokumentationsseiten strukturieren"],"pt":["Organizar sites de documentação com o framework Diátaxis","Criar bases de conhecimento persistentes para agentes de codificação","Estruturar navegação e conteúdo para sites de documentação públicos"],"ru":["Организация документационных сайтов с помощью фреймворка Diátaxis","Создание постоянных баз знаний для кодировочных агентов","Структуризация навигации и содержания для публичных документационных сайтов"],"ar":["تنظيم مواقع الوثائق باستخدام إطار دياطاكسيس","إنشاء قواعد معرفية مستمرة لوكلاء الترميز","هيكلة الملاحة والمحتوى لمواقع الوثائق العامة"]},"limitations":{"en":["Requires MkDocs Material for documentation site structure","Adherence to Diátaxis writing discipline"],"zh":["需要 MkDocs Material 进行文档站点结构","遵守 Diátaxis 写作纪律"],"ja":["ドキュメント サイト構造に MkDocs Material が必要","Diátaxis 書き方規則に従う"],"ko":["문서 사이트 구조를 위해 MkDocs Material이 필요함","Diátaxis 작성 규칙을 준수해야 함"],"es":["Requiere MkDocs Material para la estructura del sitio de documentación","Adhesión a la disciplina de escritura Diátaxis"],"fr":["Nécessite MkDocs Material pour la structure du site de documentation","Adhésion à la discipline d''écriture Diátaxis"],"de":["Benötigt MkDocs Material für die Struktur der Dokumentationswebsite","Einhaltung der Diátaxis-Schreibdisziplin"],"pt":["Exige MkDocs Material para a estrutura do site de documentação","Adesão à disciplina de escrita Diátaxis"],"ru":["Требует MkDocs Material для структуры документационного сайта","Соблюдение дисциплины диатаксиса"],"ar":["يتطلب MkDocs Material لهيكل موقع الوثائق","الامتثال لانضباط كتابة دياطاكسيس"]},"version":3},"contentHash":"320d35c5943671f857f8bca68d4c47ca1319c6f0311bb483c92532a179effdf1","qualityScore":45}');
