INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pacaplan/flokay/gauntlet-setup', 'gauntlet-setup', 'pacaplan', 'flokay', 'community', 'gauntlet-setup pacaplan flokay community Flokay 是一款提供 Agent Skills 和 OpenSpec 模式的 Claude 插件，用于开发 AI 智能代理工具 Flokay は AIエージェントのための Agent Skills と OpenSpec 構造を提供する Claude プラグインです Flokay는 AI 에이전트를 위한 Agent Skills와 OpenSpec 구조를 제공하는 Claude 플러그인입니다 Flokay es un plugin de Claude que proporciona un conjunto de habilidades de Agentes de IA y un esquema de OpenSpec para desarrollo guiado por especificaciones Flokay est un plugin Claude qui fournit un ensemble de compétences d''Outils d''IA et un schéma OpenSpec pour le développement piloté par des spécifications Flokay ist ein Claude-Plugin, das eine Reihe von Fähigkeiten für KI-Agents und ein OpenSpec-Schema für spezifikationsgesteuerte Entwicklung bereitstellt Flokay é um plugin do Claude que fornece um conjunto de habilidades de agente e um esquema OpenSpec para desenvolvimento orientado a especificações Flokay - это плагин Claude, который предоставляет набор навыков агента и схему OpenSpec для разработки, ориентированной на спецификации فلوكاي هو مكون إضافي من كلود الذي يوفر مجموعة من مهارات الوكيل ومخطط مواصفات مفتوحة للتنمية الموجهة بالمواصفات Flokay is a Claude plugin that provides a set of Agent Skills and an OpenSpec schema for spec-driven development. AI智能代理工具 Flokay Gauntlet Setup Agent Skills OpenSpec 模式 Claude 插件 AI开发框架 如何使用 Flokay Flokay 与其他工具的比较 Flokay is a Claude plugin that provides a set of Agent Skills and an OpenSpec schema for spec-driven development.');
