INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AutumnsGrove/Lattice/raven-investigate', 'raven-investigate', 'AutumnsGrove', 'Lattice', 'community', 'raven-investigate AutumnsGrove Lattice community blogging cloudflare indie-web nature-themed queer solarpunk sveltekit raven-investigate是一个基于SvelteKit的博客和社区工具，旨在打造一个更加宁静的网络角落 raven-investigateはSvelteKitを使用したブログとコミュニティツールで、より静かなネットワークの角を構築することを目的としています raven-investigate는 SvelteKit 기반의 블로그 및 커뮤니티 도구로 더 조용한 네트워크 구석을 구축하는 것을 목표로 합니다 Raven-investigate es un conjunto de herramientas de comunidad y escritura para un rincón más tranquilo de internet, con un enfoque en la tecnología SvelteKit y la plataforma Cloudflare Raven-investigate est un ensemble d''outils de communauté et d''écriture pour un coin plus calme de l''internet, avec un focus sur la technologie SvelteKit et la plateforme Cloudflare Raven-Investigate ist ein Set von Community- und Schreibtools für eine ruhigere Ecke des Internets, mit einem Fokus auf die Technologie SvelteKit und die Plattform Cloudflare O raven-investigate é uma ferramenta de escrita e comunidade que oferece um ambiente tranquilo para desenvolvedores, com foco em tecnologias como SvelteKit e Cloudflare raven-investigate - это инструмент для написания и сообщества, который предлагает спокойную среду для разработчиков, с фокусом на технологиях như SvelteKit и Cloudflare raven-investigate هو أداة للكتابة والمجتمع تقدم بيئة هادئة للمطورين، مع تركيز على تقنيات مثل SvelteKit و Cloudflare A forest of voices. Writing and community tools for a quieter corner of the internet. 如何使用raven-investigate 什么是solarpunk raven-investigate替代品 raven-investigate vs ghost raven-investigate安装 raven-investigate设置指南 基于云的博客工具 LGBTQ+社区支持 A forest of voices. Writing and community tools for a quieter corner of the internet.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('harikiran138/lumina-ai-learning/skill-creator', 'community', 'harikiran138', 'lumina-ai-learning', 'harikiran138/lumina-ai-learning', 'skill-creator', 0, 0, 45, '2026-03-07T01:49:01.470Z', '2026-03-07T01:56:12.023Z', 'd57b6e3a44535b9c0ef454dad5c86f5df78185fc80a65c7092885b4b5e10f81b', '{"id":"harikiran138/lumina-ai-learning/skill-creator","name":"skill-creator","description":{"en":"Skill-Creator provides guidance for creating effective skills, extending Claude''s capabilities with specialized knowledge and workflows. It benefits developers and educators seeking to create adaptive learning experiences","zh":"Skill Creator 是一个使用预测智能和认知分析的自适应学习伴侣，提供模块化和自包含的技能包","ja":"Skill Creator は、AIエージェントを使用した学習環境を構築するためのモジュール化されたスキルパッケージです","ko":"Skill Creator는 예측 인텔리전스와 인지 분석을 사용하여 적응형 학습 환경을 제공하는 모듈화된 스킬 패키지입니다","es":"Skill Creator es un compañero de aprendizaje de IA adaptativo que personaliza la educación a través del análisis cognitivo y la inteligencia predictiva, diseñado para hacer que el aprendizaje de calidad sea accesible para todos","fr":"Skill Creator est un compagnon d''apprentissage IA adaptatif qui personnalise l''éducation à travers l''analyse cognitive et l''intelligence prédictive, conçu pour rendre l''apprentissage de qualité accessible à tous","de":"Skill Creator ist ein adaptiver IA-Lernbegleiter, der die Ausbildung durch kognitive Analyse und prädiktive Intelligenz personalisiert, designed, um hochwertiges Lernen für alle zugänglich zu machen","pt":"O Skill-Creator é um companion de aprendizado adaptativo que fornece orientação para criar habilidades eficazes. Ele é offline-first, multilíngue e projetado para tornar o aprendizado de qualidade acessível a todos.","ru":"Skill-Creator — это адаптивный компаньон обучения, который предоставляет руководство по созданию эффективных навыков. Он офлайн-ориентирован, многоязычный и предназначен для того, чтобы качественное обучение было доступно всем с помощью ИИ Агентов.","ar":"Skill-Creator هو رفيق تعليمي ذكي يقدم إرشادات لإنشاء مهارات فعالة. وهو غير متصل بالإنترنت، متعددة اللغات، ومصمم لجعل التعلم النوعي متاحًا للجميع بالاعتماد على تقنيات الذكاء الاصطناعي."},"seo":{"title":{"en":"Skill-Creator: Adaptive Learning Companion Setup Guide | ...","zh":"Skill Creator 集成指南 - 使用预测智能构建自适应学习伴侣","ja":"Skill Creator セットアップガイド - AIエージェントを使用した学習環境の構築","ko":"Skill Creator 설정 가이드 - 예측 인텔리전스를 활용한 적응형 학습 동반자","es":"Guía de configuración de Skill Creator para desarrolladores","fr":"Guide de mise en place de Skill Creator pour les développ...","de":"Einrichtungsanleitung für Skill Creator-Entwickler","pt":"Guia de Configuração do Skill-Creator: Aprenda com um Com...","ru":"Настройка Skill-Creator: Адаптивный компаньон обучения с ...","ar":"دليل إعداد Skill-Creator: رفيق تعليمي ذكي مع تقنيات الذكا..."},"description":{"en":"Unlock personalized education with Skill-Creator, an offline-first AI learning companion. Discover how to create effective skills and transform Claude into a...","zh":"了解 Skill Creator 的功能和特点，使用预测智能和认知分析构建自适应学习环境","ja":"Skill Creator の機能と特徴を紹介します。AIエージェントを使用して学習環境を構築しましょう","ko":"Skill Creator의 기능과 특징을 살펴보세요. 예측 인텔리전스와 인지 분석을 사용하여 적응형 학습 환경을 구축합니다","es":"Aprende a crear habilidades personalizadas con Skill Creator, un compañero de aprendizaje de IA adaptativo que utiliza análisis cognitivo y inteligencia pred...","fr":"Découvrez comment créer des compétences personnalisées avec Skill Creator, un compagnon d''apprentissage IA adaptatif qui utilise l''analyse cognitive et l''int...","de":"Erfahren Sie, wie Sie mit Skill Creator, einem adaptiven IA-Lernbegleiter, der kognitive Analyse und prädiktive Intelligenz verwendet, personalisierte Fähigk...","pt":"Descubra como o Skill-Creator pode personalizar a educação com análise cognitiva e inteligência preditiva. Aprenda mais sobre essa ferramenta offline-first e...","ru":"Узнайте, как Skill-Creator может персонализировать образование с помощью когнитивного анализа и прогностической интеллекта. Подробнее об этом офлайн-инструме...","ar":"تعرف على كيفية عمل Skill-Creator في تخصيص التعليم باستخدام التحليل المعرفي والذكاء التحليلي. تعلم المزيد حول هذا الأداة غير متصل بالإنترنت ومتعددة اللغات."},"definition":{"en":"Skill-creator is an adaptive AI learning companion that personalizes education through cognitive analysis and predictive intelligence","zh":"Skill Creator 是一个使用预测智能的自适应学习伴侣","ja":"Skill Creator は、AIエージェントを使用した学習環境を構築するためのツールです","ko":"Skill Creator는 예측 인텔리전스를 사용하여 적응형 학습 환경을 제공하는 도구입니다","es":"Skill Creator es un agente de aprendizaje de IA que proporciona orientación para crear habilidades efectivas","fr":"Skill Creator est un agent d''apprentissage IA qui fournit des conseils pour créer des compétences efficaces","de":"Skill Creator ist ein IA-Lernagent, der Anleitung zur Erstellung effektiver Fähigkeiten bietet","pt":"O Skill-Creator é um companion de aprendizado adaptativo que utiliza análise cognitiva e inteligência preditiva para personalizar a educação.","ru":"Skill-Creator — это адаптивный компаньон обучения, который использует когнитивный анализ и прогностическую интеллекта для персонализации образования с помощью ИИ Агентов.","ar":"Skill-Creator هو رفيق تعليمي ذكي يستخدم التحليل المعرفي والذكاء التحليلي لتخصيص التعليم بالاعتماد على تقنيات الذكاء الاصطناعي."},"features":{"en":["Provides specialized workflows and procedural knowledge","Enables creation of modular, self-contained packages for Claude","Supports multilingual and offline-first learning experiences","Transforms Claude into a specialized agent with domain-specific knowledge","Offers guidance for creating effective skills through cognitive analysis"],"zh":["使用预测智能和认知分析","提供模块化和自包含的技能包","支持离线使用","支持多语言","提供专用化工作流程"],"ja":["AIエージェントを使用した学習環境の構築","モジュール化されたスキルパッケージの提供","オフラインでの使用をサポート","多言語をサポート","専用化されたワークフローを提供"],"ko":["예측 인텔리전스와 인지 분석을 사용","모듈화된 스킬 패키지를 제공","오프라인 사용을 지원","다국어를 지원","전문화된 워크플로우를 제공"],"es":["Análisis cognitivo para personalizar la educación","Inteligencia predictiva para mejorar el aprendizaje","Diseño offline-first para acceso sin conexión","Compatibilidad multilingüe para usuarios globales","Proporciona flujos de trabajo especializados para dominios específicos"],"fr":["Analyse cognitive pour personnaliser l''éducation","Intelligence prédictive pour améliorer l''apprentissage","Conception offline-first pour accéder sans connexion","Compatibilité multilingue pour les utilisateurs mondiaux","Fournit des flux de travail spécialisés pour des domaines spécifiques"],"de":["Kognitive Analyse zur Personalisierung der Ausbildung","Prädiktive Intelligenz zur Verbesserung des Lernens","Offline-First-Design für den Zugriff ohne Verbindung","Multilinguale Kompatibilität für globale Benutzer","Bietet spezialisierte Workflows für bestimmte Domänen"],"pt":["Análise cognitiva para personalizar a educação","Inteligência preditiva para melhorar o aprendizado","Design offline-first para acessibilidade","Suporte a múltiplas línguas","Fornecimento de orientação para criar habilidades eficazes"],"ru":["Когнитивный анализ для персонализации образования","Прогностическая интеллекта для улучшения обучения","Офлайн-ориентированный дизайн для доступности","Поддержка нескольких языков","Предоставление руководства по созданию эффективных навыков с помощью ИИ Агентов"],"ar":["التحليل المعرفي لتخصيص التعليم","الذكاء التحليلي لتحسين التعلم","تصميم غير متصل بالإنترنت للتоступ","دعم اللغات المتعددة","تقديم إرشادات لإنشاء مهارات فعالة بالاعتماد على تقنيات الذكاء الاصطناعي"]},"keywords":{"en":["how to use skill-creator","what is skill-creator","skill-creator alternative","skill-creator vs claude","skill-creator install","skill-creator setup guide","adaptive learning companion","cognitive analysis for education","predictive intelligence for learning"],"zh":["Skill Creator","预测智能","认知分析","模块化技能包","AI学习伴侣","离线学习","多语言支持"],"ja":["Skill Creator","AIエージェント","学習環境の構築","モジュール化されたスキルパッケージ","予測インテリジェンス","オフライン学習","多言語対応"],"ko":["Skill Creator","예측 인텔리전스","인지 분석","모듈화된 스킬 패키지","AI 학습 동반자","오프라인 학습","다국어 지원"],"es":["Skill Creator","agente de aprendizaje de IA","análisis cognitivo","inteligencia predictiva","educación personalizada","desarrollo de habilidades","IA para educación","herramientas de aprendizaje","tecnologías de IA para educación"],"fr":["Skill Creator","agent d''apprentissage IA","analyse cognitive","intelligence prédictive","éducation personnalisée","développement de compétences","IA pour l''éducation","outils d''apprentissage","technologies IA pour l''éducation"],"de":["Skill Creator","IA-Lernagent","kognitive Analyse","prädiktive Intelligenz","personalisierte Ausbildung","Fähigkeitsentwicklung","IA für Ausbildung","Lernwerkzeuge","IA-Technologien für Ausbildung"],"pt":["Skill-Creator","aprendizado adaptativo","análise cognitiva","inteligência preditiva","educação personalizada","desenvolvimento de habilidades","ferramentas de aprendizado","tecnologias educacionais"],"ru":["Skill-Creator","адаптивное обучение","когнитивный анализ","прогностическая интеллекта","персонализированное образование","развитие навыков","инструменты обучения","обучающие технологии","ИИ Агенты"],"ar":["Skill-Creator","التعلم التكيفي","التحليل المعرفي","الذكاء التحليلي","التعليم المتخصص","تطوير المهارات","أدوات التعلم","تقنيات التعليم","الذكاء الاصطناعي"]}},"owner":"harikiran138","repo":"lumina-ai-learning","repoPath":"harikiran138/lumina-ai-learning","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.470Z","topics":[],"category":"community","skillMd":{"name":"skill-creator","description":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claudes capabilities with specialized knowledge, workflows, or tool integrations.","bodyPreview":"# Skill Creator\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi","body":"# Skill Creator\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi-step procedures for specific domains\n2. Tool integrations - Instructions for working with specific file formats or APIs\n3. Domain expertise - Company-specific knowledge, schemas, business logic\n4. Bundled resources - Scripts, references, and assets for complex and repetitive tasks\n\n## Core Principles\n\n### Concise is Key\n\nThe context window is a public good. Skills share the context window with everything else Claude needs: system prompt, conversation history, other Skills'' metadata, and the actual user request.\n\n**Default assumption: Claude is already very smart.** Only add context Claude doesn''t already have. Challenge each piece of information: \"Does Claude really need this explanation?\" and \"Does this paragraph justify its token cost?\"\n\nPrefer concise examples over verbose explanations.\n\n### Set Appropriate Degrees of Freedom\n\nMatch the level of specificity to the task''s fragility and variability:\n\n**High freedom (text-based instructions)**: Use when multiple approaches are valid, decisions depend on context, or heuristics guide the approach.\n\n**Medium freedom (pseudocode or scripts with parameters)**: Use when a preferred pattern exists, some variation is acceptable, or configuration affects behavior.\n\n**Low freedom (specific scripts, few parameters)**: Use when operations are fragile and error-prone, consistency is critical, or a specific sequence must be followed.\n\nThink of Claude as exploring a path: a narrow bridge with cliffs needs specific guardrails (low freedom), while an open field allows many routes (high freedom).\n\n### Anatomy of a Skill\n\nEvery skill consists of a required SKILL.md file and optional bundled resources:\n\n```\nskill-name/\n├── SKILL.md (required)\n│   ├── YAML frontmatter metadata (required)\n│   │   ├── name: (required)\n│   │   ├── description: (required)\n│   │   └── compatibility: (optional, rarely needed)\n│   └── Markdown instructions (required)\n└── Bundled Resources (optional)\n    ├── scripts/          - Executable code (Python/Bash/etc.)\n    ├── references/       - Documentation intended to be loaded into context as needed\n    └── assets/           - Files used in output (templates, icons, fonts, etc.)\n```\n\n#### SKILL.md (required)\n\nEvery SKILL.md consists of:\n\n- **Frontmatter** (YAML): Contains `name` and `description` fields (required), plus optional fields like `license`, `metadata`, and `compatibility`. Only `name` and `description` are read by Claude to determine when the skill triggers, so be clear and comprehensive about what the skill is and when it should be used. The `compatibility` field is for noting environment requirements (target product, system packages, etc.) but most skills don''t need it.\n- **Body** (Markdown): Instructions and guidance for using the skill. Only loaded AFTER the skill triggers (if at all).\n\n#### Bundled Resources (optional)\n\n##### Scripts (`scripts/`)\n\nExecutable code (Python/Bash/etc.) for tasks that require deterministic reliability or are repeatedly rewritten.\n\n- **When to include**: When the same code is being rewritten repeatedly or deterministic reliability is needed\n- **Example**: `scripts/rotate_pdf.py` for PDF rotation tasks\n- **Benefits**: Token efficient, deterministic, may be executed without loading into context\n- **Note**: Scripts may still need to be read by Claude for patching or environment-specific adjustments\n\n##### References (`references/`)\n\nDocumentation and reference material intended to be loaded as needed into context to inform Claude''s process and thinking.\n\n- **When to include**: For documentation that Claude should reference while working\n- **Examples**: `references/finance.md` for financial schemas, `references/mnda.md` for company NDA template, `references/policies.md` for company policies, `references/api_docs.md` for API specifications\n- **Use cases**: Database schemas, API documentation, domain knowledge, company policies, detailed workflow guides\n- **Benefits**: Keeps SKILL.md lean, loaded only when Claude determines it''s needed\n- **Best practice**: If files are large (>10k words), include grep search patterns in SKILL.md\n- **Avoid duplication**: Information should live in either SKILL.md or references files, not both. Prefer references files for detailed information unless it''s truly core to the skill—this keeps SKILL.md lean while making information discoverable without hogging the context window. Keep only essential procedural instructions and workflow guidance in SKILL.md; move detailed reference material, schemas, and examples to references files.\n\n##### Assets (`assets/`)\n\nFiles not intended to be loaded into context, but rather used within the output Claude produces.\n\n- **When to include**: When the skill needs files that will be used in the final output\n- **Examples**: `assets/logo.png` for brand assets, `assets/slides.pptx` for PowerPoint templates, `assets/frontend-template/` for HTML/React boilerplate, `assets/font.ttf` for typography\n- **Use cases**: Templates, images, icons, boilerplate code, fonts, sample documents that get copied or modified\n- **Benefits**: Separates output resources from documentation, enables Claude to use files without loading them into context\n\n#### What to Not Include in a Skill\n\nA skill should only contain essential files that directly support its functionality. Do NOT create extraneous documentation or auxiliary files, including:\n\n- README.md\n- INSTALLATION_GUIDE.md\n- QUICK_REFERENCE.md\n- CHANGELOG.md\n- etc.\n\nThe skill should only contain the information needed for an AI agent to do the job at hand. It should not contain auxilary context about the process that went into creating it, setup and testing procedures, user-facing documentation, etc. Creating additional documentation files just adds clutter and confusion.\n\n### Progressive Disclosure Design Principle\n\nSkills use a three-level loading system to manage context efficiently:\n\n1. **Metadata (name + description)** - Always in context (~100 words)\n2. **SKILL.md body** - When skill triggers (<5k words)\n3. **Bundled resources** - As needed by Claude (Unlimited because scripts can be executed without reading into context window)\n\n#### Progressive Disclosure Patterns\n\nKeep SKILL.md body to the essentials and under 500 lines to minimize context bloat. Split content into separate files when approaching this limit. When splitting out content into other files, it is very important to reference them from SKILL.md and describe clearly when to read them, to ensure the reader of the skill knows they exist and when to use them.\n\n**Key principle:** When a skill supports multiple variations, frameworks, or options, keep only the core workflow and selection guidance in SKILL.md. Move variant-specific details (patterns, examples, configuration) into separate reference files.\n\n**Pattern 1: High-level guide with references**\n\n```markdown\n# PDF Processing\n\n## Quick start\n\nExtract text with pdfplumber:\n[code example]\n\n## Advanced features\n\n- **Form filling**: See [FORMS.md](FORMS.md) for complete guide\n- **API reference**: See [REFERENCE.md](REFERENCE.md) for all methods\n- **Examples**: See [EXAMPLES.md](EXAMPLES.md) for common patterns\n```\n\nClaude loads FORMS.md, REFERENCE.md, or EXAMPLES.md only when needed.\n\n**Pattern 2: Domain-specific organization**\n\nFor Skills with multiple domains, organize content by domain to avoid loading irrelevant context:\n\n```\nbigquery-skill/\n├── SKILL.md (overview and navigation)\n└── reference/\n    ├── finance.md (revenue, billing metrics)\n    ├── sales.md (opportunities, pipeline)\n    ├── product.md (API usage, features)\n    └── marketing.md (campaigns, attribution)\n```\n\nWhen a user asks about sales metrics, Claude only reads sales.md.\n\nSimilarly, for skills supporting multiple frameworks or variants, organize by variant:\n\n```\ncloud-deploy/\n├── SKILL.md (workflow + provider selection)\n└── references/\n    ├── aws.md (AWS deployment patterns)\n    ├── gcp.md (GCP deployment patterns)\n    └── azure.md (Azure deployment patterns)\n```\n\nWhen the user chooses AWS, Claude only reads aws.md.\n\n**Pattern 3: Conditional details**\n\nShow basic content, link to advanced content:\n\n```markdown\n# DOCX Processing\n\n## Creating documents\n\nUse docx-js for new documents. See [DOCX-JS.md](DOCX-JS.md).\n\n## Editing documents\n\nFor simple edits, modify the XML directly.\n\n**For tracked changes**: See [REDLINING.md](REDLINING.md)\n**For OOXML details**: See [OOXML.md](OOXML.md)\n```\n\nClaude reads REDLINING.md or OOXML.md only when the user needs those features.\n\n**Important guidelines:**\n\n- **Avoid deeply nested references** - Keep references one level deep from SKILL.md. All reference files should link directly from SKILL.md.\n- **Structure longer reference files** - For files longer than 100 lines, include a table of contents at the top so Claude can see the full scope when previewing.\n\n## Skill Creation Process\n\nSkill creation involves these steps:\n\n1. Understand the skill with concrete examples\n2. Plan reusable skill contents (scripts, references, assets)\n3. Initialize the skill (run init_skill.py)\n4. Edit the skill (implement resources and write SKILL.md)\n5. Package the skill (run package_skill.py)\n6. Iterate based on real usage\n\nFollow these steps in order, skipping only if there is a clear reason why they are not applicable.\n\n### Step 1: Understanding the Skill with Concrete Examples\n\nSkip this step only when the skill''s usage patterns are already clearly understood. It remains valuable even when working with an existing skill.\n\nTo create an effective skill, clearly understand concrete examples of how the skill will be used. This understanding can come from either direct user examples or generated examples that are validated with user feedback.\n\nFor example, when building an image-editor skill, relevant questions include:\n\n- \"What functionality should the image-editor skill support? Editing, rotating, anything else?\"\n- \"Can you give some examples of how this skill would be used?\"\n- \"I can imagine users asking for things like ''Remove the red-eye from this image'' or ''Rotate this image''. Are there other ways you imagine this skill being used?\"\n- \"What would a user say that should trigger this skill?\"\n\nTo avoid overwhelming users, avoid asking too many questions in a single message. Start with the most important questions and follow up as needed for better effectiveness.\n\nConclude this step when there is a clear sense of the functionality the skill should support.\n\n### Step 2: Planning the Reusable Skill Contents\n\nTo turn concrete examples into an effective skill, analyze each example by:\n\n1. Considering how to execute on the example from scratch\n2. Identifying what scripts, references, and assets would be helpful when executing these workflows repeatedly\n\nExample: When building a `pdf-editor` skill to handle queries like \"Help me rotate this PDF,\" the analysis shows:\n\n1. Rotating a PDF requires re-writing the same code each time\n2. A `scripts/rotate_pdf.py` script would be helpful to store in the skill\n\nExample: When designing a `frontend-webapp-builder` skill for queries like \"Build me a todo app\" or \"Build me a dashboard to track my steps,\" the analysis shows:\n\n1. Writing a frontend webapp requires the same boilerplate HTML/React each time\n2. An `assets/hello-world/` template containing the boilerplate HTML/React project files would be helpful to store in the skill\n\nExample: When building a `big-query` skill to handle queries like \"How many users have logged in today?\" the analysis shows:\n\n1. Querying BigQuery requires re-discovering the table schemas and relationships each time\n2. A `references/schema.md` file documenting the table schemas would be helpful to store in the skill\n\nTo establish the skill''s contents, analyze each concrete example to create a list of the reusable resources to include: scripts, references, and assets.\n\n### Step 3: Initializing the Skill\n\nAt this point, it is time to actually create the skill.\n\nSkip this step only if the skill being developed already exists, and iteration or packaging is needed. In this case, continue to the next step.\n\nWhen creating a new skill from scratch, always run the `init_skill.py` script. The script conveniently generates a new template skill directory that automatically includes everything a skill requires, making the skill creation process much more efficient and reliable.\n\nUsage:\n\n```bash\nscripts/init_skill.py <skill-name> --path <output-directory>\n```\n\nThe script:\n\n- Creates the skill directory at the specified path\n- Generates a SKILL.md template with proper frontmatter and TODO placeholders\n- Creates example resource directories: `scripts/`, `references/`, and `assets/`\n- Adds example files in each directory that can be customized or deleted\n\nAfter initialization, customize or remove the generated SKILL.md and example files as needed.\n\n### Step 4: Edit the Skill\n\nWhen editing the (newly-generated or existing) skill, remember that the skill is being created for another instance of Claude to use. Include information that would be beneficial and non-obvious to Claude. Consider what procedural knowledge, domain-specific details, or reusable assets would help another Claude instance execute these tasks more effectively.\n\n#### Learn Proven Design Patterns\n\nConsult these helpful guides based on your skill''s needs:\n\n- **Multi-step processes**: See references/workflows.md for sequential workflows and conditional logic\n- **Specific output formats or quality standards**: See references/output-patterns.md for template and example patterns\n\nThese files contain established best practices for effective skill design.\n\n#### Start with Reusable Skill Contents\n\nTo begin implementation, start with the reusable resources identified above: `scripts/`, `references/`, and `assets/` files. Note that this step may require user input. For example, when implementing a `brand-guidelines` skill, the user may need to provide brand assets or templates to store in `assets/`, or documentation to store in `references/`.\n\nAdded scripts must be tested by actually running them to ensure there are no bugs and that the output matches what is expected. If there are many similar scripts, only a representative sample needs to be tested to ensure confidence that they all work while balancing time to completion.\n\nAny example files and directories not needed for the skill should be deleted. The initialization script creates example files in `scripts/`, `references/`, and `assets/` to demonstrate structure, but most skills won''t need all of them.\n\n#### Update SKILL.md\n\n**Writing Guidelines:** Always use imperative/infinitive form.\n\n##### Frontmatter\n\nWrite the YAML frontmatter with `name` and `description`:\n\n- `name`: The skill name\n- `description`: This is the primary triggering mechanism for your skill, and helps Claude understand when to use the skill.\n  - Include both what the Skill does and specific triggers/contexts for when to use it.\n  - Include all \"when to use\" information here - Not in the body. The body is only loaded after triggering, so \"When to Use This Skill\" sections in the body are not helpful to Claude.\n  - Example description for a `docx` skill: \"Comprehensive document creation, editing, and analysis with support for tracked changes, comments, formatting preservation, and text extraction. Use when Claude needs to work with professional documents (.docx files) for: (1) Creating new documents, (2) Modifying or editing content, (3) Working with tracked changes, (4) Adding comments, or any other document tasks\"\n\nDo not include any other fields in YAML frontmatter.\n\n##### Body\n\nWrite instructions for using the skill and its bundled resources.\n\n### Step 5: Packaging a Skill\n\nOnce development of the skill is complete, it must be packaged into a distributable .skill file that gets shared with the user. The packaging process automatically validates the skill first to ensure it meets all requirements:\n\n```bash\nscripts/package_skill.py <path/to/skill-folder>\n```\n\nOptional output directory specification:\n\n```bash\nscripts/package_skill.py <path/to/skill-folder> ./dist\n```\n\nThe packaging script will:\n\n1. **Validate** the skill automatically, checking:\n\n   - YAML frontmatter format and required fields\n   - Skill naming conventions and directory structure\n   - Description completeness and quality\n   - File organization and resource references\n\n2. **Package** the skill if validation passes, creating a .skill file named after the skill (e.g., `my-skill.skill`) that includes all files and maintains the proper directory structure for distribution. The .skill file is a zip file with a .skill extension.\n\nIf validation fails, the script will report the errors and exit without creating a package. Fix any validation errors and run the packaging command again.\n\n### Step 6: Iterate\n\nAfter testing the skill, users may request improvements. Often this happens right after using the skill, with fresh context of how the skill performed.\n\n**Iteration workflow:**\n\n1. Use the skill on real tasks\n2. Notice struggles or inefficiencies\n3. Identify how SKILL.md or bundled resources should be updated\n4. Implement changes and test again\n"},"lastSynced":"2026-03-07T01:56:12.023Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing to extend Claude''s capabilities with specialized knowledge and workflows.","zh":"非常适合需要扩展Claude能力的开发者代理，通过专门的知识和工作流程。","ja":"Claudeの機能を特殊な知識やワークフローで拡張する必要がある開発者エージェントに最適です。","ko":"클라우드의 기능을 전문 지식과 워크플로우로 확장해야 하는 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan ampliar las capacidades de Claude con conocimientos y flujos de trabajo especializados.","fr":"Parfait pour les agents de développement qui doivent étendre les capacités de Claude avec des connaissances et des flux de travail spécialisés.","de":"Perfekt für Entwickleragenten, die die Fähigkeiten von Claude mit spezialisierten Kenntnissen und Workflows erweitern müssen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam estender as capacidades do Claude com conhecimento especializado e fluxos de trabalho.","ru":"Идеально подходит для агентов-разработчиков, которым необходимо расширить возможности Claude с помощью специализированных знаний и рабочих процессов.","ar":"مثالي للوكلاء المطورين الذين يحتاجون إلى扩يع قدرات كلود مع المعارف المتخصصة والتدفقات العملية."},"recommendation":{"en":"Empowers agents to create adaptive learning experiences by providing modular, self-contained packages that extend capabilities with specialized knowledge, workflows, and tools, utilizing procedural knowledge and multi-step workflows.","zh":"通过提供模块化、自成体系的软件包来赋予代理创建自适应学习体验的能力，这些软件包扩展了功能，包括专门的知识、工作流程和工具，利用程序化的知识和多步骤的工作流程。","ja":"モジュラーで自己完結したパッケージを提供することで、エージェントが適応的な学習体験を作成する能力を付与します。これらのパッケージは、機能を拡張し、特殊な知識、ワークフロー、ツールを提供し、手続き型の知識とマルチステップのワークフローを利用します。","ko":"모듈화되어 자체적으로 완결된 패키지를 제공하여 에이전트가 적응형 학습 경험을 생성할 수 있는 능력을 부여합니다. 이러한 패키지는 기능을 확장하고 전문 지식, 워크플로우, 도구를 제공하며 프로그래밍된 지식과 다단계 워크플로우를 활용합니다.","es":"Habilita a los agentes a crear experiencias de aprendizaje adaptativas al proporcionar paquetes modulares y autocontenidos que amplían las capacidades con conocimientos especializados, flujos de trabajo y herramientas, utilizando conocimiento procedural y flujos de trabajo multi paso.","fr":"Permet aux agents de créer des expériences d''apprentissage adaptatives en fournissant des packages modulaires et auto-contenus qui étendent les capacités avec des connaissances spécialisées, des flux de travail et des outils, en utilisant des connaissances procédurales et des flux de travail multi-étapes.","de":"Ermöglicht es Agenten, adaptive Lernerfahrungen zu erstellen, indem sie modulare, selbstenthaltene Pakete bereitstellen, die Fähigkeiten mit spezialisierten Kenntnissen, Workflows und Tools erweitern, unter Verwendung von prozeduralem Wissen und mehrschrittigen Workflows.","pt":"Habilita os agentes a criar experiências de aprendizado adaptáveis, fornecendo pacotes modulares e autossuficientes que estendem as capacidades com conhecimento especializado, fluxos de trabalho e ferramentas, utilizando conhecimento procedural e fluxos de trabalho em várias etapas.","ru":"Позволяет агентам создавать адаптивные опыт обучения, предоставляя модульные, самодостаточные пакеты, которые расширяют возможности с помощью специализированных знаний, рабочих процессов и инструментов, используя процедурные знания и многоступенчатые рабочие процессы.","ar":"تمكين الوكلاء من إنشاء تجارب تعلم متكيفة من خلال توفير حزم متماسكة وذاتية الحصار التي تمتد القدرات المعرفية المتخصصة والتدفقات العملية والأدوات، باستخدام المعرفة الإجرائية والتدفقات العملية متعددة المراحل."},"useCases":{"en":["Creating customized onboarding guides for specific domains","Developing specialized workflows for tasks","Extending agent capabilities with domain-specific knowledge"],"zh":["为特定领域创建自定义的入门指南","为任务开发专门的工作流程","使用领域特定知识来扩展代理的功能"],"ja":["特定ドメインのカスタマイズされたオンボーディングガイドを作成する","タスク用の特殊なワークフローを開発する","ドメイン固有の知識を使用してエージェントの機能を拡張する"],"ko":["특정 도메인에 대한 맞춤형 온보딩 가이드 생성","작업을 위한 전문 워크플로우 개발","도메인 특정 지식을 사용하여 에이전트 기능 확장"],"es":["Crear guías de incorporación personalizadas para dominios específicos","Desarrollar flujos de trabajo especializados para tareas","Ampliar las capacidades de los agentes con conocimientos específicos del dominio"],"fr":["Créer des guides d''intégration personnalisés pour des domaines spécifiques","Développer des flux de travail spécialisés pour des tâches","Étendre les capacités des agents avec des connaissances spécifiques au domaine"],"de":["Erstellen von benutzerdefinierten Onboarding-Anleitungen für bestimmte Bereiche","Entwickeln von spezialisierten Workflows für Aufgaben","Erweitern der Agentenfähigkeiten mit bereichsspezifischen Kenntnissen"],"pt":["Criação de guias de integração personalizados para domínios específicos","Desenvolvimento de fluxos de trabalho especializados para tarefas","Extensão das capacidades do agente com conhecimento específico de domínio"],"ru":["Создание индивидуальных руководств по интеграции для конкретных доменов","Разработка специализированных рабочих процессов для задач","Расширение возможностей агента с помощью домен-специфических знаний"],"ar":["إنشاء دلالات التكامل المخصصة لأقسام محددة","تطوير التدفقات العملية المتخصصة للمهام","تمديد قدرات الوكيل المعرفية الخاصة بالمجال"]},"limitations":{"en":["Requires Claude''s infrastructure","Limited to extending Claude''s capabilities"],"zh":["需要Claude的基础设施","仅限于扩展Claude的功能"],"ja":["Claudeのインフラストラクチャが必要","Claudeの機能の拡張のみ"],"ko":["클라우드의 인프라스트럭처가 필요","클라우드의 기능 확장만 가능"],"es":["Requiere la infraestructura de Claude","Limitado a ampliar las capacidades de Claude"],"fr":["Nécessite l''infrastructure de Claude","Limité à l''extension des capacités de Claude"],"de":["Benötigt die Infrastruktur von Claude","Begrenzt auf die Erweiterung der Fähigkeiten von Claude"],"pt":["Requer a infraestrutura do Claude","Limitado à extensão das capacidades do Claude"],"ru":["Требует инфраструктуры Claude","Ограничен расширением возможностей Claude"],"ar":["يتطلب البنية التحتية لكلود","محدود بتوسيع قدرات كلود"]},"version":4},"contentHash":"d57b6e3a44535b9c0ef454dad5c86f5df78185fc80a65c7092885b4b5e10f81b","qualityScore":45}');
DELETE FROM skills_fts WHERE id = 'harikiran138/lumina-ai-learning/skill-creator';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('harikiran138/lumina-ai-learning/skill-creator', 'skill-creator', 'harikiran138', 'lumina-ai-learning', 'community', 'skill-creator harikiran138 lumina-ai-learning community Skill-Creator provides guidance for creating effective skills, extending Claude''s capabilities with specialized knowledge and workflows. It benefits developers and educators seeking to create adaptive learning experiences Skill Creator 是一个使用预测智能和认知分析的自适应学习伴侣，提供模块化和自包含的技能包 Skill Creator は、AIエージェントを使用した学習環境を構築するためのモジュール化されたスキルパッケージです Skill Creator는 예측 인텔리전스와 인지 분석을 사용하여 적응형 학습 환경을 제공하는 모듈화된 스킬 패키지입니다 Skill Creator es un compañero de aprendizaje de IA adaptativo que personaliza la educación a través del análisis cognitivo y la inteligencia predictiva, diseñado para hacer que el aprendizaje de calidad sea accesible para todos Skill Creator est un compagnon d''apprentissage IA adaptatif qui personnalise l''éducation à travers l''analyse cognitive et l''intelligence prédictive, conçu pour rendre l''apprentissage de qualité accessible à tous Skill Creator ist ein adaptiver IA-Lernbegleiter, der die Ausbildung durch kognitive Analyse und prädiktive Intelligenz personalisiert, designed, um hochwertiges Lernen für alle zugänglich zu machen O Skill-Creator é um companion de aprendizado adaptativo que fornece orientação para criar habilidades eficazes. Ele é offline-first, multilíngue e projetado para tornar o aprendizado de qualidade acessível a todos. Skill-Creator — это адаптивный компаньон обучения, который предоставляет руководство по созданию эффективных навыков. Он офлайн-ориентирован, многоязычный и предназначен для того, чтобы качественное обучение было доступно всем с помощью ИИ Агентов. Skill-Creator هو رفيق تعليمي ذكي يقدم إرشادات لإنشاء مهارات فعالة. وهو غير متصل بالإنترنت، متعددة اللغات، ومصمم لجعل التعلم النوعي متاحًا للجميع بالاعتماد على تقنيات الذكاء الاصطناعي. how to use skill-creator what is skill-creator skill-creator alternative skill-creator vs claude skill-creator install skill-creator setup guide adaptive learning companion cognitive analysis for education predictive intelligence for learning Skill Creator 预测智能 认知分析 模块化技能包 AI学习伴侣 离线学习 多语言支持 Provides specialized workflows and procedural knowledge Enables creation of modular, self-contained packages for Claude Supports multilingual and offline-first learning experiences Transforms Claude into a specialized agent with domain-specific knowledge Offers guidance for creating effective skills through cognitive analysis Skill-creator is an adaptive AI learning companion that personalizes education through cognitive analysis and predictive intelligence');
