INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ncrmro/deepwork-permanent-portfolio/deepwork_jobs', 'deepwork_jobs', 'ncrmro', 'deepwork-permanent-portfolio', 'community', 'deepwork_jobs ncrmro deepwork-permanent-portfolio community deepwork_jobs是一种AI智能代理，实现了Harry Browne的永久投资组合策略，自动化每日投资组合分析 deepwork_jobsは、ハリー・ブラウンの永久ポートフォリオ戦略を実現するAIエージェントであり、毎日のポートフォリオ分析を自動化 deepwork_jobs는 Harry Browne의 영구 포트폴리오 전략을 구현하는 AI 에이전트로서 일일 포트폴리오 분석을 자동화 deepwork_jobs es una herramienta de AI que analiza automáticamente su cartera diaria, implementando la estrategia de cartera permanente de Harry Browne deepwork_jobs est un outil d''IA qui analyse automatiquement votre portefeuille quotidien, en implementant la stratégie de portefeuille permanent de Harry Browne deepwork_jobs ist ein KI-Tool, das Ihre tägliche Portfolioanalyse automatisch durchführt, indem es die Permanent-Portfolio-Strategie von Harry Browne implementiert Análise de carteira automatizada diária implementando a estratégia de Portfolio Permanente de Harry Browne Автоматический ежедневный анализ портфеля, реализующий стратегию Постоянного Портфеля Гарри Брауна تحليل تلقائي يومي للمحفظة باستخدام استراتيجية المحفظة الدائمة لهاري براون Automated daily portfolio analysis implementing Harry Browne''s Permanent Portfolio strategy AI智能代理 永久投资组合策略 如何使用deepwork_jobs 什么是Harry Browne永久投资组合策略 deepwork_jobs安装指南 deepwork_jobs vs 其他投资组合工具 Automated daily portfolio analysis implementing Harry Browne''s Permanent Portfolio strategy');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('siluat/web-projects/turborepo', 'community', 'siluat', 'web-projects', 'siluat/web-projects', 'turborepo', 0, 0, 45, '2026-03-04T13:07:01.803Z', '2026-03-04T14:30:25.350Z', '390f3a791150b139a8e8eb995cd4e81a3b8b05ce90fe1136964e335abb19e5b7', '{"id":"siluat/web-projects/turborepo","name":"turborepo","description":{"zh":"Turborepo是一种用于加速个人网页项目开发的AI工具，通过自动化构建和优化过程","ja":"Turborepoは、個人ウェブプロジェクトの開発を加速するためのAIエージェントです。自動化された構築と最適化プロセスを提供します","ko":"Turborepo는 개인 웹 프로젝트 개발을 가속화하는 AI 에이전트로, 자동화된 구축 및 최적화 프로세스를 제공합니다","es":"Turborepo es una herramienta de AI para mejorar la eficiencia de tus proyectos web personales. Ofrece funcionalidades para optimizar y automatizar tareas.","fr":"Turborepo est un outil d''IA pour améliorer l''efficacité de vos projets web personnels. Il offre des fonctionnalités pour optimiser et automatiser des tâches.","de":"Turborepo ist ein AI-Tool, um die Effizienz Ihrer persönlichen Webprojekte zu verbessern. Es bietet Funktionen zur Optimierung und Automatisierung von Aufgaben.","pt":"O Turborepo é uma ferramenta de desenvolvimento de projetos web que visa aumentar a produtividade dos desenvolvedores","ru":"Turborepo - это инструмент для разработки веб-проектов, предназначенный для повышения производительности разработчиков","ar":"تيربو ريبو هي أداة تطوير مشاريع الويب التي تهدف إلى زيادة إنتاجية المطورين","en":"My personal web projects"},"seo":{"title":{"zh":"Turborepo AI工具：加速个人网页项目开发","ja":"Turborepo AIエージェント：個人ウェブプロジェクトの高速開発","ko":"Turborepo AI 에이전트: 개인 웹 프로젝트 개발 가속","es":"Turborepo: Herramientas de AI para proyectos web personales","fr":"Turborepo: Outils d''IA pour les projets web personnels","de":"Turborepo: AI-Tools für persönliche Webprojekte","pt":"Turborepo: Ferramenta de Desenvolvimento de Projetos Web","ru":"Turborepo: Инструмент для разработки веб-проектов","ar":"تيربو ريبو: أداة تطوير مشاريع الويب","en":"turborepo"},"description":{"zh":"Turborepo是一种用于加速个人网页项目开发的AI工具，通过自动化构建和优化过程","ja":"Turborepoは、個人ウェブプロジェクトの開発を加速するためのAIエージェントです。自動化された構築と最適化プロセスを提供します","ko":"Turborepo는 개인 웹 프로젝트 개발을 가속화하는 AI 에이전트로, 자동화된 구축 및 최적화 프로세스를 제공합니다","es":"Turborepo es una herramienta de AI para mejorar la eficiencia de tus proyectos web personales. Ofrece funcionalidades para optimizar y automatizar tareas.","fr":"Turborepo est un outil d''IA pour améliorer l''efficacité de vos projets web personnels. Il offre des fonctionnalités pour optimiser et automatiser des tâches.","de":"Turborepo ist ein AI-Tool, um die Effizienz Ihrer persönlichen Webprojekte zu verbessern. Es bietet Funktionen zur Optimierung und Automatisierung von Aufgaben.","pt":"O Turborepo é uma ferramenta de desenvolvimento de projetos web que visa aumentar a produtividade dos desenvolvedores","ru":"Turborepo - это инструмент для разработки веб-проектов, предназначенный для повышения производительности разработчиков","ar":"تيربو ريبو هي أداة تطوير مشاريع الويب التي تهدف إلى زيادة إنتاجية المطورين","en":"My personal web projects"},"definition":{"en":"My personal web projects"},"features":{"zh":["自动化构建和优化","支持React、Node.js和CLI","提高开发效率和速度","简化个人网页项目开发过程","提供实时反馈和错误检测"],"ja":["自動化された構築と最適化","React、Node.js、CLIのサポート","開発効率と速度の向上","個人ウェブプロジェクトの開発プロセスの簡素化","リアルタイムのフィードバックとエラーディテクション"],"ko":["자동화된 구축 및 최적화","React, Node.js, CLI 지원","개발 효율성과 속도 향상","개인 웹 프로젝트 개발 프로세스簡素化","실시간 피드백 및 에러 감지"],"es":["Optimización de código","Automatización de tareas","Mejora de la eficiencia del proyecto","Integración con herramientas de desarrollo","Soporte para proyectos web personales"],"fr":["Optimisation du code","Automatisation des tâches","Amélioration de l''efficacité du projet","Intégration avec des outils de développement","Prise en charge des projets web personnels"],"de":["Code-Optimierung","Automatisierung von Aufgaben","Verbesserung der Projekteffizienz","Integration mit Entwicklungstools","Unterstützung für persönliche Webprojekte"],"pt":["Desenvolvimento de projetos web personalizados","Integração com ferramentas de desenvolvimento populares","Aumento da produtividade dos desenvolvedores","Suporte a múltiplos ambientes de desenvolvimento","Fácil instalação e configuração"],"ru":["Разработка индивидуальных веб-проектов","Интеграция с популярными инструментами разработки","Повышение производительности разработчиков","Поддержка нескольких сред разработки","Легкая установка и конфигурация"],"ar":["تطوير مشاريع ويب مخصصة","التكامل مع أدوات التطوير الشهيرة","زيادة إنتاجية المطورين","دعم بيئات متعددة للتطوير","تثبيت وتهيئة سهلة"]},"keywords":{"zh":["Turborepo教程","如何使用Turborepo","Turborepo替代品","Turborepo与其他工具的比较","Turborepo安装指南","Turborepo设置教程","个人网页项目开发工具","AI工具用于网页开发","网页开发加速工具"],"ja":["Turborepoの使い方","Turborepoの設定方法","Turborepoの代替ツール","Turborepoと他のツールの比較","Turborepoのインストールガイド","Turborepoの設定ガイド","個人ウェブプロジェクトの開発ツール","AIツールを使用したウェブ開発","ウェブ開発の加速ツール"],"ko":["Turborepo 사용법","Turborepo 설정 방법","Turborepo 대체 도구","Turborepo와 다른 도구 비교","Turborepo 설치 가이드","Turborepo 설정 가이드","개인 웹 프로젝트 개발 도구","AI 도구를 사용한 웹 개발","웹 개발 가속 도구"],"es":["cómo usar Turborepo","herramientas de AI para proyectos web","Turborepo vs otras herramientas","instalación de Turborepo","guía de configuración de Turborepo","mejora de la eficiencia del proyecto con AI"],"fr":["comment utiliser Turborepo","outils d''IA pour les projets web","Turborepo vs d''autres outils","installation de Turborepo","guide de configuration de Turborepo","amélioration de l''efficacité du projet avec l''IA"],"de":["wie man Turborepo verwendet","AI-Tools für Webprojekte","Turborepo im Vergleich zu anderen Tools","Installation von Turborepo","Konfigurationsanleitung für Turborepo","Verbesserung der Projekteffizienz mit AI"],"pt":["como usar Turborepo","o que é Turborepo","Turborepo vs Create React App","Turborepo alternative","guia de instalação do Turborepo","configuração do Turborepo","desenvolvimento de projetos web com Turborepo","Turborepo e Node.js"],"ru":["как использовать Turborepo","что такое Turborepo","Turborepo vs Create React App","аналог Turborepo","руководство по установке Turborepo","настройка Turborepo","разработка веб-проектов с Turborepo","Turborepo и Node.js"],"ar":["كيفية استخدام تيربو ريبو","ما هو تيربو ريبو","تيربو ريبو مقابل Create React App","بديل تيربو ريبو","دليل تثبيت تيربو ريبو","تهيئة تيربو ريبو","تطوير مشاريع الويب مع تيربو ريبو","تيربو ريبو و Node.js"]}},"owner":"siluat","repo":"web-projects","repoPath":"siluat/web-projects","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.803Z","topics":[],"category":"community","skillMd":{"name":"turborepo","description":"|","version":"2.8.1-canary.1","bodyPreview":"# Turborepo Skill\n\nBuild system for JavaScript/TypeScript monorepos. Turborepo caches task outputs and runs tasks in parallel based on dependency graph.\n\n## IMPORTANT: Package Tasks, Not Root Tasks\n\n**DO NOT create Root Tasks. ALWAYS create package tasks.**\n\nWhen creating tasks/scripts/pipelines, you MUST:\n\n1. Add the script to each relevant package''s `package.json`\n2. Register the task in root `turbo.json`\n3. Root `package.json` only delegates via `turbo run <task>`\n\n**DO NOT** put task logic i","body":"# Turborepo Skill\n\nBuild system for JavaScript/TypeScript monorepos. Turborepo caches task outputs and runs tasks in parallel based on dependency graph.\n\n## IMPORTANT: Package Tasks, Not Root Tasks\n\n**DO NOT create Root Tasks. ALWAYS create package tasks.**\n\nWhen creating tasks/scripts/pipelines, you MUST:\n\n1. Add the script to each relevant package''s `package.json`\n2. Register the task in root `turbo.json`\n3. Root `package.json` only delegates via `turbo run <task>`\n\n**DO NOT** put task logic in root `package.json`. This defeats Turborepo''s parallelization.\n\n```json\n// DO THIS: Scripts in each package\n// apps/web/package.json\n{ \"scripts\": { \"build\": \"next build\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n\n// apps/api/package.json\n{ \"scripts\": { \"build\": \"tsc\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n\n// packages/ui/package.json\n{ \"scripts\": { \"build\": \"tsc\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n```\n\n```json\n// turbo.json - register tasks\n{\n  \"tasks\": {\n    \"build\": { \"dependsOn\": [\"^build\"], \"outputs\": [\"dist/**\"] },\n    \"lint\": {},\n    \"test\": { \"dependsOn\": [\"build\"] }\n  }\n}\n```\n\n```json\n// Root package.json - ONLY delegates, no task logic\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"lint\": \"turbo run lint\",\n    \"test\": \"turbo run test\"\n  }\n}\n```\n\n```json\n// DO NOT DO THIS - defeats parallelization\n// Root package.json\n{\n  \"scripts\": {\n    \"build\": \"cd apps/web && next build && cd ../api && tsc\",\n    \"lint\": \"eslint apps/ packages/\",\n    \"test\": \"vitest\"\n  }\n}\n```\n\nRoot Tasks (`//#taskname`) are ONLY for tasks that truly cannot exist in packages (rare).\n\n## Secondary Rule: `turbo run` vs `turbo`\n\n**Always use `turbo run` when the command is written into code:**\n\n```json\n// package.json - ALWAYS \"turbo run\"\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\"\n  }\n}\n```\n\n```yaml\n# CI workflows - ALWAYS \"turbo run\"\n- run: turbo run build --affected\n```\n\n**The shorthand `turbo <tasks>` is ONLY for one-off terminal commands** typed directly by humans or agents. Never write `turbo build` into package.json, CI, or scripts.\n\n## Quick Decision Trees\n\n### \"I need to configure a task\"\n\n```\nConfigure a task?\n├─ Define task dependencies → references/configuration/tasks.md\n├─ Lint/check-types (parallel + caching) → Use Transit Nodes pattern (see below)\n├─ Specify build outputs → references/configuration/tasks.md#outputs\n├─ Handle environment variables → references/environment/RULE.md\n├─ Set up dev/watch tasks → references/configuration/tasks.md#persistent\n├─ Package-specific config → references/configuration/RULE.md#package-configurations\n└─ Global settings (cacheDir, daemon) → references/configuration/global-options.md\n```\n\n### \"My cache isn''t working\"\n\n```\nCache problems?\n├─ Tasks run but outputs not restored → Missing `outputs` key\n├─ Cache misses unexpectedly → references/caching/gotchas.md\n├─ Need to debug hash inputs → Use --summarize or --dry\n├─ Want to skip cache entirely → Use --force or cache: false\n├─ Remote cache not working → references/caching/remote-cache.md\n└─ Environment causing misses → references/environment/gotchas.md\n```\n\n### \"I want to run only changed packages\"\n\n```\nRun only what changed?\n├─ Changed packages + dependents (RECOMMENDED) → turbo run build --affected\n├─ Custom base branch → --affected --affected-base=origin/develop\n├─ Manual git comparison → --filter=...[origin/main]\n└─ See all filter options → references/filtering/RULE.md\n```\n\n**`--affected` is the primary way to run only changed packages.** It automatically compares against the default branch and includes dependents.\n\n### \"I want to filter packages\"\n\n```\nFilter packages?\n├─ Only changed packages → --affected (see above)\n├─ By package name → --filter=web\n├─ By directory → --filter=./apps/*\n├─ Package + dependencies → --filter=web...\n├─ Package + dependents → --filter=...web\n└─ Complex combinations → references/filtering/patterns.md\n```\n\n### \"Environment variables aren''t working\"\n\n```\nEnvironment issues?\n├─ Vars not available at runtime → Strict mode filtering (default)\n├─ Cache hits with wrong env → Var not in `env` key\n├─ .env changes not causing rebuilds → .env not in `inputs`\n├─ CI variables missing → references/environment/gotchas.md\n└─ Framework vars (NEXT_PUBLIC_*) → Auto-included via inference\n```\n\n### \"I need to set up CI\"\n\n```\nCI setup?\n├─ GitHub Actions → references/ci/github-actions.md\n├─ Vercel deployment → references/ci/vercel.md\n├─ Remote cache in CI → references/caching/remote-cache.md\n├─ Only build changed packages → --affected flag\n├─ Skip unnecessary builds → turbo-ignore (references/cli/commands.md)\n└─ Skip container setup when no changes → turbo-ignore\n```\n\n### \"I want to watch for changes during development\"\n\n```\nWatch mode?\n├─ Re-run tasks on change → turbo watch (references/watch/RULE.md)\n├─ Dev servers with dependencies → Use `with` key (references/configuration/tasks.md#with)\n├─ Restart dev server on dep change → Use `interruptible: true`\n└─ Persistent dev tasks → Use `persistent: true`\n```\n\n### \"I need to create/structure a package\"\n\n```\nPackage creation/structure?\n├─ Create an internal package → references/best-practices/packages.md\n├─ Repository structure → references/best-practices/structure.md\n├─ Dependency management → references/best-practices/dependencies.md\n├─ Best practices overview → references/best-practices/RULE.md\n├─ JIT vs Compiled packages → references/best-practices/packages.md#compilation-strategies\n└─ Sharing code between apps → references/best-practices/RULE.md#package-types\n```\n\n### \"How should I structure my monorepo?\"\n\n```\nMonorepo structure?\n├─ Standard layout (apps/, packages/) → references/best-practices/RULE.md\n├─ Package types (apps vs libraries) → references/best-practices/RULE.md#package-types\n├─ Creating internal packages → references/best-practices/packages.md\n├─ TypeScript configuration → references/best-practices/structure.md#typescript-configuration\n├─ ESLint configuration → references/best-practices/structure.md#eslint-configuration\n├─ Dependency management → references/best-practices/dependencies.md\n└─ Enforce package boundaries → references/boundaries/RULE.md\n```\n\n### \"I want to enforce architectural boundaries\"\n\n```\nEnforce boundaries?\n├─ Check for violations → turbo boundaries\n├─ Tag packages → references/boundaries/RULE.md#tags\n├─ Restrict which packages can import others → references/boundaries/RULE.md#rule-types\n└─ Prevent cross-package file imports → references/boundaries/RULE.md\n```\n\n## Critical Anti-Patterns\n\n### Using `turbo` Shorthand in Code\n\n**`turbo run` is recommended in package.json scripts and CI pipelines.** The shorthand `turbo <task>` is intended for interactive terminal use.\n\n```json\n// WRONG - using shorthand in package.json\n{\n  \"scripts\": {\n    \"build\": \"turbo build\",\n    \"dev\": \"turbo dev\"\n  }\n}\n\n// CORRECT\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"dev\": \"turbo run dev\"\n  }\n}\n```\n\n```yaml\n# WRONG - using shorthand in CI\n- run: turbo build --affected\n\n# CORRECT\n- run: turbo run build --affected\n```\n\n### Root Scripts Bypassing Turbo\n\nRoot `package.json` scripts MUST delegate to `turbo run`, not run tasks directly.\n\n```json\n// WRONG - bypasses turbo entirely\n{\n  \"scripts\": {\n    \"build\": \"bun build\",\n    \"dev\": \"bun dev\"\n  }\n}\n\n// CORRECT - delegates to turbo\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"dev\": \"turbo run dev\"\n  }\n}\n```\n\n### Using `&&` to Chain Turbo Tasks\n\nDon''t chain turbo tasks with `&&`. Let turbo orchestrate.\n\n```json\n// WRONG - turbo task not using turbo run\n{\n  \"scripts\": {\n    \"changeset:publish\": \"bun build && changeset publish\"\n  }\n}\n\n// CORRECT\n{\n  \"scripts\": {\n    \"changeset:publish\": \"turbo run build && changeset publish\"\n  }\n}\n```\n\n### `prebuild` Scripts That Manually Build Dependencies\n\nScripts like `prebuild` that manually build other packages bypass Turborepo''s dependency graph.\n\n```json\n// WRONG - manually building dependencies\n{\n  \"scripts\": {\n    \"prebuild\": \"cd ../../packages/types && bun run build && cd ../utils && bun run build\",\n    \"build\": \"next build\"\n  }\n}\n```\n\n**However, the fix depends on whether workspace dependencies are declared:**\n\n1. **If dependencies ARE declared** (e.g., `\"@repo/types\": \"workspace:*\"` in package.json), remove the `prebuild` script. Turbo''s `dependsOn: [\"^build\"]` handles this automatically.\n\n2. **If dependencies are NOT declared**, the `prebuild` exists because `^build` won''t trigger without a dependency relationship. The fix is to:\n   - Add the dependency to package.json: `\"@repo/types\": \"workspace:*\"`\n   - Then remove the `prebuild` script\n\n```json\n// CORRECT - declare dependency, let turbo handle build order\n// package.json\n{\n  \"dependencies\": {\n    \"@repo/types\": \"workspace:*\",\n    \"@repo/utils\": \"workspace:*\"\n  },\n  \"scripts\": {\n    \"build\": \"next build\"\n  }\n}\n\n// turbo.json\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    }\n  }\n}\n```\n\n**Key insight:** `^build` only runs build in packages listed as dependencies. No dependency declaration = no automatic build ordering.\n\n### Overly Broad `globalDependencies`\n\n`globalDependencies` affects ALL tasks in ALL packages. Be specific.\n\n```json\n// WRONG - heavy hammer, affects all hashes\n{\n  \"globalDependencies\": [\"**/.env.*local\"]\n}\n\n// BETTER - move to task-level inputs\n{\n  \"globalDependencies\": [\".env\"],\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"],\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n```\n\n### Repetitive Task Configuration\n\nLook for repeated configuration across tasks that can be collapsed. Turborepo supports shared configuration patterns.\n\n```json\n// WRONG - repetitive env and inputs across tasks\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"]\n    },\n    \"test\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"]\n    },\n    \"dev\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"],\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n\n// BETTER - use globalEnv and globalDependencies for shared config\n{\n  \"globalEnv\": [\"API_URL\", \"DATABASE_URL\"],\n  \"globalDependencies\": [\".env*\"],\n  \"tasks\": {\n    \"build\": {},\n    \"test\": {},\n    \"dev\": {\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\n**When to use global vs task-level:**\n\n- `globalEnv` / `globalDependencies` - affects ALL tasks, use for truly shared config\n- Task-level `env` / `inputs` - use when only specific tasks need it\n\n### NOT an Anti-Pattern: Large `env` Arrays\n\nA large `env` array (even 50+ variables) is **not** a problem. It usually means the user was thorough about declaring their build''s environment dependencies. Do not flag this as an issue.\n\n### Using `--parallel` Flag\n\nThe `--parallel` flag bypasses Turborepo''s dependency graph. If tasks need parallel execution, configure `dependsOn` correctly instead.\n\n```bash\n# WRONG - bypasses dependency graph\nturbo run lint --parallel\n\n# CORRECT - configure tasks to allow parallel execution\n# In turbo.json, set dependsOn appropriately (or use transit nodes)\nturbo run lint\n```\n\n### Package-Specific Task Overrides in Root turbo.json\n\nWhen multiple packages need different task configurations, use **Package Configurations** (`turbo.json` in each package) instead of cluttering root `turbo.json` with `package#task` overrides.\n\n```json\n// WRONG - root turbo.json with many package-specific overrides\n{\n  \"tasks\": {\n    \"test\": { \"dependsOn\": [\"build\"] },\n    \"@repo/web#test\": { \"outputs\": [\"coverage/**\"] },\n    \"@repo/api#test\": { \"outputs\": [\"coverage/**\"] },\n    \"@repo/utils#test\": { \"outputs\": [] },\n    \"@repo/cli#test\": { \"outputs\": [] },\n    \"@repo/core#test\": { \"outputs\": [] }\n  }\n}\n\n// CORRECT - use Package Configurations\n// Root turbo.json - base config only\n{\n  \"tasks\": {\n    \"test\": { \"dependsOn\": [\"build\"] }\n  }\n}\n\n// packages/web/turbo.json - package-specific override\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"test\": { \"outputs\": [\"coverage/**\"] }\n  }\n}\n\n// packages/api/turbo.json\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"test\": { \"outputs\": [\"coverage/**\"] }\n  }\n}\n```\n\n**Benefits of Package Configurations:**\n\n- Keeps configuration close to the code it affects\n- Root turbo.json stays clean and focused on base patterns\n- Easier to understand what''s special about each package\n- Works with `$TURBO_EXTENDS$` to inherit + extend arrays\n\n**When to use `package#task` in root:**\n\n- Single package needs a unique dependency (e.g., `\"deploy\": { \"dependsOn\": [\"web#build\"] }`)\n- Temporary override while migrating\n\nSee `references/configuration/RULE.md#package-configurations` for full details.\n\n### Using `../` to Traverse Out of Package in `inputs`\n\nDon''t use relative paths like `../` to reference files outside the package. Use `$TURBO_ROOT$` instead.\n\n```json\n// WRONG - traversing out of package\n{\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \"../shared-config.json\"]\n    }\n  }\n}\n\n// CORRECT - use $TURBO_ROOT$ for repo root\n{\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \"$TURBO_ROOT$/shared-config.json\"]\n    }\n  }\n}\n```\n\n### Missing `outputs` for File-Producing Tasks\n\n**Before flagging missing `outputs`, check what the task actually produces:**\n\n1. Read the package''s script (e.g., `\"build\": \"tsc\"`, `\"test\": \"vitest\"`)\n2. Determine if it writes files to disk or only outputs to stdout\n3. Only flag if the task produces files that should be cached\n\n```json\n// WRONG: build produces files but they''re not cached\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    }\n  }\n}\n\n// CORRECT: build outputs are cached\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n```\n\nCommon outputs by framework:\n\n- Next.js: `[\".next/**\", \"!.next/cache/**\"]`\n- Vite/Rollup: `[\"dist/**\"]`\n- tsc: `[\"dist/**\"]` or custom `outDir`\n\n**TypeScript `--noEmit` can still produce cache files:**\n\nWhen `incremental: true` in tsconfig.json, `tsc --noEmit` writes `.tsbuildinfo` files even without emitting JS. Check the tsconfig before assuming no outputs:\n\n```json\n// If tsconfig has incremental: true, tsc --noEmit produces cache files\n{\n  \"tasks\": {\n    \"typecheck\": {\n      \"outputs\": [\"node_modules/.cache/tsbuildinfo.json\"] // or wherever tsBuildInfoFile points\n    }\n  }\n}\n```\n\nTo determine correct outputs for TypeScript tasks:\n\n1. Check if `incremental` or `composite` is enabled in tsconfig\n2. Check `tsBuildInfoFile` for custom cache location (default: alongside `outDir` or in project root)\n3. If no incremental mode, `tsc --noEmit` produces no files\n\n### `^build` vs `build` Confusion\n\n```json\n{\n  \"tasks\": {\n    // ^build = run build in DEPENDENCIES first (other packages this one imports)\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    },\n    // build (no ^) = run build in SAME PACKAGE first\n    \"test\": {\n      \"dependsOn\": [\"build\"]\n    },\n    // pkg#task = specific package''s task\n    \"deploy\": {\n      \"dependsOn\": [\"web#build\"]\n    }\n  }\n}\n```\n\n### Environment Variables Not Hashed\n\n```json\n// WRONG: API_URL changes won''t cause rebuilds\n{\n  \"tasks\": {\n    \"build\": {\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n\n// CORRECT: API_URL changes invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"outputs\": [\"dist/**\"],\n      \"env\": [\"API_URL\", \"API_KEY\"]\n    }\n  }\n}\n```\n\n### `.env` Files Not in Inputs\n\nTurbo does NOT load `.env` files - your framework does. But Turbo needs to know about changes:\n\n```json\n// WRONG: .env changes don''t invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\"]\n    }\n  }\n}\n\n// CORRECT: .env file changes invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env\", \".env.*\"]\n    }\n  }\n}\n```\n\n### Root `.env` File in Monorepo\n\nA `.env` file at the repo root is an anti-pattern — even for small monorepos or starter templates. It creates implicit coupling between packages and makes it unclear which packages depend on which variables.\n\n```\n// WRONG - root .env affects all packages implicitly\nmy-monorepo/\n├── .env              # Which packages use this?\n├── apps/\n│   ├── web/\n│   └── api/\n└── packages/\n\n// CORRECT - .env files in packages that need them\nmy-monorepo/\n├── apps/\n│   ├── web/\n│   │   └── .env      # Clear: web needs DATABASE_URL\n│   └── api/\n│       └── .env      # Clear: api needs API_KEY\n└── packages/\n```\n\n**Problems with root `.env`:**\n\n- Unclear which packages consume which variables\n- All packages get all variables (even ones they don''t need)\n- Cache invalidation is coarse-grained (root .env change invalidates everything)\n- Security risk: packages may accidentally access sensitive vars meant for others\n- Bad habits start small — starter templates should model correct patterns\n\n**If you must share variables**, use `globalEnv` to be explicit about what''s shared, and document why.\n\n### Strict Mode Filtering CI Variables\n\nBy default, Turborepo filters environment variables to only those in `env`/`globalEnv`. CI variables may be missing:\n\n```json\n// If CI scripts need GITHUB_TOKEN but it''s not in env:\n{\n  \"globalPassThroughEnv\": [\"GITHUB_TOKEN\", \"CI\"],\n  \"tasks\": { ... }\n}\n```\n\nOr use `--env-mode=loose` (not recommended for production).\n\n### Shared Code in Apps (Should Be a Package)\n\n```\n// WRONG: Shared code inside an app\napps/\n  web/\n    shared/          # This breaks monorepo principles!\n      utils.ts\n\n// CORRECT: Extract to a package\npackages/\n  utils/\n    src/utils.ts\n```\n\n### Accessing Files Across Package Boundaries\n\n```typescript\n// WRONG: Reaching into another package''s internals\nimport { Button } from \"../../packages/ui/src/button\";\n\n// CORRECT: Install and import properly\nimport { Button } from \"@repo/ui/button\";\n```\n\n### Too Many Root Dependencies\n\n```json\n// WRONG: App dependencies in root\n{\n  \"dependencies\": {\n    \"react\": \"^18\",\n    \"next\": \"^14\"\n  }\n}\n\n// CORRECT: Only repo tools in root\n{\n  \"devDependencies\": {\n    \"turbo\": \"latest\"\n  }\n}\n```\n\n## Common Task Configurations\n\n### Standard Build Pipeline\n\n```json\n{\n  \"$schema\": \"https://turborepo.dev/schema.v2.json\",\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\", \".next/**\", \"!.next/cache/**\"]\n    },\n    \"dev\": {\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\nAdd a `transit` task if you have tasks that need parallel execution with cache invalidation (see below).\n\n### Dev Task with `^dev` Pattern (for `turbo watch`)\n\nA `dev` task with `dependsOn: [\"^dev\"]` and `persistent: false` in root turbo.json may look unusual but is **correct for `turbo watch` workflows**:\n\n```json\n// Root turbo.json\n{\n  \"tasks\": {\n    \"dev\": {\n      \"dependsOn\": [\"^dev\"],\n      \"cache\": false,\n      \"persistent\": false  // Packages have one-shot dev scripts\n    }\n  }\n}\n\n// Package turbo.json (apps/web/turbo.json)\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"dev\": {\n      \"persistent\": true  // Apps run long-running dev servers\n    }\n  }\n}\n```\n\n**Why this works:**\n\n- **Packages** (e.g., `@acme/db`, `@acme/validators`) have `\"dev\": \"tsc\"` — one-shot type generation that completes quickly\n- **Apps** override with `persistent: true` for actual dev servers (Next.js, etc.)\n- **`turbo watch`** re-runs the one-shot package `dev` scripts when source files change, keeping types in sync\n\n**Intended usage:** Run `turbo watch dev` (not `turbo run dev`). Watch mode re-executes one-shot tasks on file changes while keeping persistent tasks running.\n\n**Alternative pattern:** Use a separate task name like `prepare` or `generate` for one-shot dependency builds to make the intent clearer:\n\n```json\n{\n  \"tasks\": {\n    \"prepare\": {\n      \"dependsOn\": [\"^prepare\"],\n      \"outputs\": [\"dist/**\"]\n    },\n    \"dev\": {\n      \"dependsOn\": [\"prepare\"],\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\n### Transit Nodes for Parallel Tasks with Cache Invalidation\n\nSome tasks can run in parallel (don''t need built output from dependencies) but must invalidate cache when dependency source code changes.\n\n**The problem with `dependsOn: [\"^taskname\"]`:**\n\n- Forces sequential execution (slow)\n\n**The problem with `dependsOn: []` (no dependencies):**\n\n- Allows parallel execution (fast)\n- But cache is INCORRECT - changing dependency source won''t invalidate cache\n\n**Transit Nodes solve both:**\n\n```json\n{\n  \"tasks\": {\n    \"transit\": { \"dependsOn\": [\"^transit\"] },\n    \"my-task\": { \"dependsOn\": [\"transit\"] }\n  }\n}\n```\n\nThe `transit` task creates dependency relationships without matching any actual script, so tasks run in parallel with correct cache invalidation.\n\n**How to identify tasks that need this pattern:** Look for tasks that read source files from dependencies but don''t need their build outputs.\n\n### With Environment Variables\n\n```json\n{\n  \"globalEnv\": [\"NODE_ENV\"],\n  \"globalDependencies\": [\".env\"],\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\"],\n      \"env\": [\"API_URL\", \"DATABASE_URL\"]\n    }\n  }\n}\n```\n\n## Reference Index\n\n### Configuration\n\n| File                                                                            | Purpose                                                  |\n| ------------------------------------------------------------------------------- | -------------------------------------------------------- |\n| [configuration/RULE.md](./references/configuration/RULE.md)                     | turbo.json overview, Package Configurations              |\n| [configuration/tasks.md](./references/configuration/tasks.md)                   | dependsOn, outputs, inputs, env, cache, persistent       |\n| [configuration/global-options.md](./references/configuration/global-options.md) | globalEnv, globalDependencies, cacheDir, daemon, envMode |\n| [configuration/gotchas.md](./references/configuration/gotchas.md)               | Common configuration mistakes                            |\n\n### Caching\n\n| File                                                            | Purpose                                      |\n| --------------------------------------------------------------- | -------------------------------------------- |\n| [caching/RULE.md](./references/caching/RULE.md)                 | How caching works, hash inputs               |\n| [caching/remote-cache.md](./references/caching/remote-cache.md) | Vercel Remote Cache, self-hosted, login/link |\n| [caching/gotchas.md](./references/caching/gotchas.md)           | Debugging cache misses, --summarize, --dry   |\n\n### Environment Variables\n\n| File                                                          | Purpose                                   |\n| ------------------------------------------------------------- | ----------------------------------------- |\n| [environment/RULE.md](./references/environment/RULE.md)       | env, globalEnv, passThroughEnv            |\n| [environment/modes.md](./references/environment/modes.md)     | Strict vs Loose mode, framework inference |\n| [environment/gotchas.md](./references/environment/gotchas.md) | .env files, CI issues                     |\n\n### Filtering\n\n| File                                                        | Purpose                  |\n| ----------------------------------------------------------- | ------------------------ |\n| [filtering/RULE.md](./references/filtering/RULE.md)         | --filter syntax overview |\n| [filtering/patterns.md](./references/filtering/patterns.md) | Common filter patterns   |\n\n### CI/CD\n\n| File                                                      | Purpose                         |\n| --------------------------------------------------------- | ------------------------------- |\n| [ci/RULE.md](./references/ci/RULE.md)                     | General CI principles           |\n| [ci/github-actions.md](./references/ci/github-actions.md) | Complete GitHub Actions setup   |\n| [ci/vercel.md](./references/ci/vercel.md)                 | Vercel deployment, turbo-ignore |\n| [ci/patterns.md](./references/ci/patterns.md)             | --affected, caching strategies  |\n\n### CLI\n\n| File                                            | Purpose                                       |\n| ----------------------------------------------- | --------------------------------------------- |\n| [cli/RULE.md](./references/cli/RULE.md)         | turbo run basics                              |\n| [cli/commands.md](./references/cli/commands.md) | turbo run flags, turbo-ignore, other commands |\n\n### Best Practices\n\n| File                                                                          | Purpose                                                         |\n| ----------------------------------------------------------------------------- | --------------------------------------------------------------- |\n| [best-practices/RULE.md](./references/best-practices/RULE.md)                 | Monorepo best practices overview                                |\n| [best-practices/structure.md](./references/best-practices/structure.md)       | Repository structure, workspace config, TypeScript/ESLint setup |\n| [best-practices/packages.md](./references/best-practices/packages.md)         | Creating internal packages, JIT vs Compiled, exports            |\n| [best-practices/dependencies.md](./references/best-practices/dependencies.md) | Dependency management, installing, version sync                 |\n\n### Watch Mode\n\n| File                                        | Purpose                                         |\n| ------------------------------------------- | ----------------------------------------------- |\n| [watch/RULE.md](./references/watch/RULE.md) | turbo watch, interruptible tasks, dev workflows |\n\n### Boundaries (Experimental)\n\n| File                                                  | Purpose                                               |\n| ----------------------------------------------------- | ----------------------------------------------------- |\n| [boundaries/RULE.md](./references/boundaries/RULE.md) | Enforce package isolation, tag-based dependency rules |\n\n## Source Documentation\n\nThis skill is based on the official Turborepo documentation at:\n\n- Source: `docs/site/content/docs/` in the Turborepo repository\n- Live: https://turborepo.dev/docs\n"},"lastSynced":"2026-03-04T14:30:25.350Z","agentAnalysis":{"suitability":{"en":"Perfect for JavaScript/TypeScript Agent Developers needing high-performance monorepo build systems with parallel task execution and caching.","zh":"适合需要高性能单体仓库构建系统、并行任务执行和缓存的JavaScript/TypeScript代理开发人员。","ja":"JavaScript/TypeScriptエージェント開発者が、高パフォーマンスのモノレポビルドシステム、並列タスク実行、キャッシングを必要とする場合に適しています。","ko":"고성능 모노레포 빌드 시스템, 병렬 태스크 실행 및 캐싱이 필요한 JavaScript/TypeScript 에이전트 개발자에게 적합합니다.","es":"Perfecto para desarrolladores de Agentes JavaScript/TypeScript que necesitan sistemas de compilación de monorepo de alto rendimiento con ejecución de tareas en paralelo y caché.","fr":"Parfait pour les développeurs d''Agents JavaScript/TypeScript ayant besoin de systèmes de build de monorepo haute performance avec exécution de tâches en parallèle et mise en cache.","de":"Perfekt für JavaScript/TypeScript-Agent-Entwickler, die hochleistungsstarke Monorepo-Build-Systeme mit paralleler Task-Ausführung und Caching benötigen.","pt":"Perfeito para desenvolvedores de Agentes JavaScript/TypeScript que necessitam de sistemas de compilação de monorepo de alto desempenho com execução de tarefas paralelas e cache.","ru":"Идеально для разработчиков агентов JavaScript/TypeScript, которым необходимы высокопроизводительные системы сборки монорепов с параллельным выполнением задач и кэшированием.","ar":"เหมาะ للطورين لغة JavaScript/TypeScript الذين يحتاجون إلى أنظمة بناء مونوربو عالية الأداء مع تنفيذ مهام متوازي وتخزين مؤقت."},"recommendation":{"en":"Empowers agents to optimize JavaScript/TypeScript monorepos by caching task outputs, running tasks in parallel based on dependency graphs, and managing tasks via turbo.json configurations, ensuring efficient package management and root task delegation.","zh":"赋予代理优化JavaScript/TypeScript单体仓库的能力，通过缓存任务输出、基于依赖图并行运行任务和管理turbo.json配置，确保高效的包管理和根任务委托。","ja":"エージェントにJavaScript/TypeScriptモノレポを最適化する能力を与え、タスク出力をキャッシングし、依存関係グラフに基づいてタスクを並列に実行し、turbo.json構成を介してタスクを管理することで、効率的なパッケージ管理とルートタスクの委譲を保証します。","ko":"에이전트에게 JavaScript/TypeScript 모노레포를 최적화하는 능력을 부여하여, 태스크 출력을 캐싱하고, 의존성 그래프에 따라 태스크를 병렬로 실행하며, turbo.json 구성으로 태스크를 관리하여 효율적인 패키지 관리와 루트 태스크 위임을 보장합니다.","es":"Habilita a los agentes a optimizar monorepos de JavaScript/TypeScript al cachear las salidas de las tareas, ejecutar tareas en paralelo en función de los gráficos de dependencias y administrar tareas a través de configuraciones turbo.json, garantizando una gestión de paquetes eficiente y la delegación de tareas raíz.","fr":"Permet aux agents d''optimiser les monorepos JavaScript/TypeScript en mettant en cache les sorties de tâches, en exécutant des tâches en parallèle en fonction des graphiques de dépendances et en gérant des tâches via des configurations turbo.json, assurant ainsi une gestion de paquets efficace et une délégation de tâches racine.","de":"Ermächtigt Agenten, JavaScript/TypeScript-Monorepos zu optimieren, indem Task-Ausgaben zwischengespeichert, Tasks basierend auf Abhängigkeitsgraphen parallel ausgeführt und Tasks über turbo.json-Konfigurationen verwaltet werden, wodurch eine effiziente Paketverwaltung und die Delegation von Root-Tasks gewährleistet werden.","pt":"Habilita os agentes a otimizar monorepos JavaScript/TypeScript, armazenando os resultados das tarefas em cache, executando tarefas em paralelo com base em gráficos de dependência e gerenciando tarefas via configurações turbo.json, garantindo gerenciamento eficiente de pacotes e delegação de tarefas raiz.","ru":"Наделяет агентов возможностью оптимизировать монорепос JavaScript/TypeScript, кэшируя выводы задач, выполняя задачи параллельно на основе графиков зависимостей и управляя задачами через конфигурации turbo.json, обеспечивая эффективное управление пакетами и делегирование корневых задач.","ar":"يمنح الوكلاء القدرة على تحسين مونوربو لغة JavaScript/TypeScript عن طريق تخزين مخرجات المهام في الذاكرة المؤقتة وتنفيذ المهام بالتوازي بناءً على رسومات الاعتماد وإدارة المهام من خلال إعدادات turbo.json، مما يضمن إدارة فعالة للحزم وتفويض المهام الجذرية."},"useCases":{"en":["Automating build processes for large-scale JavaScript/TypeScript projects","Optimizing task execution times using parallel processing and caching","Managing complex dependency graphs across monorepo packages"],"zh":["自动化大规模JavaScript/TypeScript项目的构建流程","使用并行处理和缓存优化任务执行时间","管理单体仓库包之间的复杂依赖图"],"ja":["大規模なJavaScript/TypeScriptプロジェクトのビルドプロセスを自動化する","並列処理とキャッシングを使用してタスク実行時間を最適化する","モノレポパッケージ間の複雑な依存関係グラフを管理する"],"ko":["대규모 JavaScript/TypeScript 프로젝트의 빌드 프로세스를 자동화하는 것","병렬 처리와 캐싱을 사용하여 태스크 실행 시간을 최적화하는 것","모노레포 패키지 간의 복잡한 의존성 그래프를 관리하는 것"],"es":["Automatizar procesos de compilación para proyectos JavaScript/TypeScript a gran escala","Optimizar los tiempos de ejecución de tareas mediante el procesamiento en paralelo y la caché","Administrar gráficos de dependencias complejos en paquetes de monorepo"],"fr":["Automatiser les processus de build pour les projets JavaScript/TypeScript à grande échelle","Optimiser les temps d''exécution des tâches en utilisant le traitement parallèle et la mise en cache","Gérer des graphiques de dépendances complexes à travers les paquets de monorepo"],"de":["Automatisierung von Build-Prozessen für groß angelegte JavaScript/TypeScript-Projekte","Optimierung der Task-Ausführungszeiten unter Verwendung von parallelem Verarbeiten und Caching","Verwaltung komplexer Abhängigkeitsgraphen über Monorepo-Pakete hinweg"],"pt":["Automatizar processos de compilação para projetos JavaScript/TypeScript de grande escala","Otimizar tempos de execução de tarefas usando processamento paralelo e cache","Gerenciar grafos de dependência complexos em pacotes de monorepo"],"ru":["Автоматизация процессов сборки для проектов JavaScript/TypeScript крупного масштаба","Оптимизация времени выполнения задач с помощью параллельной обработки и кэширования","Управление сложными графами зависимостей между пакетами монорепов"],"ar":["تأتمة عمليات البناء للمشاريع كبيرة النطاق بلغة JavaScript/TypeScript","تحسين أوقات تنفيذ المهام باستخدام المعالجة المتوازية والتخزين المؤقت","إدارة رسومات الاعتماد المعقدة عبر حزم مونوربو"]},"limitations":{"en":["Requires turbo.json configuration","JavaScript/TypeScript monorepos only","Root tasks must delegate via ''turbo run <task>''"],"zh":["需要turbo.json配置","仅适用于JavaScript/TypeScript单体仓库","根任务必须通过''turbo run <task>''委托"],"ja":["turbo.json構成が必要","JavaScript/TypeScriptモノレポのみ","ルートタスクは''turbo run <task>''を介して委譲する必要がある"],"ko":["turbo.json 구성이 필요합니다.","JavaScript/TypeScript 모노레포만 지원합니다.","루트 태스크는 ''turbo run <task>''를 통해 위임해야 합니다."],"es":["Requiere configuración turbo.json","Solo monorepos de JavaScript/TypeScript","Tareas raíz deben delegar a través de ''turbo run <task>''"],"fr":["Nécessite une configuration turbo.json","Monorepos JavaScript/TypeScript uniquement","Les tâches racine doivent déléguer via ''turbo run <task>''"],"de":["Benötigt turbo.json-Konfiguration","Nur JavaScript/TypeScript-Monorepos","Root-Tasks müssen über ''turbo run <task>'' delegieren"],"pt":["Requer configuração turbo.json","Apenas monorepos JavaScript/TypeScript","Tarefas raiz devem delegar via ''turbo run <task>''"],"ru":["Требуется конфигурация turbo.json","Только монорепос JavaScript/TypeScript","Корневые задачи должны делегировать через ''turbo run <task>''"],"ar":["يتطلب إعدادات turbo.json","مونوربو لغة JavaScript/TypeScript فقط","المراحل الجذرية يجب أن تفوض عبر ''turbo run <task>''"]},"version":3},"contentHash":"390f3a791150b139a8e8eb995cd4e81a3b8b05ce90fe1136964e335abb19e5b7","qualityScore":45}');
