INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Open-Earth-Foundation/CityCatalyst/repo-doc-audit', 'repo-doc-audit', 'Open-Earth-Foundation', 'CityCatalyst', 'community', 'repo-doc-audit Open-Earth-Foundation CityCatalyst community repo-doc-audit 是一个开源的城市碳排放核算 AI 工具，帮助开发者计算和管理城市碳足迹 repo-doc-audit は、都市の炭素排出量を計算および管理するためのオープンソース AI エージェントです repo-doc-audit은 도시의 탄소排출량을 계산하고 관리하는 데 도움이 되는 오픈소스 AI 에이전트입니다 repo-doc-audit es una herramienta de código abierto para la contabilidad de carbono en ciudades, utilizando inteligencia artificial para auditar y mejorar la sostenibilidad repo-doc-audit est un outil open source pour la comptabilité carbone dans les villes, utilisant l''intelligence artificielle pour auditer et améliorer la durabilité repo-doc-audit ist ein Open-Source-Tool für die Kohlenstoffbilanz in Städten, das künstliche Intelligenz nutzt, um die Nachhaltigkeit zu überprüfen und zu verbessern O repo-doc-audit é uma ferramenta de contabilidade de carbono aberta para cidades, ajudando a reduzir a pegada de carbono ИИ Агенты repo-doc-audit - это открытый инструмент учета углерода для городов, помогающий уменьшить углеродный след أدوات المحاسبة الكربونية المفتوحة repo-doc-audit هي أداة لحساب الكربون المفتوحة للمدن، تساعد في تقليل بصمتها الكربونية Open Source carbon accounting for cities 如何使用 repo-doc-audit 什么是城市碳排放核算 repo-doc-audit 安装 repo-doc-audit 教程 城市碳排放核算工具 开源 AI 工具 repo-doc-audit 与其他工具的比较 Open Source carbon accounting for cities');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/github-search', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'github-search', 0, 0, 45, '2026-02-24T11:52:28.980Z', '2026-02-24T11:52:35.462Z', '6bb106204adc91adfcf7e7e98263735ea30df9cbbbb599d1db32931ff91bb04b', '{"id":"majiayu000/claude-skill-registry/github-search","name":"github-search","description":{"zh":"GitHub 搜索技能提供了一种快速高效的方式来搜索 GitHub 仓库、代码、问题和拉取请求。使用 gh 命令行工具进行搜索。","ja":"GitHub 検索スキルは、GitHub リポジトリ、コード、問題、プルリクエストを迅速に検索するための効率的な方法を提供します。gh コマンドラインツールを使用して検索します。","ko":"GitHub 검색 스킬은 GitHub 저장소, 코드, 문제 및 풀 리퀘스트를 빠르게 검색할 수 있는 효율적인 방법을 제공합니다. gh 명령줄 도구를 사용하여 검색합니다.","es":"La búsqueda de GitHub es una herramienta poderosa para encontrar recursos y solucionar problemas. Aprende a utilizar comandos y patrones de búsqueda para mejorar tu productividad","fr":"La recherche GitHub est un outil puissant pour trouver des ressources et résoudre des problèmes. Apprenez à utiliser des commandes et des modèles de recherche pour améliorer votre productivité","de":"Die GitHub-Suche ist ein leistungsfähiges Tool, um Ressourcen zu finden und Probleme zu lösen. Lernen Sie, Befehle und Suchmuster zu verwenden, um Ihre Produktivität zu steigern","pt":"O GitHub Search é uma ferramenta poderosa para desenvolvedores, permitindo buscar repositórios, código, problemas e PRs de forma rápida e eficiente","ru":"GitHub Search - это мощный инструмент для разработчиков, позволяющий быстро и эффективно искать репозитории, код, проблемы и PR","ar":"بحث جيت هاب هو أداة قوية للمطورين، مما يسمح للبحث عن المستودعات والكود والمشاكل والطلبات سحب بسرعة وكفاءة","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"GitHub 搜索技能 - Claude Code","ja":"GitHub 検索スキル - Claude Code","ko":"GitHub 검색