INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/github-search', 'github-search', 'majiayu000', 'claude-skill-registry', 'community', 'github-search majiayu000 claude-skill-registry community GitHub 搜索技能提供了一种快速高效的方式来搜索 GitHub 仓库、代码、问题和拉取请求。使用 gh 命令行工具进行搜索。 GitHub 検索スキルは、GitHub リポジトリ、コード、問題、プルリクエストを迅速に検索するための効率的な方法を提供します。gh コマンドラインツールを使用して検索します。 GitHub 검색 스킬은 GitHub 저장소, 코드, 문제 및 풀 리퀘스트를 빠르게 검색할 수 있는 효율적인 방법을 제공합니다. gh 명령줄 도구를 사용하여 검색합니다. La búsqueda de GitHub es una herramienta poderosa para encontrar recursos y solucionar problemas. Aprende a utilizar comandos y patrones de búsqueda para mejorar tu productividad La recherche GitHub est un outil puissant pour trouver des ressources et résoudre des problèmes. Apprenez à utiliser des commandes et des modèles de recherche pour améliorer votre productivité Die GitHub-Suche ist ein leistungsfähiges Tool, um Ressourcen zu finden und Probleme zu lösen. Lernen Sie, Befehle und Suchmuster zu verwenden, um Ihre Produktivität zu steigern O GitHub Search é uma ferramenta poderosa para desenvolvedores, permitindo buscar repositórios, código, problemas e PRs de forma rápida e eficiente GitHub Search - это мощный инструмент для разработчиков, позволяющий быстро и эффективно искать репозитории, код, проблемы и PR بحث جيت هاب هو أداة قوية للمطورين، مما يسمح للبحث عن المستودعات والكود والمشاكل والطلبات سحب بسرعة وكفاءة The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app GitHub 搜索 gh 命令行工具 仓库搜索 代码搜索 问题搜索 拉取请求搜索 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/gh-discussions-answerer', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'gh-discussions-answerer', 0, 0, 45, '2026-02-20T04:13:19.570Z', '2026-02-20T04:17:04.681Z', '4621086a327532d50f910f4ab233a27ffc5e0d386a2fbca6dfb4e58fe8102d4a', '{"id":"majiayu000/claude-skill-registry/gh-discussions-answerer","name":"gh-discussions-answerer","description":{"zh":"gh-discussions-answerer 是一个自动化回答 GitHub 讨论中的问题的技能，通过代码验证和自动发布来提高回答质量","ja":"gh-discussions-answerer は、GitHub のディスカッションでの質問に自動回答するスキルです。コード検証と自動投稿により回答の品質を高めています","ko":"gh-discussions-answerer는 GitHub 토론에서의 질문에 자동으로 답변하는 스킬로서, 코드 검증과 자동 게시를 통해 답변의 품질을 높입니다","es":"El agente gh-discussions-answerer es una herramienta que responde automáticamente a discusiones de GitHub, utilizando un flujo de trabajo en tres fases para proporcionar respuestas precisas y verificadas","fr":"L''agent gh-discussions-answerer est un outil qui répond automatiquement aux discussions GitHub, utilisant un flux de travail en trois phases pour fournir des réponses précises et vérifiées","de":"Der Agent gh-discussions-answerer ist ein Tool, das Diskussionen auf GitHub automatisch beantwortet, indem es einen dreiphasigen Arbeitsablauf verwendet, um genaue und verifizierte Antworten zu liefern","pt":"O agente de respostas de discussões do GitHub é uma ferramenta que fornece respostas automatizadas para discussões não respondidas.","ru":"Агент ответов на обсуждения GitHub - это инструмент, который предоставляет автоматические ответы на невылеченные обсуждения.","ar":"وكلاء الإجابة على مناقشات جيت هاب هي أداة تقدم إجابات آلية للمناقشات غير المجابة.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"GitHub 讨论回答器 - 自动化回答工具","ja":"GitHub Discussion Answerer - オートメーション回答ツール","ko":"GitHub 토론 답변자 - 자동화 답변 도구","es":"Respuesta automática de discusiones de GitHub","fr":"Répondeur automatique de discussions GitHub","de":"Automatischer GitHub-Diskussions-Antworter","pt":"Respostas de Discussões do GitHub","ru":"Ответы на обсуждения GitHub","ar":"إجابات مناقشات جيت هاب","en":"gh-discussions-answerer"},"description":{"zh":"gh-discussions-answerer 是一个自动化回答 GitHub 讨论中的问题的技能，通过代码验证和自动发布来提高回答质量","ja":"gh-discussions-answerer は、GitHub のディスカッションでの質問に自動回答するスキルです。コード検証と自動投稿により回答の品質を高めています","ko":"gh-discussions-answerer는 GitHub 토론에서의 질문에 자동으로 답변하는 스킬로서, 코드 검증과 자동 게시를 통해 답변의 품질을 높입니다","es":"El agente gh-discussions-answerer es una herramienta que responde automáticamente a discusiones de GitHub, utilizando un flujo de trabajo en tres fases para ...","fr":"L''agent gh-discussions-answerer est un outil qui répond automatiquement aux discussions GitHub, utilisant un flux de travail en trois phases pour fournir des...","de":"Der Agent gh-discussions-answerer ist ein Tool, das Diskussionen auf GitHub automatisch beantwortet, indem es einen dreiphasigen Arbeitsablauf verwendet, um ...","pt":"O agente de respostas de discussões do GitHub é uma ferramenta que fornece respostas automatizadas para discussões não respondidas.","ru":"Агент ответов на обсуждения GitHub - это инструмент, который предоставляет автоматические ответы на невылеченные обсуждения.","ar":"وكلاء الإجابة على مناقشات جيت هاب هي أداة تقدم إجابات آلية للمناقشات غير المجابة.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["自动化回答 GitHub 讨论中的问题","代码验证和自动发布","支持 10 个答案","100% 代码验证","自动发布答案"],"ja":["GitHub ディスカッションでの質問に自動回答する","コード検証と自動投稿","10 個の回答をサポート","100% コード検証","回答を自動投稿する"],"ko":["GitHub 토론에서의 질문에 자동으로 답변","코드 검증과 자동 게시","10개의 답변을 지원","100% 코드 검증","답변을 자동으로 게시"],"es":["Respuesta automática a discusiones de GitHub","Flujo de trabajo en tres fases para garantizar la precisión","Verificación de código a través de la CLI de GitHub","Publicación automática de respuestas verificadas","Compatibilidad con múltiples subagentes"],"fr":["Réponse automatique aux discussions GitHub","Flux de travail en trois phases pour assurer la précision","Vérification de code via la CLI de GitHub","Publication automatique de réponses vérifiées","Compatibilité avec de multiples sous-agents"],"de":["Automatische Beantwortung von Diskussionen auf GitHub","Dreiphasiger Arbeitsablauf für eine präzise Antwort","Code-Verifizierung über die GitHub-CLI","Automatische Veröffentlichung von verifizierten Antworten","Unterstützung für mehrere Subagenten"],"pt":["Respostas automatizadas para discussões não respondidas","Verificação de código via CLI do GitHub","Publicação automática de respostas verificadas","Leitura somente até a Fase 3","Suporte a múltiplas fases de workflow"],"ru":["Автоматические ответы на невылеченные обсуждения","Проверка кода через CLI GitHub","Автоматическая публикация проверенных ответов","Только чтение до Фазы 3","Поддержка нескольких фаз workflow"],"ar":["إجابات آلية للمناقشات غير المجابة","التحقق من الكود عبر واجهة سطر الأوامر جيت هاب","نشر تلقائي للإجابات الم��لة","قراءة فقط حتى المرحلة 3","دعم مراحل متعددة من سير العمل"]},"keywords":{"zh":["GitHub 讨论回答器","自动化回答工具","代码验证","自动发布","GitHub 开发工具","开发效率"],"ja":["GitHub Discussion Answerer","自動回答ツール","コード検証","自動投稿","GitHub 開発ツール","開発効率"],"ko":["GitHub 토론 답변자","자동화 답변 도구","코드 검증","자동 게시","GitHub 개발 도구","개발 효율성"],"es":["GitHub","discusiones","respuesta automática","flujo de trabajo","verificación de código","CLI de GitHub","publicación automática","subagentes"],"fr":["GitHub","discussions","réponse automatique","flux de travail","vérification de code","CLI de GitHub","publication automatique","sous-agents"],"de":["GitHub","Diskussionen","automatische Beantwortung","Arbeitsablauf","Code-Verifizierung","GitHub-CLI","automatische Veröffentlichung","Subagenten"],"pt":["GitHub Discussions","Respostas automatizadas","Verificação de código","Publicação automática","Leitura somente","Workflow de discussões"],"ru":["Обсуждения GitHub","Автоматические ответы","Проверка кода","Автоматическая публикация","Только чтение","Workflow обсуждений"],"ar":["مناقشات جيت هاب","إجابات آلية","التحقق من الكود","نشر تلقائي","قراءة فقط","سير العمل للمناقشات"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.570Z","topics":[],"category":"community","skillMd":{"name":"gh-discussions-answerer","description":"Find and answer unanswered GitHub discussions. Activate when user wants to contribute to open source discussions, help answer GitHub questions, or find discussions to answer. Delegates all work to subagents.","bodyPreview":"# GitHub Discussions Answerer\n\nAll work delegated to `general` subagents.\n\n## Constraints\n\n- **Target: 10 answers** → find 1.5x candidates\n- **Post ALL verified** (may be lower or higher, that''s fine)\n- **100% code-verified** via `gh` CLI\n- **Discard only uncertain** → post everything that passes\n- **Auto-post** immediately after analysis\n- **Read-only until Phase 3** → Phases 1-2 use only GET/query operations; no mutations\n\n## Workflow\n\n### Phase 1: Discovery\n\nSearch for unanswered discussions","body":"# GitHub Discussions Answerer\n\nAll work delegated to `general` subagents.\n\n## Constraints\n\n- **Target: 10 answers** → find 1.5x candidates\n- **Post ALL verified** (may be lower or higher, that''s fine)\n- **100% code-verified** via `gh` CLI\n- **Discard only uncertain** → post everything that passes\n- **Auto-post** immediately after analysis\n- **Read-only until Phase 3** → Phases 1-2 use only GET/query operations; no mutations\n\n## Workflow\n\n### Phase 1: Discovery\n\nSearch for unanswered discussions via GitHub API:\n\n```\ntask(subagent_type=\"general\", description=\"Search unanswered discussions\", prompt=\"\nRun these searches to find unanswered discussions. Calculate dates from today.\n\nSEARCH 1 - Last 30 days, Q&A with no replies:\ngh api graphql -f query=''{\n  search(query: \\\"is:open comments:0 created:>YYYY-MM-DD category:Q&A NOT author:bot\\\", type: DISCUSSION, first: 100) {\n    nodes { ... on Discussion { title number url bodyText repository { nameWithOwner } category { name } } }\n  }\n}''\n\nSEARCH 2 - Popular repos (stars>100), any unanswered:\ngh api graphql -f query=''{\n  search(query: \\\"is:open comments:0 stars:>100 NOT author:bot NOT title:RFC\\\", type: DISCUSSION, first: 100) {\n    nodes { ... on Discussion { title number url bodyText repository { nameWithOwner } category { name } } }\n  }\n}''\n\nSEARCH 3 - Last 14 days, Help/Support categories:\ngh api graphql -f query=''{\n  search(query: \\\"is:open comments:0 created:>YYYY-MM-DD NOT author:bot NOT title:proposal\\\", type: DISCUSSION, first: 100) {\n    nodes { ... on Discussion { title number url bodyText repository { nameWithOwner } category { name } } }\n  }\n}''\n\nMerge results, deduplicate by repo#number.\n\nINCLUDE categories (prioritized):\n1. Q&A, Questions, Help, Support, Troubleshooting (highest priority)\n2. General (if contains a question mark or asks ''how to'')\n3. Technical, Development, Usage (if asking for help)\n\nHARD SKIP (not answerable with code research):\n- Feature requests (''add X'', ''would be nice if'', ''please implement'')\n- Timeline/roadmap questions (''when will X'', ''release plan'', ''ETA'')\n- Questions only maintainers can answer (prioritization, future plans)\n- Bot-created discussions (mvnpm, dependabot, renovate, github-actions)\n- RFCs/proposals/announcements/newsletters\n- Release notes or changelogs\n- Discussions with only emoji or very short body (<20 chars)\n- Already answered discussions (comments > 0)\n\nReturn exactly 15 candidates: [repo#number] title - category\n\")\n```\n\n### Phase 2: Parallel Analysis\n\nLaunch analyses for ALL candidates in parallel (one subagent per candidate):\n\n```\ntask(subagent_type=\"general\", description=\"Analyze discussion\", prompt=\"\nAnalyze [repo]#[number]: [title]\n\nREAD-ONLY: Only use GET/query operations. Do NOT post, create, or mutate anything.\n\n1. Read discussion: gh api repos/OWNER/REPO/discussions/NUMBER\n2. Search code: gh search code ''keyword'' repo:OWNER/REPO\n3. Read files: gh api repos/OWNER/REPO/contents/PATH --jq ''.content'' | base64 -d\n4. Check README/docs for relevant info\n\nVERIFIED answers must provide ACTIONABLE value:\n- Code fixes with file:line references\n- Configuration solutions with exact syntax\n- Workarounds when expected feature is missing\n- Technical explanation of WHY something doesn''t work\n- Links to relevant documentation in the repo\n\nDISCARD if answer would just restate the question:\n- ''Feature X doesn''t exist'' (user knows, that''s why they asked)\n- ''No timeline available'' (useless)\n- ''This is a known limitation'' (without workaround)\n\nReturn VERIFIED: [1-2 sentence answer with actionable fix] OR DISCARD: [reason]\n\")\n```\n\n### Phase 3: Post All Verified\n\nPost ALL verified answers in parallel (one subagent per answer):\n\n```\ntask(subagent_type=\"general\", description=\"Post discussion answer\", prompt=\"\nPost answer for [repo]#[number]:\n\n1. Get discussion ID:\n   gh api graphql -f query=''{ repository(owner:\\\"X\\\", name:\\\"Y\\\") { discussion(number:N) { id } } }''\n\n2. Post the answer:\n   gh api graphql -f query=''mutation { addDiscussionComment(input: { discussionId: \\\"ID\\\", body: \\\"ANSWER\\\" }) { comment { url } } }''\n\n3. Unsubscribe from notifications\n   THREAD_ID=$(gh api /notifications --jq ''.[] | select(.subject.url | contains(\\\"OWNER/REPO/discussions/NUMBER\\\")) | .id'')\n   gh api -X DELETE /notifications/threads/$THREAD_ID/subscription\n\nReturn posted URL.\n\")\n```\n\n## Answer Format\n\n- 1-2 sentences max\n- File:line if relevant\n- No fluff, no AI-speak\n- Must give user something they can DO, not just confirm what they know\n"},"lastSynced":"2026-02-20T04:17:04.681Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub Integration Agents needing automated discussion answering capabilities via the GitHub CLI.","zh":"非常适合需要通过 GitHub CLI 实现自动讨论回答的 GitHub 集成代理。","ja":"GitHub CLI を使用して自動で議論に回答する機能が必要な GitHub 統合エージェントに最適です。","ko":"GitHub CLI를 통해 자동으로 토론에 답변하는 기능이 필요한 GitHub 통합 에이전트에게 완벽합니다.","es":"Perfecto para agentes de integración de GitHub que necesitan capacidades de respuesta de discusión automatizada a través de la CLI de GitHub.","fr":"Parfait pour les agents d''intégration de GitHub ayant besoin de capacités de réponse de discussion automatisées via la CLI GitHub.","de":"Perfekt für GitHub-Integration-Agents, die automatisierte Diskussionsantwortfunktionen über die GitHub-CLI benötigen.","pt":"Perfeito para Agentes de Integração do GitHub que precisam de capacidades de resposta de discussão automatizada via CLI do GitHub.","ru":"Идеально подходит для агентов интеграции GitHub, требующих автоматических возможностей ответа на обсуждения через CLI GitHub.","ar":"مثالي للوكلاء المتكاملين مع GitHub الذين بحاجة إلى قدرات الإجابة التلقائية على المناقشات عبر واجهة سطر أوامر GitHub."},"recommendation":{"en":"Empowers agents to automatically find and answer unanswered GitHub discussions using the `gh` CLI, ensuring 100% code-verified responses and auto-posting capabilities, leveraging GET/query operations for read-only analysis.","zh":"赋予代理自动查找和回答未回答的 GitHub 讨论的能力，使用 `gh` CLI 确保 100% 代码验证的响应和自动发布功能，利用 GET/查询操作进行只读分析。","ja":"エージェントが `gh` CLI を使用して自動で未回答の GitHub 議論を検索し、回答する機能を提供し、100% コード検証済みのレスポンスと自動投稿機能を保証し、GET/クエリ操作を使用して読み取り専用の分析を実行します。","ko":"에이전트가 `gh` CLI를 사용하여 자동으로 답변되지 않은 GitHub 토론을 찾고 답변할 수 있는 기능을 제공하며, 100% 코드 검증된 응답과 자동 게시 기능을 보장하며, GET/쿼리 연산을 사용하여 읽기 전용 분석을 수행합니다.","es":"Habilita a los agentes a encontrar y responder automáticamente a las discusiones no respondidas de GitHub utilizando la CLI `gh`, asegurando respuestas verificadas al 100% y capacidades de publicación automática, aprovechando las operaciones GET/consulta para el análisis de solo lectura.","fr":"Permet aux agents de trouver et de répondre automatiquement aux discussions non répondues de GitHub en utilisant la CLI `gh`, garantissant des réponses vérifiées à 100% et des capacités de publication automatique, en exploitant les opérations GET/requête pour l''analyse en lecture seule.","de":"Ermöglicht es Agenten, unbeantwortete GitHub-Diskussionen mithilfe der `gh`-CLI automatisch zu finden und zu beantworten, wodurch 100% code-verifizierte Antworten und Auto-Posten-Funktionen sichergestellt werden, indem GET/Abfrage-Operationen für die schreibgeschützte Analyse genutzt werden.","pt":"Habilita os agentes a encontrar e responder automaticamente às discussões não respondidas do GitHub usando o CLI `gh`, garantindo respostas verificadas por 100% do código e capacidades de publicação automática, utilizando operações GET/consulta para análise somente leitura.","ru":"Наделяет агентов возможностью автоматически находить и отвечать на неотвеченные обсуждения GitHub с помощью CLI `gh`, обеспечивая 100% проверенные кодом ответы и возможности автоматического размещения, используя операции GET/запрос для чтения анализа.","ar":"تمكّن الوكلاء من العثور والإجابة التلقائية على مناقشات GitHub غير المجابة باستخدام واجهة سطر أوامر `gh`، وضمان استجابات تم التحقق منها بنسبة 100% من الكود وامكانات النشر التلقائي، واستخدام عمليات GET/استعلام للتحليل القراءة فقط."},"useCases":{"en":["Automating GitHub discussion responses","Verifying answers using the GitHub CLI","Discovering unanswered discussions for immediate response"],"zh":["自动化 GitHub 讨论响应","使用 GitHub CLI 验证答案","发现未回答的讨论以进行立即响应"],"ja":["GitHub 議論の応答を自動化する","GitHub CLI を使用して回答を検証する","未回答の議論を即時対応するために発見する"],"ko":["GitHub 토론 응답 자동화","GitHub CLI를 사용하여 답변 검증","즉시 응답을 위해 답변되지 않은 토론 발견"],"es":["Automatizar las respuestas de discusión de GitHub","Verificar las respuestas mediante la CLI de GitHub","Descubrir discusiones no respondidas para una respuesta inmediata"],"fr":["Automatiser les réponses de discussion de GitHub","Vérifier les réponses à l''aide de la CLI GitHub","Découvrir les discussions non répondues pour une réponse immédiate"],"de":["GitHub-Diskussionsantworten automatisieren","Antworten mithilfe der GitHub-CLI verifizieren","Unbeantwortete Diskussionen für eine sofortige Antwort entdecken"],"pt":["Automatizar respostas de discussão do GitHub","Verificar respostas usando o CLI do GitHub","Descobrir discussões não respondidas para resposta imediata"],"ru":["Автоматизация ответов на обсуждения GitHub","Проверка ответов с помощью CLI GitHub","Обнаружение неотвеченных обсуждений для немедленного ответа"],"ar":["توفير استجابات مناقشات GitHub تلقائيًا","التحقق من الإجابات باستخدام واجهة سطر أوامر GitHub","اكتشاف المناقشات غير المجابة للاستجابة الفورية"]},"limitations":{"en":["Requires `gh` CLI installation and configuration","Read-only access until Phase 3","Limited to GitHub discussions"],"zh":["需要 `gh` CLI 安装和配置","仅在第三阶段之前提供只读访问","仅限 GitHub 讨论"],"ja":["`gh` CLI のインストールと構成が必要","フェーズ 3 までは読み取り専用のアクセス","GitHub 議論のみ"],"ko":["`gh` CLI 설치 및 구성이 필요","3단계 이전에는 읽기 전용 액세스","GitHub 토론만"],"es":["Requiere la instalación y configuración de la CLI `gh`","Acceso de solo lectura hasta la Fase 3","Limitado a discusiones de GitHub"],"fr":["Nécessite l''installation et la configuration de la CLI `gh`","Accès en lecture seule jusqu''à la Phase 3","Limité aux discussions de GitHub"],"de":["Benötigt die Installation und Konfiguration der `gh`-CLI","Schreibgeschützter Zugriff bis Phase 3","Begrenzt auf GitHub-Diskussionen"],"pt":["Requer instalação e configuração do CLI `gh`","Acesso somente leitura até a Fase 3","Limitado a discussões do GitHub"],"ru":["Требует установки и конфигурации CLI `gh`","Только чтение доступа до Фазы 3","Ограничен обсуждениями GitHub"],"ar":["يتطلب تثبيت وتهيئة واجهة سطر أوامر `gh`","وصول للقراءة فقط حتى المرحلة 3","محدود مناقشات GitHub"]},"version":3},"contentHash":"4621086a327532d50f910f4ab233a27ffc5e0d386a2fbca6dfb4e58fe8102d4a","qualityScore":45}');
