INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/gh-discussions-answerer', 'gh-discussions-answerer', 'majiayu000', 'claude-skill-registry', 'community', 'gh-discussions-answerer majiayu000 claude-skill-registry community gh-discussions-answerer 是一个自动化回答 GitHub 讨论中的问题的技能，通过代码验证和自动发布来提高回答质量 gh-discussions-answerer は、GitHub のディスカッションでの質問に自動回答するスキルです。コード検証と自動投稿により回答の品質を高めています gh-discussions-answerer는 GitHub 토론에서의 질문에 자동으로 답변하는 스킬로서, 코드 검증과 자동 게시를 통해 답변의 품질을 높입니다 El agente gh-discussions-answerer es una herramienta que responde automáticamente a discusiones de GitHub, utilizando un flujo de trabajo en tres fases para proporcionar respuestas precisas y verificadas L''agent gh-discussions-answerer est un outil qui répond automatiquement aux discussions GitHub, utilisant un flux de travail en trois phases pour fournir des réponses précises et vérifiées Der Agent gh-discussions-answerer ist ein Tool, das Diskussionen auf GitHub automatisch beantwortet, indem es einen dreiphasigen Arbeitsablauf verwendet, um genaue und verifizierte Antworten zu liefern O agente de respostas de discussões do GitHub é uma ferramenta que fornece respostas automatizadas para discussões não respondidas. Агент ответов на обсуждения GitHub - это инструмент, который предоставляет автоматические ответы на невылеченные обсуждения. وكلاء الإجابة على مناقشات جيت هاب هي أداة تقدم إجابات آلية للمناقشات غير المجابة. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app GitHub 讨论回答器 自动化回答工具 代码验证 自动发布 GitHub 开发工具 开发效率 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/github-automation', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'github-automation', 0, 0, 45, '2026-02-20T04:13:19.570Z', '2026-02-20T04:19:50.832Z', '02ae85a1a3437f52fbea300a7007ec11ca27a597fa86fe6ac9d8bbe9666eff28', '{"id":"majiayu000/claude-skill-registry/github-automation","name":"github-automation","description":{"zh":"GitHub 自动化操作技能提供仓库管理、Pull Request 和 Issue 跟踪等功能，简化开发流程","ja":"GitHub 自動化操作スキルは、リポジトリ管理、Pull Request、Issue フォローアップなどの機能を提供し、開発プロセスを簡素化します","ko":"GitHub 자동화 운영 스킬은 저장소 관리, Pull Request 및 이슈 추적 등을 제공하여 개발 프로세스를 단순화","es":"Automatiza operaciones en GitHub, incluyendo gestión de repositorios, creación de solicitudes de extracción y seguimiento de problemas","fr":"Automatisez les opérations sur GitHub, y compris la gestion de référentiels, la création de demandes d''extraction et le suivi des problèmes","de":"Automatisieren Sie Operationen auf GitHub, einschließlich Repository-Verwaltung, Erstellung von Pull-Requests und Nachverfolgung von Problemen","pt":"O Claude Code é uma ferramenta de automação para GitHub que permite criar repositórios, fazer pull requests e gerenciar issues de forma eficiente.","ru":"Claude Code - это инструмент автоматизации для GitHub, который позволяет создавать репозитории, отправлять pull requests и управлять issues эффективно.","ar":"Claude Code هو أداة آليّة لتنفيذ عمليات على GitHub التي تمكنك من إنشاء مستودعات، وارسل طلبات سحب، وادِر قضايا بفعالية.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"GitHub 自动化操作 - Claude Code 仓库管理","ja":"GitHub 自動化操作 - Claude Code リポジトリ管理","ko":"GitHub 자동화 운영 - Claude Code 저장소 관리","es":"Automatización de GitHub","fr":"Automatisation de GitHub","de":"GitHub-Automatisieru