INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('YPYT1/All-skills/github-kb', 'github-kb', 'YPYT1', 'All-skills', 'community', 'github-kb YPYT1 All-skills community GitHub 知识库管理工具，用于管理和搜索 GitHub 项目。支持设置环境变量和使用 gh CLI GitHub ナレッジベース管理ツールは、GitHub プロジェクトを管理および検索するために使用されます。環境変数の設定と gh CLI の使用をサポート GitHub 지식庫 관리 도구는 GitHub 프로젝트를 관리 및 검색하는 데 사용됩니다. 환경 변수 설정 및 gh CLI 사용 지원 La base de conocimientos de GitHub es una herramienta para gestionar y buscar proyectos en un repositorio local La base de connaissances GitHub est un outil pour gérer et rechercher des projets dans un référentiel local Die GitHub-Wissensbasis ist ein Tool zur Verwaltung und Suche von Projekten in einem lokalen Repository O GitHub Knowledge Base é uma ferramenta para gerenciar conhecimento e realizar buscas no GitHub База знаний GitHub - это инструмент для управления знаниями и поиска в GitHub قاعدة معرفة جيثب هي أداة لإدارة المعرفة والبحث في جيثب 集合了所有的openclaw,claudecode,open等各个平台所有的skills GitHub 知识库管理 GitHub 项目管理 gh CLI 环境变量设置 私有仓库管理 GitHub 搜索 集合了所有的openclaw,claudecode,open等各个平台所有的skills');
