INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NeverSight/skills_feed/secure-web-search', 'secure-web-search', 'NeverSight', 'skills_feed', 'community', 'secure-web-search NeverSight skills_feed community 本技能帮助开发者在保护隐私的同时进行安全的网页搜索，验证信息来源和准确性。 このスキルは、開発者がプライバシーを保護しながらセキュアなウェブ検索を行い、情報源と正確性を確認するのに役立ちます。 이 스킬은 개발자가 개인 정보를 보호하면서 안전한 웹 검색을 수행하고 정보 출처와 정확성을 확인하는 데 도움이 됩니다. Esta guía te ayudará a realizar búsquedas web seguras y proteger tu privacidad. Aprende a verificar fuentes y validar la exactitud de la información Ce guide vous aidera à effectuer des recherches web sécurisées et à protéger votre vie privée. Apprenez à vérifier les sources et à valider l''exactitude des informations Dieser Leitfaden hilft Ihnen, sichere Web-Suchen durchzuführen und Ihre Privatsphäre zu schützen. Erfahren Sie, wie Sie Quellen überprüfen und die Genauigkeit von Informationen validieren O Secure Web Search é uma habilidade que ajuda a realizar buscas web seguras, protegendo a privacidade e verificando a precisão das informações. Безопасный Веб-поиск - это навык, который помогает выполнять безопасные веб-поиски, защищая конфиденциальность и проверяя точность информации. بحث ويب آمن هو مهارة تساعد على إجراء عمليات بحث ويب آمنة، مع الحفاظ على الخصوصية و التحقق من دقة المعلومات. A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions. 安全网页搜索 保护隐私 验证信息来源 网页搜索技能 开发者工具 搜索引擎优化 A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/parametric-scribe', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'parametric-scribe', 0, 0, 45, '2026-02-20T04:13:19.574Z', '2026-02-20T04:35:05.294Z', '213fc914c477ba185240936fb17650b43b622dcfb2b544dfc9c2b3effd7ee4de', '{"id":"aiskillstore/marketplace/parametric-scribe","name":"parametric-scribe","description":{"zh":"Parametric Scribe, , , ","ja":"Parametric Scribe, , , ","ko":"Parametric Scribe, , , ","es":"Parametric Scribe es una habilidad de seguridad auditada que mantiene un historial paramétrico del proyecto en docs/recipe.yaml.","fr":"Parametric Scribe est une compétence de sécurité auditée qui maintient un historique paramétrique du projet dans docs/recipe.yaml.","de":"Parametric Scribe ist eine sicherheitsgeprüfte Fähigkeit, die ein parametriertes Historial des Projekts in docs/recipe.yaml aufrechterhält.","pt":"Parametric Scribe é uma ferramenta de registro de projeto que permite manter um histórico paramétrico do seu código, facilitando a colaboração e a manutenção","ru":"Параметрический Скальпель - это инструмент для записи проекта, который позволяет поддерживать параметрическую историю вашего кода, что упрощает сотрудничество и обслуживание","ar":"Parametric Scribe هي أداة لتسجيل المشروع التي تمكنك من الحفاظ على تاريخ مشروع معلمات، مما يسهل التعاون والصيانة","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"Parametric Scribe - ","ja":"Parametric Scribe - ","ko":"Parametric Scribe - ","es":"Parametric Scribe: Seguridad y auditoría de código","fr":"Parametric Scribe : Sécurité et audit de code","de":"Parametric Scribe: Sicherheit und Code-Audit","pt":"Parametric Scribe: Ferramenta de Registro de Projeto","ru":"Параметрический Скальпель: Инструмент для Записи Проекта","ar":"برامتريك سكريب: أداة لتسجيل المشروع","en":"parametric-scribe"},"description":{"zh":"Parametric Scribe, , , ","ja":"Parametric Scribe, , , ","ko":"Parametric Scribe, , , ","es":"Parametric Scribe es una habilidad de seguridad auditada que mantiene un historial paramétrico del proyecto en docs/recipe.yaml.","fr":"Parametric Scribe est une compétence de sécurité auditée qui maintient un historique paramétrique du projet dans docs/recipe.yaml.","de":"Parametric Scribe ist eine sicherheitsgeprüfte Fähigkeit, die ein parametriertes Historial des Projekts in docs/recipe.yaml aufrechterhält.","pt":"Parametric Scribe é uma ferramenta de registro de projeto que permite manter um histórico paramétrico do seu código, facilitando a colaboração e a manutenção","ru":"Параметрический Скальпель - это инструмент для записи проекта, который позволяет поддерживать параметрическую историю вашего кода, что упрощает сотрудничеств...","ar":"Parametric Scribe هي أداة لتسجيل المشروع التي تمكنك من الحفاظ على تاريخ مشروع معلمات، مما يسهل التعاون والصيانة","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"definition":{"en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"features":{"zh":["One-click ","Quality ","Parametric History","Recording","Security-audited"],"ja":["One-click ","Quality ","Parametric History","Recording","Security-audited"],"ko":["One-click ","Quality ","Parametric History","Recording","Security-audited"],"es":["Seguridad auditada para Claude, Codex y Claude Code","Instalación de un solo clic","Verificación de calidad","Historial paramétrico en docs/recipe.yaml","Registro de cambios en el proyecto"],"fr":["Sécurité auditée pour Claude, Codex et Claude Code","Installation en un seul clic","Vérification de la qualité","Historique paramétrique dans docs/recipe.yaml","Enregistrement des modifications du projet"],"de":["Sicherheitsgeprüfte Fähigkeit für Claude, Codex und Claude Code","Ein-Klick-Installation","Qualitätsprüfung","Parametriertes Historial in docs/recipe.yaml","Aufzeichnung von Änderungen am Projekt"],"pt":["Registro de alterações no código","Manutenção de um histórico paramétrico","Facilitação da colaboração e manutenção","Integração com Claude, Codex e Claude Code","Instalação de um clique e verificação de qualidade"],"ru":["Регистрация изменений в коде","Поддержка параметрической истории","Упрощение сотрудничества и обслуживания","Интеграция с Claude, Codex и Claude Code","Однократная установка и проверка качества"],"ar":["تسجيل التغييرات في الكود","الحفاظ على تاريخ مشروع معلمات","تسهيل التعاون والصيانة","التكامل مع Claude و Codex و Claude Code","التثبيت بلمسة واحدة والتحقق من الجودة"]},"keywords":{"zh":["Parametric Scribe","Coding","Security","Code Quality","Parametric History","Developer Tools"],"ja":["Parametric Scribe","Coding","Security","Code Quality","Parametric History","Developer Tools"],"ko":["Parametric Scribe","Coding","Security","Code Quality","Parametric History","Developer Tools"],"es":["seguridad de código","auditoría de código","Claude","Codex","Claude Code","historial paramétrico","desarrollo de software","seguridad informática"],"fr":["sécurité du code","audit de code","Claude","Codex","Claude Code","historique paramétrique","développement de logiciels","sécurité informatique"],"de":["Code-Sicherheit","Code-Audit","Claude","Codex","Claude Code","parametriertes Historial","Software-Entwicklung","IT-Sicherheit"],"pt":["parametric scribe","registro de projeto","histórico paramétrico","colaboração","manutenção","Claude","Codex","Claude Code"],"ru":["параметрический скальпель","запись проекта","параметрическая история","сотрудничество","обслуживание","Claude","Codex","Claude Code"],"ar":["برامتريك سكريب","تسجيل المشروع","تاريخ مشروع معلمات","التعاون","الصيانة","Claude","Codex","Claude Code"]}},"owner":"aiskillstore","repo":"marketplace","repoPath":"aiskillstore/marketplace","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.574Z","topics":[],"category":"community","skillMd":{"name":"parametric-scribe","description":"Enables Time Machine coding. Records tasks as a Recipe and allows intelligent replay/modification of history.","bodyPreview":"# Parametric Scribe\n\n## Overview\n\nYou are the Keeper of the Recipe. Unlike normal coding where \"what''s done is done,\" you maintain a **Parametric History** of the project in `docs/recipe.yaml`.\n\n## Mode 1: Recording (The default)\n\n**When:** After completing *any* coding task.\n**Action:** Append a new entry to `docs/recipe.yaml`.\n\n```yaml\n  - step_id: \"<sequential-id>\"\n    timestamp: \"<iso-date>\"\n    intent: \"<short-summary>\"\n    prompt: \"<the-exact-prompt-used>\"\n    output_files: [\"<list-of-modi","body":"# Parametric Scribe\n\n## Overview\n\nYou are the Keeper of the Recipe. Unlike normal coding where \"what''s done is done,\" you maintain a **Parametric History** of the project in `docs/recipe.yaml`.\n\n## Mode 1: Recording (The default)\n\n**When:** After completing *any* coding task.\n**Action:** Append a new entry to `docs/recipe.yaml`.\n\n```yaml\n  - step_id: \"<sequential-id>\"\n    timestamp: \"<iso-date>\"\n    intent: \"<short-summary>\"\n    prompt: \"<the-exact-prompt-used>\"\n    output_files: [\"<list-of-modified-files>\"]\n    git_sha: \"<current-head-sha>\"\n```\n\n## Mode 2: Time Travel (Replay)\n\n**When:** The user says \"Change Step X\" or \"Replay from Step X\".\n\n**The Protocol:**\n1.  **Read** `docs/recipe.yaml`.\n2.  **Identify** the Target Step (Step X).\n3.  **Hard Reset:** `git checkout <Step X-1 SHA>` (Go back to the state *before* Step X).\n4.  **Execute Target:** Run the *New Prompt* provided by the user.\n5.  **Intelligent Rebase (The Magic):**\n    *   For each Subsequent Step (Step X+1, X+2...):\n        *   Read the *Original Intent* (Prompt).\n        *   Look at the *Current Codebase* (which is now different).\n        *   **Self-Correction:** \"The original prompt asked to modify `app.py`, but we are now in `index.js`. I will apply the *intent* (Add Login) to `index.js` instead.\"\n        *   Execute the adapted prompt.\n        *   Update the `recipe.yaml` with the new file paths and SHAs.\n\n## Mode 3: Forking\n\n**When:** The user says \"Create a variant.\"\n**Action:** Copy `recipe.yaml` to `recipe-variant-b.yaml` and modify the target step there, leaving the original intact.\n"},"lastSynced":"2026-02-20T04:35:05.294Z","agentAnalysis":{"suitability":{"en":"Ideal for Claude, Codex, and Claude Code agents requiring secure and audited parametric history management for coding projects.","zh":"适用于 Claude、Codex 和 Claude Code 代理，需要安全且审计的参数历史管理用于编码项目。","ja":"Claude、Codex、Claude Code エージェントが、コードプロジェクトのための安全で監査されたパラメータ履歴管理を必要とする場合に最適です。","ko":"클라우드, 코덱스, 클라우드 코드 에이전트가 보안 및 감사된 매개변수 기록 관리를 코딩 프로젝트에 필요로 할 때 적합합니다.","es":"Ideal para los agentes Claude, Codex y Claude Code que requieren una gestión de historial paramétrico segura y auditada para proyectos de codificación.","fr":"Idéal pour les agents Claude, Codex et Claude Code nécessitant une gestion d''historique paramétrique sécurisée et auditée pour les projets de codage.","de":"Ideal für Claude-, Codex- und Claude-Code-Agents, die eine sichere und überprüfte parametrige Historienverwaltung für Codierungsprojekte erfordern.","pt":"Ideal para os agentes Claude, Codex e Claude Code que requerem gerenciamento de histórico paramétrico seguro e auditado para projetos de codificação.","ru":"Идеально подходит для агентов Claude, Codex и Claude Code, требующих безопасного и аудированного управления параметрической историей для проектов кодирования.","ar":"مثالي لعميل Claude و Codex و Claude Code الذين يتطلبون إدارة تاريخ параметري آمن ومحاسب لمشاريع الترميز."},"recommendation":{"en":"Empowers agents to maintain a parametric history of projects in YAML format, ensuring transparent and version-controlled coding processes with features like sequential step IDs, ISO date timestamps, and intent summaries, all stored in a `docs/recipe.yaml` file.","zh":"赋予代理维护项目的参数历史记录的能力，使用 YAML 格式，确保编码过程的透明和版本控制，具有顺序步骤 ID、ISO 日期时间戳和意图摘要等功能，都存储在 `docs/recipe.yaml` 文件中。","ja":"エージェントに、プロジェクトのパラメータ履歴を YAML フォーマットで保持する能力を与え、順序付きステップ ID、ISO 日付タイムスタンプ、意図の要約などの機能を備えた、透明でバージョン管理されたコード化プロセスを可能にします。これらはすべて `docs/recipe.yaml` ファイルに保存されます。","ko":"에이전트가 YAML 형식으로 프로젝트의 매개 변수 기록을 유지할 수 있는 능력을 부여하여 순차적 단계 ID, ISO 날짜 타임 스탬프 및 의도 요약 등의 기능을 갖춘 투명하고 버전 관리된 코딩 프로세스를 가능하게 합니다. 모두 `docs/recipe.yaml` 파일에 저장됩니다.","es":"Habilita a los agentes a mantener un historial paramétrico de proyectos en formato YAML, garantizando procesos de codificación transparentes y controlados por versiones con características como identificadores de paso secuenciales, marcas de tiempo de fecha ISO y resúmenes de intención, todos almacenados en un archivo `docs/recipe.yaml`.","fr":"Permet aux agents de maintenir un historique paramétrique des projets au format YAML, assurant des processus de codage transparents et contrôlés par version avec des fonctionnalités comme des identificateurs de pas séquentiels, des horodatages de date ISO et des résumés d''intention, le tout stocké dans un fichier `docs/recipe.yaml`.","de":"Ermächtigt die Agents, ein parametriertes Historienverwaltung für Projekte im YAML-Format zu pflegen, wodurch transparente und versionskontrollierte Codierungsprozesse mit Funktionen wie sequenziellen Schritt-IDs, ISO-Datums-Timestamps und Intentionssummaries gewährleistet werden, die alle in einer `docs/recipe.yaml`-Datei gespeichert sind.","pt":"Habilita os agentes a manter um histórico paramétrico dos projetos no formato YAML, garantindo processos de codificação transparentes e controlados por versão com recursos como IDs de etapa sequenciais, carimbos de data e hora no formato ISO e resumos de intenção, todos armazenados em um arquivo `docs/recipe.yaml`.","ru":"Позволяет агентам поддерживать параметрическую историю проектов в формате YAML, обеспечивая прозрачные и контролируемые версиями процессы кодирования с функциями, такими как последовательные идентификаторы шагов, метки даты и времени в формате ISO и сводки намерений, все хранящиеся в файле `docs/recipe.yaml`.","ar":"تمكّن العملاء من الحفاظ على تاريخ 参数ي للمشاريع ب-format YAML، مما يضمن عمليات ترميز شفافة ومراقبة الإصدارات باستخدام ميزات مثل معرّفات الخطوة المتسلسلة، وطوابع التاريخ والوقت بالتنسيق ISO، وتلخيصات النوايا، وكلها محفوظة في ملف `docs/recipe.yaml`."},"useCases":{"en":["Automating parametric history updates after coding tasks","Generating detailed project timelines with step IDs and timestamps","Debugging coding projects through intent summaries and output file tracking"],"zh":["自动更新编码任务后的参数历史记录","使用步骤 ID 和时间戳生成项目详细时间线","通过意图摘要和输出文件跟踪调试编码项目"],"ja":["コード化タスク後のパラメータ履歴の自動更新","ステップ ID とタイムスタンプを使用してプロジェクトの詳細なタイムラインを生成する","意図の要約と出力ファイルのトラッキングを使用してコード化プロジェクトのデバッグを行う"],"ko":["코딩 작업后的 매개 변수 기록 자동 업데이트","단계 ID 및 타임 스탬프를 사용하여 프로젝트의详细한 타임 라인 생성","의도 요약 및 출력 파일 트래킹을 통해 코딩 프로젝트 디버깅"],"es":["Automatizar actualizaciones de historial paramétrico después de tareas de codificación","Generar cronogramas de proyecto detallados con identificadores de paso y marcas de tiempo","Depurar proyectos de codificación a través de resúmenes de intención y seguimiento de archivos de salida"],"fr":["Automatiser les mises à jour d''historique paramétrique après des tâches de codage","Générer des chronologies de projet détaillées avec des identificateurs de pas et des horodatages","Déboguer les projets de codage via des résumés d''intention et un suivi des fichiers de sortie"],"de":["Automatisieren von Aktualisierungen der parametrierten Historie nach Codieraufgaben","Erstellen detaillierter Projektpläne mit Schritt-IDs und Timestamps","Fehlerbehebung bei Codierungsprojekten durch Intentionssummaries und Ausgabedateitracking"],"pt":["Automatizar atualizações de histórico paramétrico após tarefas de codificação","Gerar cronogramas de projeto detalhados com IDs de etapa e carimbos de data e hora","Depurar projetos de codificação por meio de resumos de intenção e rastreamento de arquivos de saída"],"ru":["Автоматизировать обновления параметрической истории после задач кодирования","Генерировать подробные временные шкалы проектов с идентификаторами шагов и метками даты и времени","Отлаживать проекты кодирования с помощью сводок намерений и отслеживания выходных файлов"],"ar":["تأتمتة تحديثات التاريخ Parametri بعد مهام الترميز","генерировать جداول زمنية مشروعة مفصلة مع معرّفات الخطوة وطوابع التاريخ والوقت","تصحيح أخطاء مشاريع الترميز من خلال تلخيصات النوايا وتتبع ملفات الإخراج"]},"limitations":{"en":["Requires security auditing for integration","Specifically designed for Claude, Codex, and Claude Code agents","Dependent on YAML file format for parametric history storage"],"zh":["需要集成的安全审计","专门为 Claude、Codex 和 Claude Code 代理设计","依赖 YAML 文件格式进行参数历史记录存储"],"ja":["統合のためのセキュリティ監査が必要","Claude、Codex、Claude Code エージェント専用に設計","パラメータ履歴の保存には YAML ファイル形式に依存"],"ko":["통합을 위한 보안 감사가 필요","클라우드, 코덱스, 클라우드 코드 에이전트 전용으로 설계됨","매개 변수 기록 저장에는 YAML 파일 형식에 의존"],"es":["Requiere auditoría de seguridad para la integración","Diseñado específicamente para los agentes Claude, Codex y Claude Code","Dependiente del formato de archivo YAML para el almacenamiento del historial paramétrico"],"fr":["Nécessite une audit de sécurité pour l''intégration","Conçu spécifiquement pour les agents Claude, Codex et Claude Code","Dépendant du format de fichier YAML pour le stockage de l''historique paramétrique"],"de":["Erfordert Sicherheitsaudit für die Integration","Speziell für die Agents Claude, Codex und Claude Code entwickelt","Abhängig vom YAML-Dateiformat für die Speicherung der parametrierten Historie"],"pt":["Requer auditoria de segurança para integração","Especificamente projetado para os agentes Claude, Codex e Claude Code","Depende do formato de arquivo YAML para armazenamento de histórico paramétrico"],"ru":["Требует аудита безопасности для интеграции","Специально разработан для агентов Claude, Codex и Claude Code","Зависит от формата файла YAML для хранения параметрической истории"],"ar":["يتطلب تدقيقاً أمنياً للدمج","صمّم خصيصاً لعملاء Claude و Codex و Claude Code","يعتمد على تنسيق ملف YAML لتخزين التاريخ Parametri"]},"version":3},"contentHash":"213fc914c477ba185240936fb17650b43b622dcfb2b544dfc9c2b3effd7ee4de","qualityScore":45}');
