INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/parametric-scribe', 'parametric-scribe', 'aiskillstore', 'marketplace', 'community', 'parametric-scribe aiskillstore marketplace community Parametric Scribe, , , Parametric Scribe, , , Parametric Scribe, , , Parametric Scribe es una habilidad de seguridad auditada que mantiene un historial paramétrico del proyecto en docs/recipe.yaml. Parametric Scribe est une compétence de sécurité auditée qui maintient un historique paramétrique du projet dans docs/recipe.yaml. Parametric Scribe ist eine sicherheitsgeprüfte Fähigkeit, die ein parametriertes Historial des Projekts in docs/recipe.yaml aufrechterhält. Parametric Scribe é uma ferramenta de registro de projeto que permite manter um histórico paramétrico do seu código, facilitando a colaboração e a manutenção Параметрический Скальпель - это инструмент для записи проекта, который позволяет поддерживать параметрическую историю вашего кода, что упрощает сотрудничество и обслуживание Parametric Scribe هي أداة لتسجيل المشروع التي تمكنك من الحفاظ على تاريخ مشروع معلمات، مما يسهل التعاون والصيانة Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. Parametric Scribe Coding Security Code Quality Parametric History Developer Tools Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
