INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('krishagel/geoffrey/pdf', 'pdf', 'krishagel', 'geoffrey', 'community', 'pdf krishagel geoffrey community 本指南涵盖了使用Python库和命令行工具进行PDF处理的基本操作 このガイドでは、Pythonライブラリとコマンドラインツールを使用したPDF処理の基本操作について説明します 이 가이드는 Python 라이브러리와 명령줄 도구를 사용하여 PDF를 처리하는 기본 작업을 다룹니다 Guía para procesar PDF con Python, incluyendo operaciones básicas y avanzadas para desarrolladores Guide pour traiter les PDF avec Python, incluant des opérations de base et avancées pour les développeurs Anleitung zur Verarbeitung von PDF mit Python, einschließlich grundlegender und erweiterter Operationen für Entwickler Esta guia aborda operações essenciais de processamento de PDF usando bibliotecas Python. Veja exemplos e recursos para desenvolvedores. Это руководство охватывает основные операции обработки PDF с помощью библиотек Python. Примеры и ресурсы для разработчиков. يهتم هذا الدليل بالعمليات الأساسية لمعالجة المستندات بتنسيق بي دي إف باستخدام مكتبات بايثون. انظر الأمثلة والموارد للمطورين. Personal AI infrastructure built on Claude Code PDF处理 Python库 命令行工具 PDF读取 PDF提取 PDF填写 Personal AI infrastructure built on Claude Code');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/crdt', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'crdt', 0, 0, 45, '2026-02-20T04:13:19.579Z', '2026-02-20T04:59:55.707Z', '0385d5d0542e052a2a6ce4acf1aa63bb44003528261024c6e2daa785db3f5aae', '{"id":"majiayu000/claude-skill-registry/crdt","name":"crdt","description":{"zh":"CRDT是一种强大的分布式数据管理技术，提供高效的数据同步和冲突解决","ja":"CRDTは、高性能なデータ同期と衝突解決を提供する強力な分散データ管理技術","ko":"CRDT는 효율적인 데이터 동기화와 충돌 해결을 제공하는 강력한 분산 데이터 관리 기술","es":"Las guías CRDT ofrecen directrices para la implementación efectiva de este modelo de datos. Aprende a mutar en lugar de reemplazar objetos","fr":"Les guides CRDT proposent des directives pour la mise en œuvre efficace de ce modèle de données. Apprenez à muter au lieu de remplacer des objets","de":"Die CRDT-Richtlinien bieten Richtlinien für die effektive Implementierung dieses Datenmodells. Erfahren Sie, wie Sie Objekte mutieren anstelle von ersetzen","pt":"O CRDT é um conjunto de diretrizes para mutações de estilo draft. Aprenda a usá-lo para melhorar seu código.","ru":"CRDT - это набор руководств для мутаций стиля черновика. Узнайте, как его использовать, чтобы улучшить свой код.","ar":"CRDT هو مجموعة من الإرشادات لتعديلات نمط المسودة. تعلم كيفية استخدامه لتحسين кодك.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"CRDT指南：高效的分布式数据管理","ja":"CRDTガイド：高性能な分散データ管理","ko":"CRDT 가이드: 효율적인 분산 데이터 관리","es":"Guías CRDT para desarrolladores","fr":"Guides CRDT pour les développeurs","de":"CRDT-Richtlinien für Entwickler","pt":"CRDT: Diretrizes para Mutações de Estilo Draft","ru":"CRDT: Руководство по мутациям стиля черновика","ar":"CRDT: إرشادات لتعديلات نمط المسودة","en":"crdt"},"description":{"zh":"CRDT是一种强大的分布式数据管理技术，提供高效的数据同步和冲突解决","ja":"CRDTは、高性能なデータ同期と衝突解決を提供する強力な分散データ管理技術","ko":"CRDT는 효율적인 데이터 동기화와 충돌 해결을 제공하는 강력한 분산 데이터 관리 기술","es":"Las guías CRDT ofrecen directrices para la implementación efectiva de este modelo de datos. Aprende a mutar en lugar de reemplazar objetos","fr":"Les guides CRDT proposent des directives pour la mise en œuvre efficace de ce modèle de données. Apprenez à muter au lieu de remplacer des objets","de":"Die CRDT-Richtlinien bieten Richtlinien für die effektive Implementierung dieses Datenmodells. Erfahren Sie, wie Sie Objekte mutieren anstelle von ersetzen","pt":"O CRDT é um conjunto de diretrizes para mutações de estilo draft. Aprenda a usá-lo para melhorar seu código.","ru":"CRDT - это набор руководств для мутаций стиля черновика. Узнайте, как его использовать, чтобы улучшить свой код.","ar":"CRDT هو مجموعة من الإرشادات لتعديلات نمط المسودة. تعلم كيفية استخدامه لتحسين кодك.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["支持_draft-style_的数据变更","使用_crypto.randomUUID()_生成ID","实现软删除和数据追踪","提供高效的数据同步和冲突解决"],"ja":["draft-style_のデータ変更をサポート","crypto.randomUUID()_を使用してIDを生成","ソフト削除とデータ追跡を実現","高性能なデータ同期と衝突解決を提供"],"ko":["draft-style_의 데이터 변경을 지원","crypto.randomUUID()_를 사용하여 ID를 생성","소프트 삭제와 데이터 추적을 구현","높은 성능의 데이터 동기화와 충돌 해결을 제공"],"es":["Mutaciones en lugar de reemplazo de objetos","Uso de crypto.randomUUID() para IDs","Eliminaciones suaves con marca de tiempo deletedAt","Importación de tipos desde schema.ts","Reglas para la implementación efectiva de CRDT"],"fr":["Mutations au lieu de remplacement d''objets","Utilisation de crypto.randomUUID() pour les IDs","Suppressions douces avec horodatage deletedAt","Importation de types depuis schema.ts","Règles pour la mise en œuvre efficace de CRDT"],"de":["Mutationen anstelle von Ersetzen von Objekten","Verwendung von crypto.randomUUID() für IDs","Weiche Löschungen mit Zeitstempel deletedAt","Import von Typen aus schema.ts","Regeln für die effektive Implementierung von CRDT"],"pt":["Mutações de estilo draft","Uso de crypto.randomUUID() para ID","Soft deletes com timestamp","Importação de tipos do schema.ts","Melhoria da qualidade do código"],"ru":["Мутации стиля черновика","Использование crypto.randomUUID() для ID","Мягкие удаления с временной меткой","Импорт типов из schema.ts","Улучшение качества кода"],"ar":["تعديلات نمط المسودة","استخدام crypto.randomUUID() لتحديد الهوية","الحذف الناعم مع توقيع الوقت","استيراد أنواع من schema.ts","تحسين جودة الكود"]},"keywords":{"zh":["CRDT","分布式数据管理","数据同步","冲突解决","_draft-style_","crypto.randomUUID()","软删除"],"ja":["CRDT","分散データ管理","データ同期","衝突解決","draft-style","crypto.randomUUID()","ソフト削除"],"ko":["CRDT","분산 데이터 관리","데이터 동기화","충돌 해결","draft-style","crypto.randomUUID()","소프트 삭제"],"es":["CRDT","modelo de datos","replicación","conurrencia","sistemas distribuidos","mutaciones","eliminaciones suaves","crypto.randomUUID()"],"fr":["CRDT","modèle de données","réplication","concurrence","systèmes distribués","mutations","suppressions douces","crypto.randomUUID()"],"de":["CRDT","Datenmodell","Replikation","Konkurrenz","verteilte Systeme","Mutationen","weiche Löschungen","crypto.randomUUID()"],"pt":["CRDT","Mutações de estilo draft","Desenvolvimento de software","Melhoria de código","Programação","Diretrizes de codificação"],"ru":["CRDT","Мутации стиля черновика","Разработка программного обеспечения","Улучшение кода","Программирование","Руководства по кодированию"],"ar":["CRDT","تعديلات نمط المسودة","تطوير البرمجيات","تحسين الكود","البرمجة","دليل الترميز"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.579Z","topics":[],"category":"community","skillMd":{"name":"crdt","description":"Loro CRDT state management with loro-mirror. Use when working on files in src/lib/crdt/.","bodyPreview":"# CRDT Guidelines\n\n## Critical: Draft-Style Mutations Only\n\n```typescript\n// CORRECT - mutate in place\nsetState((state) => {\n  state.transactions[id] = transaction;\n});\n\n// WRONG - returning new objects breaks change tracking\nsetState((state) => ({\n  ...state,\n  transactions: { ...state.transactions, [id]: transaction },\n}));\n```\n\n## Rules\n\n- Import types from `schema.ts`, don''t redeclare\n- **Soft deletes**: Set `deletedAt` timestamp, never remove from document\n- Use `crypto.randomUUID()` for ID","body":"# CRDT Guidelines\n\n## Critical: Draft-Style Mutations Only\n\n```typescript\n// CORRECT - mutate in place\nsetState((state) => {\n  state.transactions[id] = transaction;\n});\n\n// WRONG - returning new objects breaks change tracking\nsetState((state) => ({\n  ...state,\n  transactions: { ...state.transactions, [id]: transaction },\n}));\n```\n\n## Rules\n\n- Import types from `schema.ts`, don''t redeclare\n- **Soft deletes**: Set `deletedAt` timestamp, never remove from document\n- Use `crypto.randomUUID()` for IDs, `Date.now()` for timestamps\n\n## Schema Pattern\n\n```typescript\nexport const entitySchema = schema.LoroMap({\n  id: schema.String({ required: true }),\n  // ... fields\n  deletedAt: schema.Number(), // 0 = not deleted, >0 = timestamp\n});\n```\n\n## React Hooks\n\n- `useActiveTransactions()` - excludes soft-deleted\n- `useTransactions()` - includes soft-deleted  \n- `useVaultAction()` - for mutations\n\n## Sync\n\n- Updates encrypted before leaving client\n- Loro handles versioning via version vectors\n- Conflicts: last-write-wins per field\n"},"lastSynced":"2026-02-20T04:59:55.707Z","agentAnalysis":{"suitability":{"en":"Perfect for State Management Agents needing conflict-free distributed data types with draft-style mutations.","zh":"非常适合需要无冲突分布式数据类型且具有草稿样式变异的状态管理代理。","ja":"コンフリクトのない分散データタイプと草稿スタイルのミューテーションを必要とするステート管理エージェントに最適です。","ko":"衝突이 없는 분산 데이터 유형 및 초안 스타일 변형이 필요한 상태 관리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Gestión de Estado que necesitan tipos de datos distribuidos sin conflictos con mutaciones de estilo de borrador.","fr":"Parfait pour les Agents de Gestion d''État nécessitant des types de données distribués sans conflit avec des mutations de style de brouillon.","de":"Perfekt für State-Management-Agents, die konfliktfreie verteilte Datentypen mit Entwurfsmutationen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Estado que necessitam de tipos de dados distribuídos sem conflitos com mutações de estilo de rascunho.","ru":"Идеально подходит для агентов управления состоянием, которым необходимы конфликтно-безопасные распределенные типы данных с мутациями чернового стиля.","ar":"مثالي لعمليات إدارة الحالة التي تحتاج إلى أنواع بيانات موزعة خالية من الصراعات مع طريقة التلاعب بالمسودات."},"recommendation":{"en":"Empowers agents to manage state with CRDT guidelines, utilizing draft-style mutations and crypto.randomUUID() for ID generation, while enforcing soft deletes and importing types from schema.ts.","zh":"赋予代理管理状态的能力，遵循CRDT指南，利用草稿样式变异和crypto.randomUUID()生成ID，同时强制执行软删除并从schema.ts导入类型。","ja":"CRDTガイドラインに従ってステートを管理し、ドラフトスタイルのミューテーションを利用し、crypto.randomUUID()を使用してIDを生成し、ソフト削除を実施し、schema.tsから型をインポートするエージェントの能力を付与します。","ko":"CRDT 지침을 따라 상태를 관리하고 초안 스타일 변형을 사용하고 crypto.randomUUID()를 사용하여 ID를 생성하고 소프트 삭제를 적용하고 schema.ts에서 유형을 가져오는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a gestionar el estado con las pautas CRDT, utilizando mutaciones de estilo de borrador y crypto.randomUUID() para la generación de ID, mientras se aplican borrados suaves e importa tipos de schema.ts.","fr":"Permet aux agents de gérer l''état avec les lignes directrices CRDT, en utilisant des mutations de style de brouillon et crypto.randomUUID() pour la génération d''ID, tout en appliquant des suppressions souples et en important des types de schema.ts.","de":"Ermächtigt Agenten, den Zustand mit CRDT-Richtlinien zu verwalten, indem Entwurfsmutationen und crypto.randomUUID() für die ID-Generierung verwendet werden, während Soft Deletes durchgesetzt und Typen aus schema.ts importiert werden.","pt":"Habilita os agentes a gerenciar o estado com diretrizes CRDT, utilizando mutações de estilo de rascunho e crypto.randomUUID() para geração de ID, além de impor exclusões suaves e importar tipos do schema.ts.","ru":"Наделяет агентов возможностью управлять состоянием с помощью руководств CRDT, используя мутации чернового стиля и crypto.randomUUID() для генерации идентификаторов, а также обеспечивая мягкое удаление и импорт типов из schema.ts.","ar":"تمكّن الوكلاء من إدارة الحالة بفضل إرشادات CRDT، واستخدام طريقة التلاعب بالمسودات وcrypto.randomUUID() لإنشاء المعرفات، بالإضافة إلى فرض الحذف الناعم واستيراد الأنواع من schema.ts."},"useCases":{"en":["Implementing conflict-free distributed counters","Managing state with draft-style mutations","Enforcing soft deletes for data recovery"],"zh":["实现冲突免费的分布式计数器","使用草稿样式变异管理状态","强制执行软删除以进行数据恢复"],"ja":["コンフリクトのない分散カウンタの実装","ドラフトスタイルのミューテーションを使用したステート管理","ソフト削除の実施によるデータ復旧"],"ko":["衝突이 없는 분산 카운터 구현","초안 스타일 변형을 사용한 상태 관리","소프트 삭제의 적용을 통한 데이터 복구"],"es":["Implementar contadores distribuidos sin conflictos","Gestionar el estado con mutaciones de estilo de borrador","Aplicar borrados suaves para la recuperación de datos"],"fr":["Mettre en œuvre des compteurs distribués sans conflit","Gérer l''état avec des mutations de style de brouillon","Appliquer des suppressions souples pour la récupération de données"],"de":["Implementierung von konfliktfreien verteilten Zählern","Verwalten des Zustands mit Entwurfsmutationen","Durchsetzen von Soft Deletes für die Datenwiederherstellung"],"pt":["Implementação de contadores distribuídos sem conflitos","Gerenciamento de estado com mutações de estilo de rascunho","Imposição de exclusões suaves para recuperação de dados"],"ru":["Реализация конфликтно-безопасных распределенных счетчиков","Управление состоянием с мутациями чернового стиля","Обеспечение мягкого удаления для восстановления данных"],"ar":["تنفيذ معدودات موزعة خالية من الصراعات","إدارة الحالة بطريقة التلاعب بالمسودات","فرض الحذف الناعم لاستعادة البيانات"]},"limitations":{"en":["Requires adherence to draft-style mutation guidelines","Soft deletes must be implemented using deletedAt timestamp"],"zh":["需要遵循草稿样式变异指南","软删除必须使用deletedAt时间戳来实现"],"ja":["ドラフトスタイルのミューテーションガイドラインに従う必要がある","ソフト削除はdeletedAtタイムスタンプを使用して実装する必要がある"],"ko":["초안 스타일 변형 지침을 따라야 함","소프트 삭제는 deletedAt 타임스탬프를 사용하여 구현해야 함"],"es":["Requiere la adhesión a las pautas de mutación de estilo de borrador","Los borrados suaves deben implementarse utilizando la marca de tiempo deletedAt"],"fr":["Nécessite l''adhésion aux lignes directrices de mutation de style de brouillon","Les suppressions souples doivent être mises en œuvre en utilisant la balise de temps deletedAt"],"de":["Erfordert die Einhaltung der Entwurfsmutation-Richtlinien","Soft Deletes müssen mithilfe der deletedAt-Zeitstempel implementiert werden"],"pt":["Exige adesão às diretrizes de mutação de estilo de rascunho","Exclusões suaves devem ser implementadas usando carimbo de data e hora deletedAt"],"ru":["Требует соблюдения руководств по мутациям чернового стиля","Мягкое удаление должно быть реализовано с использованием метки времени deletedAt"],"ar":["يتطلب اتباع إرشادات طريقة التلاعب بالمسودات","يجب تنفيذ الحذف الناعم باستخدام توقيع زمني deletedAt"]},"version":3},"contentHash":"0385d5d0542e052a2a6ce4acf1aa63bb44003528261024c6e2daa785db3f5aae","qualityScore":45}');
