INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/crdt', 'crdt', 'majiayu000', 'claude-skill-registry', 'community', 'crdt majiayu000 claude-skill-registry community CRDT是一种强大的分布式数据管理技术，提供高效的数据同步和冲突解决 CRDTは、高性能なデータ同期と衝突解決を提供する強力な分散データ管理技術 CRDT는 효율적인 데이터 동기화와 충돌 해결을 제공하는 강력한 분산 데이터 관리 기술 Las guías CRDT ofrecen directrices para la implementación efectiva de este modelo de datos. Aprende a mutar en lugar de reemplazar objetos Les guides CRDT proposent des directives pour la mise en œuvre efficace de ce modèle de données. Apprenez à muter au lieu de remplacer des objets Die CRDT-Richtlinien bieten Richtlinien für die effektive Implementierung dieses Datenmodells. Erfahren Sie, wie Sie Objekte mutieren anstelle von ersetzen O CRDT é um conjunto de diretrizes para mutações de estilo draft. Aprenda a usá-lo para melhorar seu código. CRDT - это набор руководств для мутаций стиля черновика. Узнайте, как его использовать, чтобы улучшить свой код. CRDT هو مجموعة من الإرشادات لتعديلات نمط المسودة. تعلم كيفية استخدامه لتحسين кодك. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app CRDT 分布式数据管理 数据同步 冲突解决 _draft-style_ crypto.randomUUID() 软删除 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('enriquemoya/Electron-Pos/koyote-spec-create', 'community', 'enriquemoya', 'Electron-Pos', 'enriquemoya/Electron-Pos', 'koyote-spec-create', 0, 0, 45, '2026-02-26T13:18:49.077Z', '2026-02-26T14:29:31.922Z', 'b0982192a87ad3240e3e26ee3a682efe178fcb31d8b9b761964fdaf41b5fbc4e', '{"id":"enriquemoya/Electron-Pos/koyote-spec-create","name":"koyote-spec-create","description":{"zh":"koyote-spec-create是一种使用electron的TCG Store POS解决方案，提供高效的交易处理能力","ja":"koyote-spec-createはエレクトロンを使用したTCGストアPOSソリューションであり、高効率の取引処理能力を提供する","ko":"koyote-spec-create는 전자상거래를 위한 electron 기반의 TCG 스토어 POS 솔루션으로, 효율적인 거래 처리 능력을 제공합니다","es":"koyote-spec-create es una herramienta de AI que mejora la experiencia de TCG Store POS con Electron. Permite una integración fluida y personalizable","fr":"koyote-spec-create est un outil d''IA qui améliore l''expérience de TCG Store POS avec Electron. Il permet une intégration fluide et personnalisable","de":"koyote-spec-create ist ein KI-Tool, das die TCG Store POS-Erfahrung mit Electron verbessert. Es ermöglicht eine flüssige und anpassbare Integration","pt":"O koyote-spec-create é uma ferramenta de AI para criar um TCG Store POS com Electron, permitindo desenvolver sistemas de ponto de venda personalizados.","ru":"ИИ Агент koyote-spec-create для создания TCG Store POS с Electron, позволяет разработать индивидуальные системы продаж","ar":"أداة الذكاء الاصطناعي koyote-spec-create لإنشاء نظام نقاط بيع لمتاجر البطاقات مع Electron، تمكنك من تطوير أنظمة بيع مخصصة","en":"TCG Store POS with electron"},"seo":{"title":{"zh":"AI智能工具koyote-spec-create：电子商务POS解决方案","ja":"AIエージェントkoyote-spec-create：エレクトロントレーディングストアPOS","ko":"AI 에이전트 koyote-spec-create: 전자상거래 POS 솔루션","es":"Herramientas de AI: koyote-spec-create para TCG Store POS...","fr":"Outils d''IA : koyote-spec-create pour TCG Store POS avec ...","de":"KI-Tools: koyote-spec-create für TCG Store POS mit Electron","pt":"Crie um TCG Store POS com koyote-spec-create e Electron","ru":"ИИ Агенты: создайте TCG Store POS с koyote-spec-create и ...","ar":"أداة الذكاء الاصطناعي: انشئ متجر TCG POS باستخدام koyote-...","en":"koyote-spec-create"},"description":{"zh":"koyote-spec-create是一种使用electron的TCG Store POS解决方案，提供高效的交易处理能力","ja":"koyote-spec-createはエレクトロンを使用したTCGストアPOSソリューションであり、高効率の取引処理能力を提供する","ko":"koyote-spec-create는 전자상거래를 위한 electron 기반의 TCG 스토어 POS 솔루션으로, 효율적인 거래 처리 능력을 제공합니다","es":"koyote-spec-create es una herramienta de AI que mejora la experiencia de TCG Store POS con Electron. Permite una integración fluida y personalizable","fr":"koyote-spec-create est un outil d''IA qui améliore l''expérience de TCG Store POS avec Electron. Il permet une intégration fluide et personnalisable","de":"koyote-spec-create ist ein KI-Tool, das die TCG Store POS-Erfahrung mit Electron verbessert. Es ermöglicht eine flüssige und anpassbare Integration","pt":"O koyote-spec-create é uma ferramenta de AI para criar um TCG Store POS com Electron, permitindo desenvolver sistemas de ponto de venda personalizados.","ru":"ИИ Агент koyote-spec-create для создания TCG Store POS с Electron, позволяет разработать индивидуальные системы продаж","ar":"أداة الذكاء الاصطناعي koyote-spec-create لإنشاء نظام نقاط بيع لمتاجر البطاقات مع Electron، تمكنك من تطوير أنظمة بيع مخصصة","en":"TCG Store POS with electron"},"definition":{"en":"TCG Store POS with electron"},"features":{"zh":["电子商务POS解决方案","使用electron构建","高效的交易处理能力","支持多种支付方式","易于集成和扩展"],"ja":["エレクトロントレーディングストアPOSソリューション","エレクトロンを使用して構築","高効率の取引処理能力","複数の支払い方法をサポート","簡単に統合および拡張可能"],"ko":["전자상거래 POS 솔루션","electron을 사용하여 구축","효율적인 거래 처리 능력","여러 가지 결제 방법을 지원","쉽게 통합 및 확장 가능"],"es":["Integración con Electron para TCG Store POS","Personalización fluida de la experiencia del usuario","Mejora de la eficiencia en la gestión de la tienda","Compatibilidad con múltiples plataformas","Fácil instalación y configuración"],"fr":["Intégration avec Electron pour TCG Store POS","Personnalisation fluide de l''expérience utilisateur","Amélioration de l''efficacité dans la gestion de la boutique","Compatibilité avec plusieurs plateformes","Installation et configuration faciles"],"de":["Integration mit Electron für TCG Store POS","Flüssige Anpassung der Benutzeroberfläche","Verbesserung der Effizienz bei der Ladenverwaltung","Kompatibilität mit mehreren Plattformen","Einfache Installation und Konfiguration"],"pt":["Criação de sistema de ponto de venda personalizado","Integração com Electron","Desenvolvimento de loja de cartas","Ferramenta de AI para automação de tarefas","Suporte a múltiplos pagamentos"],"ru":["Создание индивидуальной системы продаж","Интеграция с Electron","Разработка магазина карт","ИИ Агент для автоматизации задач","Поддержка нескольких платежных систем"],"ar":["إنشاء نظام بيع مخصص","التكامل مع Electron","تطوير متجر البطاقات","أداة الذكاء الاصطناعي للautomação من المهام","دعم أنظمة الدفع المتعددة"]},"keywords":{"zh":["如何使用koyote-spec-create","什么是electron","koyote-spec-create替代品","koyote-spec-create与其他POS系统的比较","koyote-spec-create安装指南","koyote-spec-create设置教程"],"ja":["koyote-spec-createの使用方法","エレクトロンの概要","koyote-spec-createの代替品","koyote-spec-createと他のPOSシステムの比較","koyote-spec-createのインストールガイド","koyote-spec-createの設定チュートリアル"],"ko":["koyote-spec-create 사용법","electron에 대한 정보","koyote-spec-create 대체품","koyote-spec-create와 다른 POS 시스템의 비교","koyote-spec-create 설치 가이드","koyote-spec-create 설정 튜토리얼"],"es":["herramientas de AI para desarrolladores","cómo usar koyote-spec-create","TCG Store POS con Electron","alternativas a koyote-spec-create","koyote-spec-create vs otros herramientas de AI","instalación de koyote-spec-create","guía de configuración de koyote-spec-create"],"fr":["outils d''IA pour développeurs","comment utiliser koyote-spec-create","TCG Store POS avec Electron","alternatives à koyote-spec-create","koyote-spec-create vs autres outils d''IA","installation de koyote-spec-create","guide de configuration de koyote-spec-create"],"de":["KI-Tools für Entwickler","wie man koyote-spec-create verwendet","TCG Store POS mit Electron","Alternativen zu koyote-spec-create","koyote-spec-create vs andere KI-Tools","Installation von koyote-spec-create","Konfigurationsanleitung für koyote-spec-create"],"pt":["koyote-spec-create","TCG Store POS","Electron","ferramenta de AI","sistema de ponto de venda","loja de cartas","desenvolvimento de software","como usar koyote-spec-create","koyote-spec-create vs outros"],"ru":["ИИ Агенты","koyote-spec-create","TCG Store POS","Electron","инструмент для создания системы продаж","магазин карт","разработка программного обеспечения","как использовать koyote-spec-create","koyote-spec-create альтернатива"],"ar":["أداة الذكاء الاصطناعي","koyote-spec-create","نظام نقاط بيع لمتاجر البطاقات","Electron","أداة لإنشاء نظام بيع","متجر البطاقات","تطوير البرمجيات","كيفية استخدام koyote-spec-create","بديل koyote-spec-create"]}},"owner":"enriquemoya","repo":"Electron-Pos","repoPath":"enriquemoya/Electron-Pos","stars":0,"forks":0,"updatedAt":"2026-02-26T13:18:49.077Z","topics":[],"category":"community","skillMd":{"name":"koyote-spec-create","description":"Create or update a specification using spec-driven governance. Discovers relevant domain agents dynamically and produces implementation-ready spec files only.","bodyPreview":"# koyote-spec-create\n\nUse this skill to **create or update specs only**.\nThis skill NEVER writes runtime code.\n\nSpecs produced by this skill are the **only allowed input** for implementation skills.\n\n## Repo root resolution\n\nAlways operate in the repo root that contains .agent and .specs.\nIf the current working directory is not the repo root, change to it\nbefore creating or updating any spec files.\nIf multiple candidates exist, prefer the one that also contains apps/\nand package.json (expected:","body":"# koyote-spec-create\n\nUse this skill to **create or update specs only**.\nThis skill NEVER writes runtime code.\n\nSpecs produced by this skill are the **only allowed input** for implementation skills.\n\n## Repo root resolution\n\nAlways operate in the repo root that contains .agent and .specs.\nIf the current working directory is not the repo root, change to it\nbefore creating or updating any spec files.\nIf multiple candidates exist, prefer the one that also contains apps/\nand package.json (expected: pos-koyote).\nNever create a new .specs folder. Always use the existing .specs\nfolder inside the resolved repo root. If a second .specs is found\noutside the repo root, ignore it and stop to confirm before writing.\n\n---\n\n## Governing References (MUST READ)\n\n- .agent/ARCHITECTURE.md\n- .agent/rules/GLOBAL.md\n- .agent/rules/SPEC_STANDARD.md\n- .agent/rules/DATA_ACCESS.md\n- .agent/rules/MEMORY_BANK.md\n- .agent/workflows/spec-create.md\n- .agent/rules/AGENT_DISCOVERY.md\n\n---\n\n## Agent Discovery Protocol (CRITICAL)\n\nBefore drafting or modifying a spec, the skill MUST:\n\n1. Identify the spec domain(s):\n   - frontend (online-store)\n   - backend (cloud-api)\n   - data (Prisma, schema, migrations)\n   - UX / i18n / accessibility\n   - POS / IPC (only if explicitly allowed)\n\n2. Discover relevant agents by scanning `.agent/agents/` conceptually and matching:\n   - Domain\n   - Capabilities\n\n3. Consult discovered agents for:\n   - Constraints\n   - Risks\n   - Required sections\n   - Non-goals\n\nAgents provide **advice only**.  \nThis skill decides what is written into the spec.\n\nAbsence of agents must NOT block spec creation.\n\n---\n\n## Required Questions (ask before any edits)\n\n1) Target spec slug (folder name)?\n2) What problem or feature is being specified?\n3) Scope boundaries or explicitly excluded areas?\n4) Apps involved? (online-store, cloud-api, POS, multiple?)\n5) Any routing, i18n, or UX constraints?\n6) Proceed with spec creation after plan? (yes/no)\n\nDo NOT create or modify files until all answers are given.\n\n---\n\n## Spec Creation Rules\n\n- ASCII only\n- English only\n- No implementation details beyond contracts and behavior\n- No assumptions about future features unless explicitly marked\n- All non-goals must be explicit\n- Specs must stand alone without chat context\n\n---\n\n## Files to Produce or Update\n\nCreate or update exactly these files:\n\n.specs/<slug>/requirements.md  \n.specs/<slug>/design.md  \n.specs/<slug>/tasks.md  \n\nEach file must follow SPEC_STANDARD.md structure.\n\n---\n\n## Required Content per File\n\n### requirements.md\n- Problem statement\n- Goals\n- Non-goals\n- Constraints\n- Assumptions\n- Out of scope\n\n### design.md\n- High-level architecture\n- Data flow\n- State ownership\n- Error and edge cases\n- i18n and accessibility notes (if applicable)\n\n### tasks.md\n- Small, implementable tasks\n- Ordered and scoped\n- Each task maps back to requirements\n- No task larger than one implementation session\n\n---\n\n## Forbidden Actions\n\n- Writing or modifying runtime code\n- Creating migrations\n- Adding dependencies\n- Updating memory bank directly\n- Making architectural decisions outside scope\n\n---\n\n## Output Format (MANDATORY)\n\n- Summary of intent\n- Agents consulted (by domain, not filenames)\n- Files created or modified (full paths)\n- Open questions or risks\n- Next command:\n  npm run gov:spec:audit -- \"<slug>\"\n\n---\n\n## When NOT to Use This Skill\n\n- To fix bugs\n- To write code\n- To refactor existing implementations without changing behavior\n- To brainstorm without intent to implement\n\nUse this skill when the spec **must be correct before code exists**.\n"},"lastSynced":"2026-02-26T14:29:31.922Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing precise spec creation and updates for TCG Store POS with Electron","zh":"非常适合需要为TCG Store POS以Electron创建和更新精确规格的开发代理","ja":"Electronを使用したTCG Store POSの正確な仕様の作成と更新が必要な開発エージェントに最適","ko":"Electron을 사용하여 TCG Store POS에 대한 정확한 사양을 생성하고 업데이트하는 데 필요한 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo que necesitan crear y actualizar especificaciones precisas para TCG Store POS con Electron","fr":"Parfait pour les agents de développement nécessitant la création et la mise à jour de spécifications précises pour TCG Store POS avec Electron","de":"Perfekt für Entwicklungsmittel benötigende präzise Spezifikationserstellung und -aktualisierung für TCG Store POS mit Electron","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de criação e atualização precisa de especificações para TCG Store POS com Electron","ru":"Идеально для агентов разработки, которым требуется точное создание и обновление спецификаций для TCG Store POS с Electron","ar":"مثالي لعميل التطوير الذين بحاجة إلى إنشاء دقيق وتحديث للمواصفات لمنصة TCG Store POS مع Electron"},"recommendation":{"en":"Empowers agents to create or update specs only, producing specs that are the sole allowed input for implementation skills, utilizing repo root resolution and operating within directories containing .agent and .specs files, and preferring those with apps/ and package.json","zh":"赋予代理创建或更新规格的能力，仅生成规格，这些规格是实现技能的唯一允许输入，利用仓库根目录解析并在包含.agent和.specs文件的目录中操作，并且更喜欢包含apps/和package.json的目录","ja":"エージェントに仕様を作成または更新する能力を与え、実装スキルの唯一の許可された入力となる仕様のみを生成し、リポジトリルート解決と.agentおよび.specsファイルを含むディレクトリ内での操作を利用し、apps/およびpackage.jsonを含むディレクトリを優先する","ko":"에이전트가 사양을 생성하거나 업데이트하는 능력을 부여하며, 구현 스킬의 유일한 허용된 입력인 사양만 생성하며, 저장소 루트 해석 및 .agent 및 .specs 파일을 포함하는 디렉토리 내에서 작동하며, apps/ 및 package.json을 포함하는 디렉토리를 선호","es":"Habilita a los agentes a crear o actualizar especificaciones, produciendo especificaciones que son la única entrada permitida para las habilidades de implementación, utilizando la resolución de la raíz del repositorio y operando dentro de directorios que contienen archivos .agent y .specs, y prefiere aquellos con apps/ y package.json","fr":"Habilite les agents à créer ou à mettre à jour des spécifications, produisant des spécifications qui sont la seule entrée autorisée pour les compétences d''implémentation, en utilisant la résolution de la racine du référentiel et en opérant dans des répertoires contenant des fichiers .agent et .specs, et en préférant ceux avec apps/ et package.json","de":"Ermächtigt Agenten, Spezifikationen zu erstellen oder zu aktualisieren, die Spezifikationen produzieren, die die einzige zugelassene Eingabe für Implementierungsfähigkeiten sind, unter Verwendung der Auflösung der Repository-Wurzel und innerhalb von Verzeichnissen, die .agent- und .specs-Dateien enthalten, und bevorzugt solche mit apps/ und package.json","pt":"Habilita os agentes a criar ou atualizar especificações apenas, produzindo especificações que são a única entrada permitida para habilidades de implementação, utilizando resolução de repositório raiz e operando dentro de diretórios que contenham arquivos .agent e .specs, e preferindo aqueles com apps/ e package.json","ru":"Наделяет агентов возможностью создавать или обновлять спецификации только, производя спецификации, которые являются единственным разрешенным входом для навыков реализации, используя разрешение корня репозитория и работа внутри каталогов, содержащих файлы .agent и .specs, и предпочитая те, у которых есть apps/ и package.json","ar":"يمكّن الوكيل من إنشاء أو تحديث المواصفات فقط ، وإنتاج مواصفات هي المدخلات المسموحة الوحيدة لمهارات التنفيذ ، باستخدام حل الجذر للمستودع وتشغيله داخل المجلدات التي تحتوي على ملفات .agent و .specs ، والأفضل هي تلك التي تحتوي على apps/ و package.json"},"useCases":{"en":["Creating specs for new TCG Store POS features","Updating existing specs to reflect changes in Electron or POS functionality","Validating spec files against the required .agent and .specs directory structure"],"zh":["为TCG Store POS的新功能创建规格","更新现有的规格以反映Electron或POS功能的更改","验证规格文件是否符合所需的.agent和.specs目录结构"],"ja":["TCG Store POSの新機能の仕様を作成する","既存の仕様を更新してElectronまたはPOSの機能の変更を反映する","仕様ファイルを必要な.agentおよび.specsディレクトリ構造に対して検証する"],"ko":["TCG Store POS의 새로운 기능에 대한 사양을 생성","既存의 사양을 업데이트하여 Electron 또는 POS 기능의 변경을 반영","사양 파일을 필요한 .agent 및 .specs 디렉토리 구조에 대해 검증"],"es":["Crear especificaciones para nuevas características de TCG Store POS","Actualizar especificaciones existentes para reflejar cambios en Electron o la funcionalidad de POS","Validar archivos de especificaciones contra la estructura de directorio requerida .agent y .specs"],"fr":["Créer des spécifications pour les nouvelles fonctionnalités de TCG Store POS","Mettre à jour des spécifications existantes pour refléter les changements dans Electron ou la fonctionnalité de POS","Valider les fichiers de spécification contre la structure de répertoire requise .agent et .specs"],"de":["Spezifikationen für neue TCG Store POS-Funktionen erstellen","Vorhandene Spezifikationen aktualisieren, um Änderungen in Electron oder der POS-Funktionalität widerzuspiegeln","Spezifikationsdateien gegen die erforderliche Verzeichnisstruktur .agent und .specs überprüfen"],"pt":["Criar especificações para recursos novos da TCG Store POS","Atualizar especificações existentes para refletir mudanças na funcionalidade do Electron ou POS","Validar arquivos de especificações contra a estrutura de diretório necessária .agent e .specs"],"ru":["Создавать спецификации для новых функций TCG Store POS","Обновлять существующие спецификации, чтобы отразить изменения в функциональности Electron или POS","Проверять файлы спецификаций против необходимой структуры каталога .agent и .specs"],"ar":["إنشاء مواصفات لملامح جديدة من منصة TCG Store POS","تحديث المواصفات الحالية لتعكس التغييرات في وظيفة Electron أو POS","التحقق من صحة ملفات المواصفات مقابل هيكل الدليل المطلوب .agent و .specs"]},"limitations":{"en":["Never writes runtime code","Requires operating within the repo root containing .agent and .specs","Limited to creating or updating spec files, not implementation code"],"zh":["从不编写运行时代码","需要在包含.agent和.specs的仓库根目录中操作","仅限创建或更新规格文件，而不是实现代码"],"ja":["実行時コードを書き込まない",".agentおよび.specsを含むリポジトリルート内で操作する必要がある","仕様ファイルの作成または更新のみ、実装コードではない"],"ko":["런타임 코드를 절대 작성하지 않음",".agent 및 .specs를 포함하는 저장소 루트에서 작동해야 함","사양 파일의 생성 또는 업데이트만 가능하며, 구현 코드는 아님"],"es":["Nunca escribe código de ejecución","Requiere operar dentro de la raíz del repositorio que contiene .agent y .specs","Limitado a la creación o actualización de archivos de especificaciones, no código de implementación"],"fr":["Ne écrit jamais de code d''exécution","Exige d''opérer dans la racine du référentiel contenant .agent et .specs","Limité à la création ou à la mise à jour de fichiers de spécification, et non de code d''implémentation"],"de":["Schreibt niemals Laufzeitcode","Erfordert die Ausführung innerhalb der Repository-Wurzel, die .agent und .specs enthält","Begrenzt auf die Erstellung oder Aktualisierung von Spezifikationsdateien, nicht auf Implementierungscode"],"pt":["Nunca escreve código de tempo de execução","Exige operação dentro do repositório raiz que contém .agent e .specs","Limitado a criar ou atualizar arquivos de especificações, não código de implementação"],"ru":["Никогда не пишет код времени выполнения","Требует работы внутри корня репозитория, содержащего .agent и .specs","Ограничен созданием или обновлением файлов спецификаций, не кода реализации"],"ar":["أبدا لا يكتب رمز وقت التشغيل","يتطلب التشغيل داخل الجذر للمستودع الذي يحتوي على .agent و .specs","محدود بإنشاء أو تحديث ملفات المواصفات ، وليس رمز التنفيذ"]},"version":3},"contentHash":"b0982192a87ad3240e3e26ee3a682efe178fcb31d8b9b761964fdaf41b5fbc4e","qualityScore":45}');
