INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NeverSight/skills_feed/github-automation', 'github-automation', 'NeverSight', 'skills_feed', 'community', 'github-automation NeverSight skills_feed community GitHub 自动化 AI 工具帮助您自动化 GitHub 操作，提高开发效率 GitHub 自動化 AI エージェントは、GitHub 操作を自動化し、開発効率を向上させる GitHub 자동화 AI 에이전트는 GitHub 작업을 자동화하여 개발 효율성을 높입니다 El agente de automatización de GitHub simplifica la gestión de repositorios y operaciones de desarrollo L''outil d''automatisation GitHub simplifie la gestion des référentiels et des opérations de développement Das GitHub-Automatisierungstool vereinfacht die Verwaltung von Repositorys und Entwicklungsoperationen O agente de automação do GitHub é uma ferramenta de IA que ajuda a automatizar operações no GitHub, como criar PRs e gerenciar repositórios. ИИ Агент для GitHub - это инструмент, который помогает автоматизировать операции на GitHub, такие как создание PR и управление репозиториями. وكيل الإدارة الآلية على GitHub هو أداة ذكاء اصطناعي تساعد في أتمتة العمليات على GitHub، مثل إنشاء طلبات السحب و إدارة المستودعات. 自动化 GitHub 操作。当用户需要管理仓库、创建 PR、处理 Issue、自动化 CI/CD 或进行代码审查时使用此技能。 GitHub 自动化工具 AI 工具 仓库管理 PR 创建 Issue 处理 CI/CD 自动化 代码审查 GitHub API 自动化脚本 自动化 GitHub 操作。当用户需要管理仓库、创建 PR、处理 Issue、自动化 CI/CD 或进行代码审查时使用此技能。');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tung68nt/tulie_lab/knowns.task.brainstorm', 'community', 'tung68nt', 'tulie_lab', 'tung68nt/tulie_lab', 'knowns.task.brainstorm', 0, 0, 45, '2026-03-06T12:59:22.202Z', '2026-03-06T13:32:50.653Z', '35ba22358662fbcbbe0c6720d3bc8313872f21c112dfb8d0be79ec1385e4541a', '{"id":"tung68nt/tulie_lab/knowns.task.brainstorm","name":"knowns.task.brainstorm","description":{"en":"The knowns.task.brainstorm skill helps developers and AI agents convert vague task requirements into concrete designs through structured questioning and exploration, utilizing technologies like Next.js, Express, and Prisma.","zh":"knowns.task.brainstorm 技术是将模糊需求转化为具体设计的解决方案，基于 Next.js 和 Express 构建 LMS 平台","ja":"knowns.task.brainstorm は、タスク設計を効率化する AI エージェント技術です。Next.js と Express を使用した LMS プラットフォームの構築を支援します","ko":"knowns.task.brainstorm 기술은 태스크 디자인을 구체화하는 솔루션으로 Next.js 및 Express 기반의 LMS 플랫폼을 구축합니다","es":"knowns.task.brainstorm es una habilidad para convertir requisitos vagos en diseños concretos a través de preguntas estructuradas y exploración","fr":"knowns.task.brainstorm est une compétence pour convertir des exigences vagues en conceptions concrètes via des questions structurées et une exploration","de":"knowns.task.brainstorm ist eine Fähigkeit, um vage Anforderungen in konkrete Designs durch strukturierte Fragen und Exploration umzusetzen","pt":"O knowns.task.brainstorm é uma habilidade para desenvolvedores que converte requisitos vagos em design concreto com Next.js, Express e Prisma.","ru":"knowns.task.brainstorm - это навык для разработчиков, который преобразует нечеткие требования в конкретный дизайн с помощью Next.js, Express и Prisma для ИИ Агентов","ar":"knowns.task.brainstorm هو مهارة لل مبرمجين لتحويل المتطلبات الغامضة إلى تصميم ملموس باستخدام Next.js و Express و Prisma"},"seo":{"title":{"en":"knowns.task.brainstorm: Structured Task Brainstorming for...","zh":"knowns.task.brainstorm 设置指南 - 基于 Next.js 和 Express 的任务脑暴","ja":"knowns.task.brainstorm 導入ガイド - AIエージェントによるタスク設計","ko":"knowns.task.brainstorm 설정 가이드 - Next.js 및 Express 기반 태스크 ...","es":"Guía de configuración de knowns.task.brainstorm para desa...","fr":"Guide de démarrage de knowns.task.brainstorm pour les dév...","de":"Einrichtungsleitfaden für knowns.task.brainstorm-Entwickler","pt":"knowns.task.brainstorm: Guia de Configuração para Desenvo...","ru":"knowns.task.brainstorm: Настройка для Разработчиков ИИ Аг...","ar":"knowns.task.brainstorm: دليل الإعداد لل مبرمجين"},"description":{"en":"Unlock efficient task design with knowns.task.brainstorm. Explore approaches and convert vague requirements into concrete designs. Get started with our skill...","zh":"了解 knowns.task.brainstorm 技术，如何将模糊需求转化为具体设计，利用 Next.js 和 Express 构建 LMS 平台","ja":"knowns.task.brainstorm を使用して、タスク設計を効率化する方法を学びます。AIエージェントと Next.js、Express を組み合わせた LMS プラットフォームの構築","ko":"knowns.task.brainstorm 기술을 사용하여 태스크 디자인을 구체화하고 Next.js 및 Express 기반의 LMS 플랫폼을 구축하는 방법을 알아보세요","es":"Aprende a utilizar knowns.task.brainstorm para convertir requisitos vagos en diseños concretos con Next.js, Express y Prisma","fr":"Découvrez comment utiliser knowns.task.brainstorm pour convertir des exigences vagues en conceptions concrètes avec Next.js, Express et Prisma","de":"Erfahren Sie, wie Sie knowns.task.brainstorm verwenden, um vage Anforderungen in konkrete Designs mit Next.js, Express und Prisma umzusetzen","pt":"Aprenda a usar o knowns.task.brainstorm para converter requisitos vagos em design concreto com Next.js, Express e Prisma","ru":"Узнайте, как использовать knowns.task.brainstorm для преобразования нечетких требований в конкретный дизайн с помощью Next.js, Express и Prisma для ИИ Агентов","ar":"تعلم كيفية استخدام knowns.task.brainstorm لتحويل المتطلبات الغامضة إلى تصميم ملموس باستخدام Next.js و Express و Prisma"},"definition":{"en":"knowns.task.brainstorm is a skill that enables AI agents to facilitate task brainstorming sessions, following a core principle of understanding the problem before proposing solutions.","zh":"knowns.task.brainstorm 是一种任务脑暴技术，通过结构化问题和探索将模糊需求转化为具体设计","ja":"knowns.task.brainstorm は、タスク設計を効率化するための AI エージェント技術で、構造化された質問と探索を通じて、曖昧な要件を具体的な設計に変換します","ko":"knowns.task.brainstorm 은 태스크 디자인을 구체화하는 기술로 구조화된 질문과 탐색을 통해 모호한 요구사항을 구체적인 설계로 변환합니다","es":"knowns.task.brainstorm es una herramienta de inteligencia artificial para desarrolladores que facilita la creación de diseños concretos","fr":"knowns.task.brainstorm est un outil d''intelligence artificielle pour les développeurs qui facilite la création de conceptions concrètes","de":"knowns.task.brainstorm ist ein KI-Tool für Entwickler, das die Erstellung konkreter Designs erleichtert","pt":"knowns.task.brainstorm é uma habilidade de AI que auxilia desenvolvedores a entender problemas antes de propor soluções","ru":"knowns.task.brainstorm - это навык ИИ, который помогает разработчикам понять проблему перед предложением решений","ar":"knowns.task.brainstorm هو مهارة ذكاء اصطناعي تساعد المبرمجين على فهم المشاكل قبل اقتراح حلول"},"features":{"en":["Utilizes a phased approach, starting with Phase 1: Discovery, to understand task requirements","Employs structured questioning, using one question at a time, to avoid overwhelming users","Supports multiple-choice questioning, such as ''Which approach do you prefer? A) Quick solution with trade-offs''","Integrates with the LMS Platform - The Tulie Lab, built using Next.js, Express, and Prisma","Follows a core principle of understanding the problem before proposing solutions","Announces the use of the knowns.task.brainstorm skill at the start of the brainstorming process"],"zh":["基于 Next.js 和 Express 的 LMS 平台构建","结构化问题和探索的任务脑暴技术","将模糊需求转化为具体设计","支持多个问题的逐步探索","优先使用多选项的问答方式"],"ja":["Next.js と Express を使用した LMS プラットフォームの構築","構造化された質問と探索によるタスク設計","曖昧な要件を具体的な設計に変換","複数の質問の逐次探索をサポート","多肢選択式の問い合わせ方式を優先"],"ko":["Next.js 및 Express 기반의 LMS 플랫폼 구축","구조화된 질문과 탐색을 통한 태스크 디자인","모호한 요구사항을 구체적인 설계로 변환","複数의 질문의 순차적 탐색을 지원","다중 선택형 질문 방식을 우선"],"es":["Utiliza Next.js, Express y Prisma para crear diseños concretos","Preguntas estructuradas para clarificar requisitos","Exploración para encontrar soluciones óptimas","Soporte para múltiples opciones de respuesta","Integración con herramientas de desarrollo populares"],"fr":["Utilise Next.js, Express et Prisma pour créer des conceptions concrètes","Questions structurées pour clarifier les exigences","Exploration pour trouver des solutions optimales","Prise en charge de plusieurs options de réponse","Intégration avec des outils de développement populaires"],"de":["Verwenden von Next.js, Express und Prisma, um konkrete Designs zu erstellen","Strukturierte Fragen, um Anforderungen zu klären","Exploration, um optimale Lösungen zu finden","Unterstützung für mehrere Antwortoptionen","Integration mit beliebten Entwicklungstools"],"pt":["Utiliza Next.js para criar interfaces de usuário","Integra com Express para gerenciar requisições","Emprega Prisma para modelar dados","Realiza questionamento estruturado para entender problemas","Oferece abordagens de design concretas"],"ru":["Использует Next.js для создания интерфейсов пользователя","Интегрируется с Express для управления запросами","Использует Prisma для моделирования данных","Проводит структурированный вопрос для понимания проблем","Предлагает конкретные подходы к дизайну"],"ar":["يستخدم Next.js لإنشاء واجهات المستخدم","يتكامل مع Express لإدارة الطلبات","يستخدم Prisma لنمذجة البيانات","ي thựcن استجواب منظم لفهم المشاكل","يقدم نهج تصميم ملموس"]},"keywords":{"en":["how to use knowns.task.brainstorm","what is knowns.task.brainstorm","knowns.task.brainstorm alternative","knowns.task.brainstorm vs traditional task design","knowns.task.brainstorm install","knowns.task.brainstorm setup guide","task brainstorming with AI agents","structured task design with Next.js and Prisma","LMS Platform task management"],"zh":["knowns.task.brainstorm","Next.js","Express","LMS 平台","任务脑暴","结构化问题","探索式设计","模糊需求转化"],"ja":["knowns.task.brainstorm","Next.js","Express","LMS プラットフォーム","AIエージェント","タスク設計","構造化された質問","探索式設計","曖昧な要件解決"],"ko":["knowns.task.brainstorm","Next.js","Express","LMS 플랫폼","AI 에이전트","태스크 디자인","구조화된 질문","탐색식 설계","모호한 요구사항 해결"],"es":["knowns.task.brainstorm","herramientas de inteligencia artificial para desarrolladores","diseño de software","Next.js","Express","Prisma","desarrollo de aplicaciones","creación de diseños concretos"],"fr":["knowns.task.brainstorm","outils d''intelligence artificielle pour les développeurs","conception de logiciels","Next.js","Express","Prisma","développement d''applications","création de conceptions concrètes"],"de":["knowns.task.brainstorm","KI-Tools für Entwickler","Software-Design","Next.js","Express","Prisma","Anwendungs-Entwicklung","Erstellung konkreter Designs"],"pt":["knowns.task.brainstorm","Next.js","Express","Prisma","desenvolvimento de software","AI para desenvolvedores","ferramentas de AI","desenvolvimento de aplicativos","tecnologias de desenvolvimento"],"ru":["knowns.task.brainstorm","Next.js","Express","Prisma","разработка программного обеспечения","ИИ для разработчиков","инструменты ИИ","разработка приложений","технологии разработки"],"ar":["knowns.task.brainstorm","Next.js","Express","Prisma","تطوير البرمجيات","الذكاء الاصطناعي للمبرمجين","أدوات الذكاء الاصطناعي","تطوير التطبيقات","تكنولوجيا التطوير"]}},"owner":"tung68nt","repo":"tulie_lab","repoPath":"tung68nt/tulie_lab","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.202Z","topics":[],"category":"community","skillMd":{"name":"knowns.task.brainstorm","description":"Use when requirements are unclear, multiple approaches exist, or you need to explore solutions before planning","bodyPreview":"# Brainstorming for Tasks\n\nConvert vague requirements into concrete design through structured questioning and exploration.\n\n**Announce at start:** \"I''m using the knowns.task.brainstorm skill to explore approaches.\"\n\n**Core principle:** UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS.\n\n## The Process\n\n### Phase 1: Discovery\n\n**One question at a time.** Don''t overwhelm with multiple questions.\n\nPrefer multiple-choice when possible:\n```\nWhich approach do you prefer?\nA) Quick solution with trade-o","body":"# Brainstorming for Tasks\n\nConvert vague requirements into concrete design through structured questioning and exploration.\n\n**Announce at start:** \"I''m using the knowns.task.brainstorm skill to explore approaches.\"\n\n**Core principle:** UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS.\n\n## The Process\n\n### Phase 1: Discovery\n\n**One question at a time.** Don''t overwhelm with multiple questions.\n\nPrefer multiple-choice when possible:\n```\nWhich approach do you prefer?\nA) Quick solution with trade-offs\nB) Comprehensive solution, more effort\nC) Something else (describe)\n```\n\nQuestions to clarify:\n- What problem are we solving?\n- Who are the users/stakeholders?\n- What are the constraints?\n- What does success look like?\n\n### Phase 2: Research Existing Patterns\n\n```json\n// Search docs for related patterns\nmcp__knowns__search_docs({ \"query\": \"<topic>\" })\n\n// Check how similar things were done\nmcp__knowns__search_tasks({ \"query\": \"<keywords>\" })\n```\n\n**Learn from history** - completed tasks often contain implementation insights.\n\n### Phase 3: Explore Approaches\n\nPresent 2-3 options with trade-offs:\n\n```markdown\n## Option A: [Name]\n- **Approach**: Brief description\n- **Pros**: What''s good\n- **Cons**: What''s challenging\n- **Effort**: Low/Medium/High\n\n## Option B: [Name]\n- **Approach**: Brief description\n- **Pros**: What''s good\n- **Cons**: What''s challenging\n- **Effort**: Low/Medium/High\n```\n\n**Lead with your recommendation** and explain why.\n\n### Phase 4: Validate and Document\n\nAfter agreement:\n- Summarize the chosen approach\n- Identify potential risks\n- Define acceptance criteria\n\nIf creating a new task:\n```json\nmcp__knowns__create_task({\n  \"title\": \"<title>\",\n  \"description\": \"Based on brainstorm: <key decisions>\",\n  \"acceptanceCriteria\": [\"Criterion 1\", \"Criterion 2\"]\n})\n```\n\nIf updating existing task:\n```json\nmcp__knowns__update_task({\n  \"taskId\": \"$ARGUMENTS\",\n  \"description\": \"Updated based on brainstorm...\"\n})\n```\n\n## When to Use This Skill\n\n**Good candidates:**\n- Vague requirements (\"make it faster\", \"improve UX\")\n- Multiple valid approaches exist\n- Significant effort involved\n- New territory for the project\n\n**Skip for:**\n- Clear, well-defined tasks\n- Bug fixes with obvious solutions\n- Simple additions following existing patterns\n\n## Red Flags\n\n**You''re doing it wrong if:**\n- Proposing solutions before understanding the problem\n- Asking too many questions at once\n- Not researching existing patterns first\n- Skipping trade-off analysis\n\n## Remember\n\n- One question at a time\n- Research existing patterns first\n- Present options with trade-offs\n- Lead with your recommendation\n- Document the decision"},"lastSynced":"2026-03-06T13:32:50.653Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured task requirement analysis through technologies like Next.js, Express, and Prisma.","zh":"非常适合需要通过Next.js、Express和Prisma等技术进行结构化任务需求分析的开发代理人。","ja":"Next.js、Express、Prismaなどの技術を使用して構造化されたタスク要件分析が必要な開発エージェントに最適です。","ko":"Next.js, Express, Prismaなどの 기술을 통해 구조화된 작업 요구 사항 분석이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan un análisis de requisitos de tareas estructurados a través de tecnologías como Next.js, Express, y Prisma.","fr":"Parfait pour les agents de développement ayant besoin d''une analyse de besoins de tâches structurés grâce à des technologies comme Next.js, Express, et Prisma.","de":"Perfekt für Entwicklungsmittel, die eine strukturierte Aufgabenanforderungsanalyse durch Technologien wie Next.js, Express und Prisma benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de análise de requisitos de tarefas estruturadas por meio de tecnologias como Next.js, Express e Prisma.","ru":"Идеально подходит для агентов разработки, которым необходима структурированная анализ требований задач через такие технологии, как Next.js, Express и Prisma.","ar":"مثالي لعمليات تطوير الوكلاء التي تحتاج إلى تحليل متطلبات المهمة المنظمة من خلال تقنيات مثل Next.js و Express و Prisma."},"recommendation":{"en":"Empowers agents to convert vague task requirements into concrete designs through structured questioning and exploration, utilizing technologies like Next.js, Express, and Prisma for comprehensive content analysis.","zh":"通过结构化的问题和探索，利用Next.js、Express和Prisma等技术，能够将模糊的任务需求转化为具体的设计，赋予代理人进行综合内容分析的能力。","ja":"構造化された質問と探索を通じて、Next.js、Express、Prismaなどの技術を利用して、曖昧なタスク要件を具体的な設計に変換し、包括的なコンテンツ分析を行うエージェントの能力を強化します。","ko":"구조화된 질문과 탐색을 통해 Next.js, Express, Prisma 등의 기술을 활용하여 모호한 작업 요구 사항을 구체적인 설계로 변환하고, 포괄적인 내용 분석을 수행할 수 있는 에이전트의 능력을 강화합니다.","es":"Habilita a los agentes a convertir requisitos de tareas vagos en diseños concretos a través de preguntas y exploración estructuradas, utilizando tecnologías como Next.js, Express y Prisma para un análisis de contenido integral.","fr":"Permet aux agents de convertir des exigences de tâches vagues en conceptions concrètes grâce à des questions et une exploration structurées, en utilisant des technologies comme Next.js, Express et Prisma pour une analyse de contenu complète.","de":"Ermächtigt die Mittel, vage Aufgabenanforderungen in konkrete Entwürfe durch strukturierte Fragestellung und Exploration umzuwandeln, indem Technologien wie Next.js, Express und Prisma für eine umfassende Inhaltsanalyse verwendet werden.","pt":"Habilita os agentes a converter requisitos de tarefas vagos em projetos concretos por meio de questionamento estruturado e exploração, utilizando tecnologias como Next.js, Express e Prisma para análise abrangente de conteúdo.","ru":"Наделяет агентов возможностью преобразовывать неясные требования задач в конкретные проекты посредством структурированного вопросывания и исследования, используя технологии как Next.js, Express и Prisma для всестороннего анализа контента.","ar":"تمكن الوكلاء من تحويل متطلبات المهام الغامضة إلى تصاميم ملموسة من خلال استجواب منظم واستكشاف، باستخدام تقنيات مثل Next.js و Express و Prisma للتحليل الشامل للمحتوى."},"useCases":{"en":["Converting vague requirements into concrete task designs","Exploring approaches through structured questioning","Analyzing task requirements using multiple-choice questioning"],"zh":["将模糊的需求转化为具体的任务设计","通过结构化的问题进行方法探索","使用多选题进行任务需求分析"],"ja":["曖昧な要件を具体的なタスク設計に変換する","構造化された質問を通じてアプローチを探索する","多肢選択型の質問を使用してタスク要件を分析する"],"ko":["모호한 요구 사항을 구체적인 작업 설계로 변환하는 것","구조화된 질문을 통해 접근 방식을 탐색하는 것","多 선택형 질문을 사용하여 작업 요구 사항을 분석하는 것"],"es":["Convertir requisitos vagos en diseños de tareas concretos","Explorar enfoques a través de preguntas estructuradas","Analizar requisitos de tareas utilizando preguntas de múltiple opción"],"fr":["Convertir des exigences vagues en conceptions de tâches concrètes","Explorer les approches à travers des questions structurées","Analyser les besoins de tâches en utilisant des questions à choix multiple"],"de":["Ungenaue Anforderungen in konkrete Aufgabendesigns umwandeln","Ansätze durch strukturierte Fragestellung erkunden","Aufgabenanforderungen mithilfe von Multiple-Choice-Fragen analysieren"],"pt":["Converter requisitos vagos em projetos de tarefas concretos","Explorar abordagens por meio de questionamento estruturado","Analizar requisitos de tarefas usando questionamento de múltipla escolha"],"ru":["Преобразовывать неясные требования в конкретные проекты задач","Изучать подходы посредством структурированного вопросования","Анализировать требования задач с помощью вопросов с несколькими вариантами ответа"],"ar":["تحويل المتطلبات الغامضة إلى تصاميم ملموسة للمهام","استكشاف المناهج من خلال الاستجواب المنظم","تحليل متطلبات المهام باستخدام أسئلة متعددة الخيارات"]},"limitations":{"en":["Requires clear task requirements for effective analysis","Limited to text-based input and output"],"zh":["需要明确的任务需求才能进行有效的分析","仅限于基于文本的输入和输出"],"ja":["有効な分析を行うには明確なタスク要件が必要","テキストベースの入力と出力のみに限定される"],"ko":["유효한 분석을 수행하기 위해서는 명확한 작업 요구 사항이 필요합니다","텍스트 기반 입력 및 출력만으로 제한됩니다"],"es":["Requiere requisitos de tareas claros para un análisis eficaz","Limitado a entrada y salida basadas en texto"],"fr":["Nécessite des exigences de tâches claires pour une analyse efficace","Limité à l''entrée et à la sortie basées sur le texte"],"de":["Benötigt klare Aufgabenanforderungen für eine effektive Analyse","Begrenzt auf textbasierte Eingabe und Ausgabe"],"pt":["Exige requisitos de tarefas claros para análise eficaz","Limitado à entrada e saída baseada em texto"],"ru":["Требует четких требований задач для эффективного анализа","Ограничен текстовой входной и выходной информацией"],"ar":["يتطلب متطلبات مهمة واضحة لتحليل فعال","محدود بالمدخلات والمخرجات القائمة على النص"]},"version":4},"contentHash":"35ba22358662fbcbbe0c6720d3bc8313872f21c112dfb8d0be79ec1385e4541a","qualityScore":45}');
