INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tung68nt/tulie_lab/knowns.task.brainstorm', 'knowns.task.brainstorm', 'tung68nt', 'tulie_lab', 'community', 'knowns.task.brainstorm tung68nt tulie_lab community The knowns.task.brainstorm skill helps developers and AI agents convert vague task requirements into concrete designs through structured questioning and exploration, utilizing technologies like Next.js, Express, and Prisma. knowns.task.brainstorm 技术是将模糊需求转化为具体设计的解决方案，基于 Next.js 和 Express 构建 LMS 平台 knowns.task.brainstorm は、タスク設計を効率化する AI エージェント技術です。Next.js と Express を使用した LMS プラットフォームの構築を支援します knowns.task.brainstorm 기술은 태스크 디자인을 구체화하는 솔루션으로 Next.js 및 Express 기반의 LMS 플랫폼을 구축합니다 knowns.task.brainstorm es una habilidad para convertir requisitos vagos en diseños concretos a través de preguntas estructuradas y exploración knowns.task.brainstorm est une compétence pour convertir des exigences vagues en conceptions concrètes via des questions structurées et une exploration knowns.task.brainstorm ist eine Fähigkeit, um vage Anforderungen in konkrete Designs durch strukturierte Fragen und Exploration umzusetzen O knowns.task.brainstorm é uma habilidade para desenvolvedores que converte requisitos vagos em design concreto com Next.js, Express e Prisma. knowns.task.brainstorm - это навык для разработчиков, который преобразует нечеткие требования в конкретный дизайн с помощью Next.js, Express и Prisma для ИИ Агентов knowns.task.brainstorm هو مهارة لل مبرمجين لتحويل المتطلبات الغامضة إلى تصميم ملموس باستخدام Next.js و Express و Prisma how to use knowns.task.brainstorm what is knowns.task.brainstorm knowns.task.brainstorm alternative knowns.task.brainstorm vs traditional task design knowns.task.brainstorm install knowns.task.brainstorm setup guide task brainstorming with AI agents structured task design with Next.js and Prisma LMS Platform task management knowns.task.brainstorm Next.js Express LMS 平台 任务脑暴 结构化问题 探索式设计 模糊需求转化 Utilizes a phased approach, starting with Phase 1: Discovery, to understand task requirements Employs structured questioning, using one question at a time, to avoid overwhelming users Supports multiple-choice questioning, such as ''Which approach do you prefer? A) Quick solution with trade-offs'' Integrates with the LMS Platform - The Tulie Lab, built using Next.js, Express, and Prisma Follows a core principle of understanding the problem before proposing solutions Announces the use of the knowns.task.brainstorm skill at the start of the brainstorming process knowns.task.brainstorm is a skill that enables AI agents to facilitate task brainstorming sessions, following a core principle of understanding the problem before proposing solutions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PaulPio/financeFlow/better-auth-best-practices', 'community', 'PaulPio', 'financeFlow', 'PaulPio/financeFlow', 'better-auth-best-practices', 0, 0, 45, '2026-03-07T01:49:01.761Z', '2026-03-07T03:06:59.920Z', 'd67a75a83202355fe76e2db21775cce12e4948189c7b51106989e824bb1da43c', '{"id":"PaulPio/financeFlow/better-auth-best-practices","name":"better-auth-best-practices","description":{"en":"better-auth-best-practices is a TypeScript-first auth framework supporting multiple authentication methods, ideal for developers seeking secure and flexible authentication solutions.","zh":"Better Auth 是一个 TypeScript-first 的框架无关的身份验证框架，支持电子邮件/密码、OAuth、魔术链接、密钥等","ja":"Better Auth は、TypeScript-first のフレームワーク無関係の認証フレームワークで、メール/パスワード、OAuth、魔法リンク、パスキーなどをサポートします","ko":"Better Auth는 TypeScript-first 프레임 워크와 관련이 없는 인증 프레임 워크로서, 이메일/비밀번호, OAuth, 마법 링크, 패스 키 등을 지원합니다","es":"Better Auth es un framework de autenticación agnóstico de framework que soporta correo electrónico/contraseña, OAuth, enlaces mágicos, passkeys y más","fr":"Better Auth est un framework d''authentification agnostique de framework qui prend en charge le courrier électronique/mot de passe, OAuth, liens magiques, passkeys et plus","de":"Better Auth ist ein framework-agnostisches Authentifizierungsframework, das E-Mail/Kennwort, OAuth, Magische Links, Passkeys und mehr unterstützt","pt":"Better Auth é uma estrutura de autenticação TypeScript-first e framework-agnostic que suporta autenticação por e-mail/senha, OAuth, links mágicos, passkeys e mais via plugins.","ru":"Better Auth — это фреймворк аутентификации на основе TypeScript и независимый от фреймворка, поддерживающий аутентификацию по электронной почте/паролю, OAuth, магическим ссылкам, passkeys и многое другое через плагины.","ar":"Better Auth هو إطار تحقق قائم على TypeScript ومتجاوز الإطار، يدعم التحقق بالبريد الإلكتروني/كلمة السر، OAuth، الروابط السحرية، Passkeys وغيرها من خلال الإضافات."},"seo":{"title":{"en":"better-auth-best-practices: Authentication Setup Guide | ...","zh":"Better Auth 最佳实践设置指南","ja":"Better Auth ベストプラクティス設定ガイド - AIエージェント","ko":"Better Auth 최선의 설정 가이드 - AI 툴","es":"Configuración de Better Auth: Mejores Prácticas para la A...","fr":"Guide de Configuration de Better Auth: Meilleures Pratiqu...","de":"Better Auth Konfiguration: Best Practices für die Authent...","pt":"Melhores Práticas de Autenticação com Better Auth: Guia d...","ru":"Лучшие практики аутентификации с Better Auth: Руководство...","ar":"أفضل ممارسات التحقق مع Better Auth: دليل الإعداد لأدوات ا..."},"description":{"en":"Unlock secure authentication with better-auth-best-practices. Learn how to integrate email/password, OAuth, and more via plugins. Get started now!","zh":"了解 Better Auth 的技术细节和最佳实践，实现安全的身份验证和授权","ja":"Better Auth のテクニカル詳細とベストプラクティスを学び、セキュアな認証と承認を実現する - AIエージェント","ko":"Better Auth의 기술 세부 사항과 최선의 실천 방법을 배우고 안전한 인증 및 인가를 구현하십시오 - AI 툴","es":"Aprende a configurar Better Auth para mejorar la seguridad de tu sitio web con nuestras mejores prácticas y ejemplos de código","fr":"Découvrez comment configurer Better Auth pour améliorer la sécurité de votre site web avec nos meilleures pratiques et exemples de code","de":"Erfahren Sie, wie Sie Better Auth konfigurieren, um die Sicherheit Ihrer Website zu verbessern, mit unseren Best Practices und Codebeispielen","pt":"Aprenda a configurar a autenticação com Better Auth, uma estrutura de autenticação TypeScript-first e framework-agnostic, para melhorar a segurança do seu si...","ru":"Узнайте, как настроить аутентификацию с Better Auth, фреймворком аутентификации на основе TypeScript и независимым от фреймворка, для улучшения безопасности ...","ar":"تعرف على كيفية تكوين التحقق مع Better Auth، إطار تحقق قائم على TypeScript ومتجاوز الإطار، لتحسين أمان موقعك الشخصي لشؤون المالية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"better-auth-best-practices is a framework-agnostic authentication framework that supports email/password, OAuth, magic links, passkeys, and more via plugins.","zh":"Better Auth 是一个框架无关的身份验证框架，提供安全的身份验证和授权解决方案","ja":"Better Auth は、セキュアな認証と承認の解決策を提供するフレームワーク無関係の認証フレームワークです","ko":"Better Auth는 안전한 인증 및 인가를 제공하는 프레임 워크와 관련이 없는 인증 프레임 워크입니다","es":"Better Auth es un framework de autenticación que proporciona una forma segura de autenticar a los usuarios","fr":"Better Auth est un framework d''authentification qui fournit un moyen sécurisé d''authentifier les utilisateurs","de":"Better Auth ist ein Authentifizierungsframework, das eine sichere Möglichkeit zur Authentifizierung von Benutzern bietet","pt":"Better Auth é uma estrutura de autenticação que fornece uma solução segura e escalável para sites de finanças pessoais","ru":"Better Auth — это фреймворк аутентификации, который предоставляет безопасное и масштабируемое решение для сайтов личных финансов","ar":"Better Auth هو إطار تحقق يوفر حلًا آمنًا ومرنًا لمواقع شؤون المالية الشخصية"},"features":{"en":["Supports email/password authentication","Enables OAuth integration via plugins","Generates encryption secret using OpenSSL","Requires environment variables BETTER_AUTH_SECRET and BETTER_AUTH_URL","Compatible with TypeScript for robust authentication development","Extensible via plugins for magic links, passkeys, and more"],"zh":["支持电子邮件/密码、OAuth、魔术链接、密钥等身份验证方式","提供 TypeScript-first 的开发体验","支持环境变量配置，例如 BETTER_AUTH_SECRET 和 BETTER_AUTH_URL","提供代码示例和最新 API 文档","支持插件扩展"],"ja":["メール/パスワード、OAuth、魔法リンク、パスキーなどをサポート","TypeScript-first の開発体験を提供","環境変数の設定をサポート、例：BETTER_AUTH_SECRET と BETTER_AUTH_URL","コード例と最新の API ドキュメントを提供","プラグインの拡張をサポート"],"ko":["이메일/비밀번호, OAuth, 마법 링크, 패스 키 등을 지원","TypeScript-first 개발 경험 제공","환경 변수 설정 지원, 예: BETTER_AUTH_SECRET 및 BETTER_AUTH_URL","코드 예제 및 최신 API 문서 제공","플러그인 확장 지원"],"es":["Soporte para autenticación por correo electrónico/contraseña","Integración con OAuth y otros proveedores de autenticación","Uso de enlaces mágicos y passkeys para una autenticación más segura","Compatibilidad con TypeScript y frameworks agnósticos","Configuración de variables de entorno para una mayor seguridad"],"fr":["Prise en charge de l''authentification par courrier électronique/mot de passe","Intégration avec OAuth et d''autres fournisseurs d''authentification","Utilisation de liens magiques et de passkeys pour une authentification plus sécurisée","Compatibilité avec TypeScript et des frameworks agnostiques","Configuration de variables d''environnement pour une sécurité accrue"],"de":["Unterstützung für E-Mail/Kennwort-Authentifizierung","Integration mit OAuth und anderen Authentifizierungsanbietern","Verwendung von Magischen Links und Passkeys für eine sicherere Authentifizierung","Kompatibilität mit TypeScript und framework-agnostischen Frameworks","Konfiguration von Umgebungsvariablen für eine erhöhte Sicherheit"],"pt":["Suporte a autenticação por e-mail/senha","Integração com OAuth","Suporte a links mágicos","Suporte a passkeys","Arquitetura plugin para extensibilidade"],"ru":["Поддержка аутентификации по электронной почте/паролю","Интеграция с OAuth","Поддержка магических ссылок","Поддержка passkeys","Архитектура плагинов для расширения"],"ar":["دعم التحقق بالبريد الإلكتروني/كلمة السر","التكامل مع OAuth","دعم الروابط السحرية","دعم Passkeys","هندسة الإضافات للتوسعة"]},"keywords":{"en":["how to use better-auth-best-practices","better-auth-best-practices setup guide","better-auth-best-practices alternative","better-auth-best-practices vs Auth0","better-auth-best-practices install","TypeScript authentication framework","OAuth plugin integration","email/password authentication security"],"zh":["Better Auth","身份验证框架","TypeScript-first","框架无关","电子邮件/密码","OAuth","魔术链接","密钥","环境变量","代码示例","API 文档"],"ja":["Better Auth","認証フレームワーク","TypeScript-first","フレームワーク無関係","メール/パスワード","OAuth","魔法リンク","パスキー","環境変数","コード例","API ドキュメント"],"ko":["Better Auth","인증 프레임 워크","TypeScript-first","프레임 워크와 관련이 없음","이메일/비밀번호","OAuth","마법 링크","패스 키","환경 변수","코드 예제","API 문서"],"es":["autenticación segura","better auth","typescript","framework agnóstico","oauth","enlaces mágicos","passkeys","configuración de seguridad","variables de entorno"],"fr":["authentification sécurisée","better auth","typescript","framework agnostique","oauth","liens magiques","passkeys","configuration de sécurité","variables d''environnement"],"de":["sichere Authentifizierung","better auth","typescript","framework-agnostisches Framework","oauth","Magische Links","Passkeys","Sicherheitskonfiguration","Umgebungsvariablen"],"pt":["autenticação segura","Better Auth","TypeScript","framework-agnostic","OAuth","links mágicos","passkeys","plugins"," finanças pessoais"],"ru":["безопасная аутентификация","Better Auth","TypeScript","фреймворк-независимый","OAuth","магические ссылки","passkeys","плагины","личные финансы","ИИ Агенты"],"ar":["تحقق آمن","Better Auth","TypeScript","متجاوز الإطار","OAuth","روابط سحرية","Passkeys","إضافات","شؤون مالية شخصية","أدوات الذكاء الاصطناعي"]}},"owner":"PaulPio","repo":"financeFlow","repoPath":"PaulPio/financeFlow","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.761Z","topics":[],"category":"community","skillMd":{"name":"better-auth-best-practices","description":"Skill for integrating Better Auth - the comprehensive TypeScript authentication framework.","bodyPreview":"# Better Auth Integration Guide\n\n**Always consult [better-auth.com/docs](https://better-auth.com/docs) for code examples and latest API.**\n\nBetter Auth is a TypeScript-first, framework-agnostic auth framework supporting email/password, OAuth, magic links, passkeys, and more via plugins.\n\n---\n\n## Quick Reference\n\n### Environment Variables\n- `BETTER_AUTH_SECRET` - Encryption secret (min 32 chars). Generate: `openssl rand -base64 32`\n- `BETTER_AUTH_URL` - Base URL (e.g., `https://example.com`)\n\nOnl","body":"# Better Auth Integration Guide\n\n**Always consult [better-auth.com/docs](https://better-auth.com/docs) for code examples and latest API.**\n\nBetter Auth is a TypeScript-first, framework-agnostic auth framework supporting email/password, OAuth, magic links, passkeys, and more via plugins.\n\n---\n\n## Quick Reference\n\n### Environment Variables\n- `BETTER_AUTH_SECRET` - Encryption secret (min 32 chars). Generate: `openssl rand -base64 32`\n- `BETTER_AUTH_URL` - Base URL (e.g., `https://example.com`)\n\nOnly define `baseURL`/`secret` in config if env vars are NOT set.\n\n### File Location\nCLI looks for `auth.ts` in: `./`, `./lib`, `./utils`, or under `./src`. Use `--config` for custom path.\n\n### CLI Commands\n- `npx @better-auth/cli@latest migrate` - Apply schema (built-in adapter)\n- `npx @better-auth/cli@latest generate` - Generate schema for Prisma/Drizzle\n- `npx @better-auth/cli mcp --cursor` - Add MCP to AI tools\n\n**Re-run after adding/changing plugins.**\n\n---\n\n## Core Config Options\n\n| Option | Notes |\n|--------|-------|\n| `appName` | Optional display name |\n| `baseURL` | Only if `BETTER_AUTH_URL` not set |\n| `basePath` | Default `/api/auth`. Set `/` for root. |\n| `secret` | Only if `BETTER_AUTH_SECRET` not set |\n| `database` | Required for most features. See adapters docs. |\n| `secondaryStorage` | Redis/KV for sessions & rate limits |\n| `emailAndPassword` | `{ enabled: true }` to activate |\n| `socialProviders` | `{ google: { clientId, clientSecret }, ... }` |\n| `plugins` | Array of plugins |\n| `trustedOrigins` | CSRF whitelist |\n\n---\n\n## Database\n\n**Direct connections:** Pass `pg.Pool`, `mysql2` pool, `better-sqlite3`, or `bun:sqlite` instance.\n\n**ORM adapters:** Import from `better-auth/adapters/drizzle`, `better-auth/adapters/prisma`, `better-auth/adapters/mongodb`.\n\n**Critical:** Better Auth uses adapter model names, NOT underlying table names. If Prisma model is `User` mapping to table `users`, use `modelName: \"user\"` (Prisma reference), not `\"users\"`.\n\n---\n\n## Session Management\n\n**Storage priority:**\n1. If `secondaryStorage` defined → sessions go there (not DB)\n2. Set `session.storeSessionInDatabase: true` to also persist to DB\n3. No database + `cookieCache` → fully stateless mode\n\n**Cookie cache strategies:**\n- `compact` (default) - Base64url + HMAC. Smallest.\n- `jwt` - Standard JWT. Readable but signed.\n- `jwe` - Encrypted. Maximum security.\n\n**Key options:** `session.expiresIn` (default 7 days), `session.updateAge` (refresh interval), `session.cookieCache.maxAge`, `session.cookieCache.version` (change to invalidate all sessions).\n\n---\n\n## User & Account Config\n\n**User:** `user.modelName`, `user.fields` (column mapping), `user.additionalFields`, `user.changeEmail.enabled` (disabled by default), `user.deleteUser.enabled` (disabled by default).\n\n**Account:** `account.modelName`, `account.accountLinking.enabled`, `account.storeAccountCookie` (for stateless OAuth).\n\n**Required for registration:** `email` and `name` fields.\n\n---\n\n## Email Flows\n\n- `emailVerification.sendVerificationEmail` - Must be defined for verification to work\n- `emailVerification.sendOnSignUp` / `sendOnSignIn` - Auto-send triggers\n- `emailAndPassword.sendResetPassword` - Password reset email handler\n\n---\n\n## Security\n\n**In `advanced`:**\n- `useSecureCookies` - Force HTTPS cookies\n- `disableCSRFCheck` - ⚠️ Security risk\n- `disableOriginCheck` - ⚠️ Security risk  \n- `crossSubDomainCookies.enabled` - Share cookies across subdomains\n- `ipAddress.ipAddressHeaders` - Custom IP headers for proxies\n- `database.generateId` - Custom ID generation or `\"serial\"`/`\"uuid\"`/`false`\n\n**Rate limiting:** `rateLimit.enabled`, `rateLimit.window`, `rateLimit.max`, `rateLimit.storage` (\"memory\" | \"database\" | \"secondary-storage\").\n\n---\n\n## Hooks\n\n**Endpoint hooks:** `hooks.before` / `hooks.after` - Array of `{ matcher, handler }`. Use `createAuthMiddleware`. Access `ctx.path`, `ctx.context.returned` (after), `ctx.context.session`.\n\n**Database hooks:** `databaseHooks.user.create.before/after`, same for `session`, `account`. Useful for adding default values or post-creation actions.\n\n**Hook context (`ctx.context`):** `session`, `secret`, `authCookies`, `password.hash()`/`verify()`, `adapter`, `internalAdapter`, `generateId()`, `tables`, `baseURL`.\n\n---\n\n## Plugins\n\n**Import from dedicated paths for tree-shaking:**\n```\nimport { twoFactor } from \"better-auth/plugins/two-factor\"\n```\nNOT `from \"better-auth/plugins\"`.\n\n**Popular plugins:** `twoFactor`, `organization`, `passkey`, `magicLink`, `emailOtp`, `username`, `phoneNumber`, `admin`, `apiKey`, `bearer`, `jwt`, `multiSession`, `sso`, `oauthProvider`, `oidcProvider`, `openAPI`, `genericOAuth`.\n\nClient plugins go in `createAuthClient({ plugins: [...] })`.\n\n---\n\n## Client\n\nImport from: `better-auth/client` (vanilla), `better-auth/react`, `better-auth/vue`, `better-auth/svelte`, `better-auth/solid`.\n\nKey methods: `signUp.email()`, `signIn.email()`, `signIn.social()`, `signOut()`, `useSession()`, `getSession()`, `revokeSession()`, `revokeSessions()`.\n\n---\n\n## Type Safety\n\nInfer types: `typeof auth.$Infer.Session`, `typeof auth.$Infer.Session.user`.\n\nFor separate client/server projects: `createAuthClient<typeof auth>()`.\n\n---\n\n## Common Gotchas\n\n1. **Model vs table name** - Config uses ORM model name, not DB table name\n2. **Plugin schema** - Re-run CLI after adding plugins\n3. **Secondary storage** - Sessions go there by default, not DB\n4. **Cookie cache** - Custom session fields NOT cached, always re-fetched\n5. **Stateless mode** - No DB = session in cookie only, logout on cache expiry\n6. **Change email flow** - Sends to current email first, then new email\n\n---\n\n## Resources\n\n- [Docs](https://better-auth.com/docs)\n- [Options Reference](https://better-auth.com/docs/reference/options)\n- [LLMs.txt](https://better-auth.com/llms.txt)\n- [GitHub](https://github.com/better-auth/better-auth)\n- [Init Options Source](https://github.com/better-auth/better-auth/blob/main/packages/core/src/types/init-options.ts)"},"lastSynced":"2026-03-07T03:06:59.920Z","agentAnalysis":{"suitability":{"en":"Perfect for Security-focused Agents needing flexible and secure authentication solutions with support for multiple methods like email/password, OAuth, and passkeys.","zh":"非常适合需要灵活且安全的身份验证解决方案的安全专注型Agent，支持多种方法，如电子邮件/密码、OAuth和密钥。","ja":"セキュリティに焦点を当てたエージェントが柔軟で安全な認証ソリューションを必要とする場合に最適です。電子メール/パスワード、OAuth、パスキーのような複数の方法をサポートします。","ko":"안전한 인증 솔루션을 필요로 하는 보안 중심 에이전트에게 적합합니다. 이메일/비밀번호, OAuth, 패스키와 같은 여러 방법을 지원합니다.","es":"Perfecto para Agentes de seguridad que necesitan soluciones de autenticación flexibles y seguras con soporte para múltiples métodos como correo electrónico/contraseña, OAuth y passkeys.","fr":"Idéal pour les agents de sécurité qui nécessitent des solutions d''authentification flexibles et sécurisées avec prise en charge de plusieurs méthodes telles que l''e-mail/mot de passe, OAuth et passkeys.","de":"Perfekt für Sicherheits-Agents, die flexible und sichere Authentifizierungslösungen mit Unterstützung für mehrere Methoden wie E-Mail/Kennwort, OAuth und Passkeys benötigen.","pt":"Perfeito para Agentes focados em Segurança que precisam de soluções de autenticação flexíveis e seguras com suporte a vários métodos como email/senha, OAuth e passkeys.","ru":"Идеально подходит для агентов, ориентированных на безопасность, которым необходимы гибкие и безопасные решения аутентификации с поддержкой нескольких методов, таких как электронная почта/пароль, OAuth и ключи.","ar":"مثالي للوكلاء الذين يركزون على الأمن والذين يحتاجون إلى حلول مصادقة مرنة وأمنة مع دعم لطرق متعددة مثل البريد الإلكتروني / كلمة المرور و OAuth والمفاتيح."},"recommendation":{"en":"Empowers agents to implement robust authentication mechanisms using TypeScript-first framework-agnostic approaches, supporting plugins for enhanced security via encryption secrets and base URL configurations with environment variables like BETTER_AUTH_SECRET and BETTER_AUTH_URL.","zh":"使得代理能够使用TypeScript-first框架无关的方法实现强大的身份验证机制，支持插件以增强安全性，通过加密密钥和基本URL配置，使用环境变量如BETTER_AUTH_SECRET和BETTER_AUTH_URL。","ja":"エージェントがTypeScript-firstフレームワーク非依存アプローチを使用して強力な認証メカニズムを実装できるようにします。プラグインをサポートして、環境変数BETTER_AUTH_SECRETとBETTER_AUTH_URLを使用して、暗号化シークレットとベースURLの構成を介してセキュリティを強化します。","ko":"에이전트가 TypeScript-first 프레임워크 비의존적 접근 방식을 사용하여 강력한 인증 메커니즘을 구현할 수 있도록 합니다. 보안을 강화하기 위해 플러그인을 지원하며, 환경 변수 BETTER_AUTH_SECRET 및 BETTER_AUTH_URL를 사용하여 암호화 키 및 기본 URL 구성으로 보안을 강화합니다.","es":"Habilita a los agentes a implementar mecanismos de autenticación robustos utilizando enfoques agnósticos de framework en primer lugar con TypeScript, que admiten complementos para una mayor seguridad a través de secretos de cifrado y configuraciones de URL base con variables de entorno como BETTER_AUTH_SECRET y BETTER_AUTH_URL.","fr":"Permet aux agents de mettre en œuvre des mécanismes d''authentification robustes en utilisant des approches framework-agnostiques en premier lieu avec TypeScript, qui prennent en charge des plugins pour une sécurité améliorée via des secrets de chiffrement et des configurations d''URL de base avec des variables d''environnement comme BETTER_AUTH_SECRET et BETTER_AUTH_URL.","de":"Ermächtigt die Agents, robuste Authentifizierungsmechanismen mithilfe von framework-agnostischen Ansätzen in erster Linie mit TypeScript zu implementieren, die Plugins für eine verbesserte Sicherheit durch Verschlüsselungsgeheimnisse und Basis-URL-Konfigurationen mit Umgebungsvariablen wie BETTER_AUTH_SECRET und BETTER_AUTH_URL unterstützen.","pt":"Habilita os agentes a implementar mecanismos de autenticação robustos usando abordagens framework-agnostic baseadas em TypeScript, com suporte a plugins para segurança reforçada via segredos de criptografia e configurações de URL base com variáveis de ambiente como BETTER_AUTH_SECRET e BETTER_AUTH_URL.","ru":"Предоставляет агентам возможность реализовать надежные механизмы аутентификации, используя подходы, независимые от фреймворка, на основе TypeScript, с поддержкой плагинов для повышения безопасности с помощью секретов шифрования и конфигураций базового URL с переменными среды, такими как BETTER_AUTH_SECRET и BETTER_AUTH_URL.","ar":"تمكين الوكلاء من تنفيذ آليات مصادقة قوية باستخدام نهج TypeScript-first framework-agnostic، مع دعم الإضافات لتعزيز الأمان من خلال أسرار التشفير وتكوين عنوان URL الأساسي مع متغيرات البيئة مثل BETTER_AUTH_SECRET و BETTER_AUTH_URL."},"useCases":{"en":["Implementing email/password authentication with enhanced security","Configuring OAuth for social media login integrations","Generating and managing passkeys for passwordless authentication"],"zh":["使用增强的安全性实现电子邮件/密码身份验证","配置OAuth用于社交媒体登录集成","生成和管理密钥用于无密码身份验证"],"ja":["強化されたセキュリティで電子メール/パスワード認証を実装する","OAuthを構成してソーシャルメディアログイン統合を行う","パスワードレス認証用のパスキーを生成して管理する"],"ko":["보안을 강화한 이메일/비밀번호 인증을 구현하는 것","소셜 미디어 로그인 통합을 위한 OAuth 구성","패스워드 없는 인증을 위한 패스키 생성 및 관리"],"es":["Implementar la autenticación de correo electrónico/contraseña con seguridad mejorada","Configurar OAuth para integraciones de inicio de sesión en redes sociales","Generar y administrar passkeys para la autenticación sin contraseña"],"fr":["Mettre en œuvre l''authentification par e-mail/mot de passe avec une sécurité renforcée","Configurer OAuth pour les intégrations de connexion aux réseaux sociaux","Générer et gérer des passkeys pour l''authentification sans mot de passe"],"de":["Implementierung der E-Mail/Kennwort-Authentifizierung mit verbesserter Sicherheit","Konfiguration von OAuth für soziale Medien-Login-Integrationen","Generieren und Verwalten von Passkeys für die authentifizierung ohne Kennwort"],"pt":["Implementar autenticação por email/senha com segurança reforçada","Configurar OAuth para integrações de login de mídia social","Gerar e gerenciar passkeys para autenticação sem senha"],"ru":["Реализация аутентификации по электронной почте/паролю с повышенной безопасностью","Настройка OAuth для интеграций социальных сетей","Генерация и управление ключами для аутентификации без пароля"],"ar":["تنفيذ مصادقة البريد الإلكتروني / كلمة المرور مع أمان محسن","تكوين OAuth لدمج تسجيل الدخول إلى وسائل الإعلام الاجتماعية","إنشاء وإدارة المفاتيح للمصادقة بدون كلمة مرور"]},"limitations":{"en":["Requires TypeScript compatibility","Needs generation and secure storage of BETTER_AUTH_SECRET","Dependent on specific environment variable configurations"],"zh":["需要TypeScript兼容性","需要生成和安全存储BETTER_AUTH_SECRET","依赖于特定的环境变量配置"],"ja":["TypeScriptの互換性が必要","BETTER_AUTH_SECRETの生成と安全な保存が必要","特定の環境変数の構成に依存する"],"ko":["TypeScript 호환성이 필요함","BETTER_AUTH_SECRET의 생성 및 보안 저장이 필요함","특정 환경 변수 구성에 의존함"],"es":["Requiere compatibilidad con TypeScript","Necesita la generación y el almacenamiento seguro de BETTER_AUTH_SECRET","Depende de configuraciones de variables de entorno específicas"],"fr":["Nécessite la compatibilité avec TypeScript","Nécessite la génération et le stockage sécurisé de BETTER_AUTH_SECRET","Dépend de configurations de variables d''environnement spécifiques"],"de":["Benötigt TypeScript-Kompatibilität","Benötigt die Generierung und sichere Speicherung von BETTER_AUTH_SECRET","Hängt von bestimmten Umgebungsvariablen-Konfigurationen ab"],"pt":["Exige compatibilidade com TypeScript","Necessita geração e armazenamento seguro de BETTER_AUTH_SECRET","Depende de configurações específicas de variáveis de ambiente"],"ru":["Требует совместимости с TypeScript","Требует генерации и безопасного хранения BETTER_AUTH_SECRET","Зависит от конкретных конфигураций переменных среды"],"ar":["يتطلب توافقًا مع TypeScript","يتطلب توليد وتخزين آمن لـ BETTER_AUTH_SECRET","يعتمد على تكوينات متغيرات البيئة المحددة"]},"version":4},"contentHash":"d67a75a83202355fe76e2db21775cce12e4948189c7b51106989e824bb1da43c","qualityScore":45}');
