INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('geekskai/blog/ai-seo-optimization', 'ai-seo-optimization', 'geekskai', 'blog', 'community', 'ai-seo-optimization geekskai blog community blog blog-template blog-theme github-pages nextjs nextjs-blog nextjs-template nextjs14 reactjs tainwindcss ai-seo-optimization helps developers optimize their Next.js 14 blogs for AI search engines, ensuring maximum visibility and reach. Ideal for ReactJS and GitHub Pages users. 使用Next.js 14和AI SEO优化技巧，快速部署您的专业博客，并提升您的SEO排名 Next.js 14とAIエージェントによるSEO最適化テクニックを使用して、プロフェッショナルブログを迅速にデプロイし、SEOランキングを向上させます Next.js 14와 AI SEO 최적화 기법을 사용하여 전문 블로그를 빠르게 배포하고 SEO 순위를 향상시키세요 Optimiza tu contenido y sitio web para motores de búsqueda de IA con nuestra guía de AI-SEO-Optimization, que cubre principios básicos como la presencia de la marca y la puntuación de recuperación de información Optimisez votre contenu et votre site web pour les moteurs de recherche d''IA avec notre guide d''optimisation SEO, qui couvre les principes de base tels que la présence de la marque et le score de récupération d''informations Optimieren Sie Ihren Inhalt und Ihre Website für IA-Suchmaschinen mit unserem AI-SEO-Optimization-Leitfaden, der grundlegende Prinzipien wie Markenpräsenz und Informationsabrufscore behandelt Otimização de SEO para IA é fundamental para melhorar a visibilidade do seu site. Aprenda a configurar com Next.js e React Оптимизация SEO для ИИ Агентов необходима для улучшения видимости вашего сайта. Узнайте, как настроить с помощью Next.js и React تحسين محركات البحث للعوامل الذكية ضروري لتحسين وضوح موقعك. تعلم كيفية الإعداد باستخدام Next.js و React how to use ai-seo-optimization ai-seo-optimization tutorial Next.js 14 SEO optimization ai-seo-optimization vs traditional SEO ai-seo-optimization setup guide ai-seo-optimization for ReactJS developers AI SEO优化 Next.js 14 博客模板 快速部署 Markdown 自定义域名 评论功能 信息检索评分 内容新鲜度 Supports Markdown writing and one-click deployment Utilizes Next.js 14 for extreme performance and scalability Integrates with Tailwind CSS for customizable styling Enables custom domain and comment functionality Follows core principles of brand presence and information retrieval scoring ai-seo-optimization is a technique for optimizing website content and structure for AI-powered search engines, focusing on brand presence, information retrieval, and content freshness.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tile-ai/TileOPs/creating-pull-request', 'community', 'tile-ai', 'TileOPs', 'tile-ai/TileOPs', 'creating-pull-request', 88, 23, 44, '2026-03-04T11:03:48Z', '2026-03-06T06:33:00.034Z', '908d09b67d35f2de0677ca43ee283a29e18232a82153c5e952f48829bb5d4719', '{"id":"tile-ai/TileOPs/creating-pull-request","name":"creating-pull-request","description":{"en":"The creating-pull-request skill helps developers create pull requests with proper formatting and conventions. It benefits developers working on collaborative projects using git.","zh":"创建拉取请求的技术指南，涵盖 Git 和 CLI 的使用","ja":"プルリクエストを作成するためのテクニカルガイド。Git と CLI の使用方法を含みます","ko":"풀 리퀘스트 생성을 위한 기술 가이드입니다. Git 및 CLI의 사용법을 포함합니다","es":"Crea solicitudes de extracción de manera efectiva con nuestra guía técnica y domina Git y GitHub con AI Agent.","fr":"Créez des demandes d''extraction de manière efficace avec notre guide technique et maîtrisez Git et GitHub avec les outils AI.","de":"Erstellen Sie Pull-Requests effektiv mit unserer technischen Anleitung und beherrschen Sie Git und GitHub mit AI-Tools.","pt":"Criar pull requests de forma eficiente usando comandos Git e seguindo convenções de título e formato de corpo","ru":"Создание pull request эффективно с помощью команд Git и соблюдение конвенций названия и формата тела","ar":"إنشاء طلبات السحب بفعالية باستخدام أوامر Git ومتابعة اتفاقيات العنوان وتنسيق الجسم"},"seo":{"title":{"en":"Creating-Pull-Request: Setup Guide for AI Agents","zh":"创建拉取请求 Setup Guide - AIエージェント工具","ja":"プルリクエストの作成ベストプラクティス - AIエージェント","ko":"풀 리퀘스트 생성 가이드 - AI 에이전트 도구","es":"Guía de configuración para crear solicitudes de extracció...","fr":"Guide de configuration pour créer des demandes d''extracti...","de":"Konfigurationsleitfaden für das Erstellen von Pull-Reques...","pt":"Guia de Configuração para Criar Pull Request com Ferramen...","ru":"Настройка ИИ Агентов для Создания Pull Request: Руководство","ar":"دليل إعداد وإنشاء طلبات السحب باستخدام أدوات الذكاء الاصط..."},"description":{"en":"Learn how to create pull requests with ease using git commands and conventions. Get started with our setup guide and master the art of collaborative coding.","zh":"了解如何使用 Git 和 CLI 创建拉取请求，包括仓库查看、分支管理和提交日志","ja":"Git と CLI を使用してプルリクエストを作成する方法について学びます。リポジトリの表示、ブランチの管理、コミットログなどを含みます","ko":"Git 및 CLI를 사용하여 풀 리퀘스트를 생성하는 방법을 알아보세요. 리포지토리 보기, 브랜치 관리, 커밋 로그 등을 포함합니다","es":"Aprende a crear solicitudes de extracción con nuestra guía paso a paso y mejora tus habilidades en Git y GitHub con AI Agent","fr":"Découvrez comment créer des demandes d''extraction avec notre guide étape par étape et améliorez vos compétences en Git et GitHub avec les outils AI","de":"Erfahren Sie, wie Sie Pull-Requests mit unserer Schritt-für-Schritt-Anleitung erstellen und Ihre Fähigkeiten in Git und GitHub mit AI-Tools verbessern","pt":"Aprenda a criar pull requests com eficiência usando ferramentas de IA e siga as melhores práticas para contribuir para repositórios Git","ru":"Узнайте, как создавать pull request с помощью ИИ Агентов и следуйте лучшим практикам для вклада в репозитории Git","ar":"تعلم كيفية إنشاء طلبات السحب بفعالية باستخدام أدوات الذكاء الاصطناعي واتبع أفضل الممارسات للمساهمة في مستودعات Git"},"definition":{"en":"creating-pull-request is a skill that automates the process of creating pull requests using git commands and following specific conventions","zh":"创建拉取请求是使用 Git 和 CLI 提交代码变更的过程","ja":"プルリクエストの作成は、Git と CLI を使用してコードの変更を提出するプロセスです","ko":"풀 리퀘스트 생성은 Git 및 CLI를 사용하여 코드 변경을 제출하는 과정입니다","es":"Crear una solicitud de extracción es un proceso que permite a los desarrolladores proponer cambios en un repositorio de GitHub","fr":"Créer une demande d''extraction est un processus qui permet aux développeurs de proposer des modifications dans un référentiel GitHub","de":"Das Erstellen eines Pull-Requests ist ein Prozess, der es Entwicklern ermöglicht, Änderungen in einem GitHub-Repository vorzuschlagen","pt":"Criar pull request é o processo de contribuir para repositórios Git enviando alterações para revisão","ru":"Создание pull request - это процесс вклада в репозитории Git путем отправки изменений для рассмотрения","ar":"إنشاء طلب السحب هو عملية المساهمة في مستودعات Git من خلال إرسال التعديلات للتحقق"},"features":{"en":["Displays current repository state using gh repo view and git branch commands","Shows commits on the current branch using git log","Provides remote repository information using git remote","Follows PR title conventions outlined in docs/CONTRIBUTING.md","Uses template.md for PR body format","References .claude/c for type lists, regex patterns, and label mappings"],"zh":["使用 Git 命令查看仓库信息","管理分支和提交日志","使用 CLI 创建拉取请求","遵循特定的 PR 标题和正文格式","参考文档和模板以确保正确性"],"ja":["Git コマンドを使用してリポジトリ情報を表示","ブランチとコミットログを管理","CLI を使用してプルリクエストを作成","特定の PR タイトルと本文形式に従う","ドキュメントとテンプレートを参考して正確性を確保"],"ko":["Git 명령을 사용하여 리포지토리 정보를 표시","브랜치와 커밋 로그를 관리","CLI를 사용하여 풀 리퀘스트를 생성","특정한 PR 제목과 본문 형식을 따름","문서와 템플릿을 참조하여 정확성을 보장"],"es":["Integración con GitHub para crear solicitudes de extracción","Uso de Git para gestionar commits y ramas","Compatibilidad con plantillas de título y cuerpo de solicitud de extracción","Acceso a la documentación de contribución para seguir las convenciones","Uso de expresiones regulares y mapeo de etiquetas para la automatización"],"fr":["Intégration avec GitHub pour créer des demandes d''extraction","Utilisation de Git pour gérer les commits et les branches","Compatibilité avec les modèles de titre et de corps de demande d''extraction","Accès à la documentation de contribution pour suivre les conventions","Utilisation d''expressions régulières et de mappage d''étiquettes pour l''automatisation"],"de":["Integration mit GitHub zum Erstellen von Pull-Requests","Verwendung von Git zur Verwaltung von Commits und Branches","Kompatibilität mit Vorlagen für Titel und Body von Pull-Requests","Zugriff auf die Beitragsdokumentation, um Konventionen zu befolgen","Verwendung von regulären Ausdrücken und Label-Mappings für die Automatisierung"],"pt":["Uso de comandos Git para visualizar repositórios e branches","Acesso a documentos de contribuição para convenções de título e formato de corpo","Integração com templates para facilitar a criação de pull requests","Suporte a labels e tipos de pull requests para organização","Uso de regex patterns para validação de títulos e descrições","Integração com CLI para automação de tarefas"],"ru":["Использование команд Git для просмотра репозиториев и веток","Доступ к документам вклада для конвенций названия и формата тела","Интеграция с шаблонами для упрощения создания pull request","Поддержка меток и типов pull request для организации","Использование шаблонов regex для проверки названий и описаний","Интеграция с CLI для автоматизации задач"],"ar":["استخدام أوامر Git لعرض المستودعات والفروع","الدخول إلى وثائق المساهمة لاتفاقيات العنوان وتنسيق الجسم","التكامل مع القوالب لتسهيل إنشاء طلبات السحب","دعم العلامات وأنواع طلبات السحب للتنظيم","استخدام أنماط regex للتحقق من العناوين والوصف","التكامل مع CLI لآلية المهام"]},"keywords":{"en":["how to create a pull request","creating-pull-request setup guide","git pull request conventions","collaborative coding best practices","creating-pull-request vs git flow","install creating-pull-request","creating-pull-request alternative","what is creating-pull-request","creating-pull-request tutorial"],"zh":["创建拉取请求","Git 命令","CLI 工具","仓库管理","分支管理","提交日志","PR 标题格式","AIエージェント工具"],"ja":["プルリクエストの作成","Git コマンド","CLI ツール","リポジトリ管理","ブランチ管理","コミットログ","PR タイトル形式","AIエージェント"],"ko":["풀 리퀘스트 생성","Git 명령","CLI 도구","리포지토리 관리","브랜치 관리","커밋 로그","PR 제목 형식","AI 에이전트 도구"],"es":["crear solicitud de extracción","AI Agent","GitHub","Git","plantillas de solicitud de extracción","documentación de contribución","expresiones regulares","mapeo de etiquetas"],"fr":["créer demande d''extraction","outils AI","GitHub","Git","modèles de demande d''extraction","documentation de contribution","expressions régulières","mappage d''étiquettes"],"de":["Pull-Request erstellen","AI-Tools","GitHub","Git","Vorlagen für Pull-Requests","Beitragsdokumentation","reguläre Ausdrücke","Label-Mappings"],"pt":["criar pull request","ferramentas de IA para Git","contribuir para repositórios","comandos Git para pull request","convenções de título e formato de corpo","templates para pull request","labels e tipos de pull request","regex patterns para validação","CLI para automação de tarefas"],"ru":["создать pull request","ИИ Агенты для Git","вклад в репозитории","команды Git для pull request","конвенции названия и формата тела","шаблоны для pull request","метки и типы pull request","шаблоны regex для проверки","CLI для автоматизации задач"],"ar":["إنشاء طلب السحب","أدوات الذكاء الاصطناعي لمستودعات Git","المساهمة في المستودعات","أوامر Git لطلبات السحب","اتفاقيات العنوان وتنسيق الجسم","قوالب لطلبات السحب","العلامات وأنواع طلبات السحب","نماط regex للتحقق","CLI لآلية المهام"]}},"owner":"tile-ai","repo":"TileOPs","repoPath":"tile-ai/TileOPs","stars":88,"forks":23,"updatedAt":"2026-03-04T11:03:48Z","topics":[],"category":"community","skillMd":{"name":"creating-pull-request","description":"Create a PR with correct title, body, and labels following TileOPs conventions. Use when you have a pushed branch ready for PR creation.","bodyPreview":"## Current state\n\n- Repo: !`gh repo view --json nameWithOwner -q ''.nameWithOwner''`\n- Branch: !`git branch --show-current`\n- Commits on branch: !`git log --oneline main..HEAD 2>/dev/null || echo \"(no commits vs main)\"`\n- Remote: !`git remote -v | head -2`\n\n## Task\n\n\\$ARGUMENTS\n\n## Reference\n\nRead `docs/CONTRIBUTING.md` before proceeding for PR title conventions.\n\nFor PR body format, see [template.md](template.md).\n\n**Source of truth** for type lists, regex patterns, and label mappings: `.claude/c","body":"## Current state\n\n- Repo: !`gh repo view --json nameWithOwner -q ''.nameWithOwner''`\n- Branch: !`git branch --show-current`\n- Commits on branch: !`git log --oneline main..HEAD 2>/dev/null || echo \"(no commits vs main)\"`\n- Remote: !`git remote -v | head -2`\n\n## Task\n\n\\$ARGUMENTS\n\n## Reference\n\nRead `docs/CONTRIBUTING.md` before proceeding for PR title conventions.\n\nFor PR body format, see [template.md](template.md).\n\n**Source of truth** for type lists, regex patterns, and label mappings: `.claude/conventions/types.sh`.\n\n## Steps\n\nExecute these steps in order. **Do NOT skip any HARD GATE.**\n\n### Step 1: Determine owner/repo\n\n```bash\ngh repo view --json nameWithOwner -q ''.nameWithOwner''\n```\n\nSplit into `{owner}` and `{repo}`.\n\n### Step 2: Create the PR\n\nUse `gh pr create`. **Do NOT use the GitHub MCP tool** — `gh` CLI avoids the `\\n` pitfall.\n\n```bash\ngh pr create --base main --head \"$(git branch --show-current)\" \\\n  --draft \\\n  --title \"[Type] Description\" \\\n  --body \"$(cat <<''PREOF''\n<fill in from template.md>\nPREOF\n)\"\n```\n\n**Draft-first workflow:** Always create PRs as draft. Copilot reviews drafts automatically; Gemini must be triggered separately (see `lifecycle-pull-request` Phase 2b). Once CI passes and both bot reviews are addressed, the `lifecycle-pull-request` skill marks the PR ready, triggering human reviewer notifications.\n\nPR title rules:\n\n- **Must** use bracket format: `[Type] Description` or `[Type][Scope] Description`\n- Types: `[Feat]`, `[BugFix]`, `[Fix]`, `[Refactor]`, `[Enhancement]`, `[Doc]`, `[Chore]`, `[Bench]`, `[CI]`, `[Test]`, `[Perf]`\n- Keep under ~80 chars\n- **Do NOT** put issue references in the title (e.g. `(#123)`). Link issues in the PR body with `Closes #123` instead.\n\nPR body section rules:\n\n- `## Summary` — always required\n- `## Test plan` — always required\n- `## Benchmark` — required when PR involves performance changes\n- `## Regression` — recommended when PR is bugfix or refactor\n- `## Additional context` — optional\n- **Delete** inapplicable optional sections entirely. Never leave empty headers.\n\n### Step 3: Add labels (MANDATORY)\n\n**At least one label is required.** Select based on PR type:\n\n| PR Type              | Label             |\n| -------------------- | ----------------- |\n| `[Feat]`             | `feature`         |\n| `[BugFix]` / `[Fix]` | `fix`             |\n| `[Enhancement]`      | `enhancement`     |\n| `[Refactor]`         | `refactor`        |\n| `[Doc]`              | `docs`            |\n| `[Chore]`            | `chore`           |\n| `[Bench]`            | `bench`           |\n| `[CI]`               | `ci`              |\n| `[Test]`             | `test`            |\n| `[Perf]`             | `perf`            |\n| Breaking change      | `breaking change` |\n\nAuthorship label (**required**):\n\n- `all-ai-powered` — always add this label (you are an AI creating this PR)\n\n```bash\ngh pr edit <PR_NUMBER> --add-label \"<label1>\" --add-label \"<label2>\"\n```\n\n### Step 4: HARD GATE — Validate PR\n\n```bash\n.claude/skills/creating-pull-request/scripts/validate.sh <owner/repo> <PR_NUMBER>\n```\n\n**If exit code != 0: STOP.** Fix the reported issues:\n\n- Wrong title → `gh pr edit <N> --title \"[Type] New title\"`\n- Missing body section → `gh pr edit <N> --body \"$(cat <<''EOF'' ... EOF)\"`\n- Missing labels → `gh pr edit <N> --add-label \"<label>\"`\n\nRe-run the gate until it passes.\n\n## Responding to reviewer feedback\n\nWhen addressing reviewer comments (from Copilot, Gemini, or humans):\n\n- **Always reply inline** on the specific comment thread. Never post a summary comment on the PR conversation.\n- Use the review API to create inline comments on the exact lines being discussed.\n- For each comment: acknowledge, state what was fixed, and reference the commit SHA.\n\n## Return format\n\nReport exactly:\n\n- `PR_NUMBER: <number>`\n- `PR_URL: <url>`\n- `BRANCH: <branch-name>`\n- `SUMMARY: <one-line summary>`\n"},"lastSynced":"2026-03-06T06:33:00.034Z","agentAnalysis":{"suitability":{"en":"Ideal for Collaborative Development Agents requiring standardized pull request formatting and git workflow automation.","zh":"适合需要标准化拉取请求格式和 git 工作流自动化的协作开发代理。","ja":"標準化されたプルリクエストのフォーマットと Git ワークフローの自動化を必要とするコラボレーション開発エージェントに最適です。","ko":"표준화된 풀 리퀘스트 형식 및 깃 워크플로 자동화를 필요로 하는 협업 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo Colaborativo que requieren un formato de solicitud de extracción estandarizado y automatización de flujo de trabajo de git.","fr":"Idéal pour les Agents de Développement Collaboratif nécessitant un format de demande d''extraction standardisé et une automatisation du workflow git.","de":"Ideal für Collaborative Development Agents, die ein standardisiertes Pull-Request-Format und eine Automatisierung des Git-Workflows erfordern.","pt":"Ideal para Agentes de Desenvolvimento Colaborativo que exigem formatação de solicitação de pull padrão e automação de fluxo de trabalho do git.","ru":"Идеально подходит для агентов совместной разработки, требующих стандартной форматировки запросов на принятие и автоматизации рабочего процесса git.","ar":"مثالي لعميل التطوير التعاوني الذي يتطلب تنسيق طلبات السحب المعيارية وتأتماتية تدفق العمل git."},"recommendation":{"en":"Empowers agents to create properly formatted pull requests with adherence to conventions outlined in CONTRIBUTING.md, utilizing git commands and regex patterns for consistency, and referencing type lists and label mappings from .claude/c for accuracy.","zh":"赋予代理创建符合 CONTRIBUTING.md 中概述的约定、利用 git 命令和正则表达式模式以保证一致性、并引用 .claude/c 中的类型列表和标签映射以保证准确性的格式化拉取请求的能力。","ja":"CONTRIBUTING.md に概説された規約に準拠した、フォーマットされたプルリクエストを作成するエージェントを可能にし、Git コマンドと正規表現パターンを使用して一貫性を保ち、.claude/c のタイプリストとラベルマッピングを参照して正確性を確保します。","ko":"CONTRIBUTING.md에概説된규약을준수하는형식화된풀리퀘스트를생성할수있는에이전트를활성화하고깃명령어와정규식패턴을사용하여일관성을보장하며.claude/c의타입리스트와레이블매핑을참조하여정확성을보장합니다.","es":"Habilita a los agentes a crear solicitudes de extracción debidamente formateadas con adherencia a las convenciones descritas en CONTRIBUTING.md, utilizando comandos git y patrones de regex para la consistencia, y haciendo referencia a listas de tipos y asignaciones de etiquetas de .claude/c para precisión.","fr":"Permet aux agents de créer des demandes d''extraction correctement formatées avec une adhérence aux conventions décrites dans CONTRIBUTING.md, en utilisant des commandes git et des modèles de regex pour la cohérence, et en référençant des listes de types et des mappages d''étiquettes de .claude/c pour l''exactitude.","de":"Ermächtigt Agents, ordnungsgemäß formatierte Pull-Requests mit Einhaltung der in CONTRIBUTING.md beschriebenen Konventionen zu erstellen, indem Git-Befehle und Regex-Muster für Konsistenz verwendet werden und auf Typlisten und Label-Zuordnungen von .claude/c für Genauigkeit verwiesen wird.","pt":"Habilita os agentes a criar solicitações de pull com formatação adequada, seguindo as convenções delineadas em CONTRIBUTING.md, utilizando comandos git e padrões de regex para consistência, e fazendo referência a listas de tipo e mapeamentos de rótulos de .claude/c para precisão.","ru":"Наделяет агентов возможностью создавать правильно отформатированные запросы на принятие, соблюдая соглашения, изложенные в CONTRIBUTING.md, используя команды git и шаблоны regex для последовательности, и ссылаясь на списки типов и сопоставления меток из .claude/c для точности.","ar":"تمكّن الوكلاء من إنشاء طلبات سحب مع تنسيق مناسب مع اتباع الاتفاقيات المحددة في CONTRIBUTING.md، واستخدام أوامر جيت وأنماط regex للاتساق، والاطلاع على قوائم النوع وخريطة العلامات من .claude/c للدقة."},"useCases":{"en":["Automating pull request creation with proper title conventions","Generating pull request bodies using template.md for consistency","Validating commit history and branch status before submitting pull requests"],"zh":["使用适当的标题约定自动创建拉取请求","使用 template.md 生成一致的拉取请求正文","在提交拉取请求之前验证提交历史记录和分支状态"],"ja":["適切なタイトル規約を使用してプルリクエストを自動的に作成する","template.md を使用して一貫性のあるプルリクエスト本文を生成する","プルリクエストを提出する前にコミット履歴とブランチステータスを検証する"],"ko":["적절한 제목 규칙을 사용하여 풀 리퀘스트를 자동으로 생성합니다","템플릿.md를 사용하여 일관된 풀 리퀘스트 본문을 생성합니다","풀 리퀘스트를 제출하기 전에 커밋 기록 및 브랜치 상태를 검증합니다"],"es":["Automatizar la creación de solicitudes de extracción con convenciones de título adecuadas","Generar cuerpos de solicitudes de extracción utilizando template.md para la consistencia","Validar el historial de confirmaciones y el estado de la rama antes de enviar solicitudes de extracción"],"fr":["Automatiser la création de demandes d''extraction avec des conventions de titre appropriées","Générer des corps de demandes d''extraction en utilisant template.md pour la cohérence","Valider l''historique des validations et l''état de la branche avant d''envoyer des demandes d''extraction"],"de":["Automatisieren der Erstellung von Pull-Requests mit geeigneten Titelkonventionen","Erzeugen von Pull-Request-Texten unter Verwendung von template.md für Konsistenz","Überprüfen des Commit-Verlaufs und des Branch-Status vor dem Senden von Pull-Requests"],"pt":["Automatizar a criação de solicitações de pull com convenções de título apropriadas","Gerar corpos de solicitações de pull usando template.md para consistência","Validar o histórico de confirmação e o status da branch antes de enviar solicitações de pull"],"ru":["Автоматизировать создание запросов на принятие с правильными соглашениями названий","Генерировать тела запросов на принятие, используя template.md для последовательности","Проверять историю фиксации и статус ветки перед отправкой запросов на принятие"],"ar":["تأتمتة إنشاء طلبات السحب مع اتفاقيات أسماء العناوين المناسبة","توليد أجساد طلبات السحب باستخدام template.md للاتساق","التحقق من سجل الإصدار والتحقق من حالة الفرع قبل إرسال طلبات السحب"]},"limitations":{"en":["Requires git repository access","Dependent on .claude/c for type lists, regex patterns, and label mappings","Must adhere to specific formatting guidelines outlined in CONTRIBUTING.md and template.md"],"zh":["需要 git 仓库访问权限","依赖 .claude/c 中的类型列表、正则表达式模式和标签映射","必须遵守 CONTRIBUTING.md 和 template.md 中概述的特定格式化指南"],"ja":["Git リポジトリへのアクセス権が必要",".claude/c のタイプリスト、正規表現パターン、およびラベルマッピングに依存","CONTRIBUTING.md および template.md に概説された特定のフォーマットガイドラインに従う必要がある"],"ko":["깃 리포지토리 액세스 권한이 필요합니다",".claude/c의 타입 목록, 정규식 패턴 및 레이블 매핑에 의존합니다","CONTRIBUTING.md 및 템플릿.md에概説된 특정 형식화 지침을 준수해야 합니다"],"es":["Requiere acceso al repositorio git","Dependiente de .claude/c para listas de tipos, patrones de regex y asignaciones de etiquetas","Debe adherirse a las pautas de formato específicas descritas en CONTRIBUTING.md y template.md"],"fr":["Nécessite un accès au référentiel git","Dépendant de .claude/c pour les listes de types, les modèles de regex et les mappages d''étiquettes","Doit respecter les directives de formatage spécifiques décrites dans CONTRIBUTING.md et template.md"],"de":["Benötigt Zugriff auf das Git-Repository","Abhängig von .claude/c für Typlisten, Regex-Muster und Label-Zuordnungen","Muss den spezifischen Formatrichtlinien entsprechen, die in CONTRIBUTING.md und template.md beschrieben sind"],"pt":["Exige acesso ao repositório git","Depende de .claude/c para listas de tipo, padrões de regex e mapeamentos de rótulos","Deve aderir a diretrizes de formatação específicas delineadas em CONTRIBUTING.md e template.md"],"ru":["Требует доступа к репозиторию git","Зависит от .claude/c для списков типов, шаблонов regex и сопоставлений меток","Должен следовать конкретным рекомендациям по форматированию, изложенным в CONTRIBUTING.md и template.md"],"ar":["يتطلب الوصول إلى مستودع جيت","يعتمد على .claude/c لقوائم النوع وأنماط regex وخريطة العلامات","يجب اتباع إرشادات التنسيق المحددة الموجودة في CONTRIBUTING.md وtemplate.md"]},"version":4},"contentHash":"908d09b67d35f2de0677ca43ee283a29e18232a82153c5e952f48829bb5d4719","qualityScore":44}');
