INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tile-ai/TileOPs/creating-pull-request', 'creating-pull-request', 'tile-ai', 'TileOPs', 'community', 'creating-pull-request tile-ai TileOPs community The creating-pull-request skill helps developers create pull requests with proper formatting and conventions. It benefits developers working on collaborative projects using git. 创建拉取请求的技术指南，涵盖 Git 和 CLI 的使用 プルリクエストを作成するためのテクニカルガイド。Git と CLI の使用方法を含みます 풀 리퀘스트 생성을 위한 기술 가이드입니다. Git 및 CLI의 사용법을 포함합니다 Crea solicitudes de extracción de manera efectiva con nuestra guía técnica y domina Git y GitHub con AI Agent. Créez des demandes d''extraction de manière efficace avec notre guide technique et maîtrisez Git et GitHub avec les outils AI. Erstellen Sie Pull-Requests effektiv mit unserer technischen Anleitung und beherrschen Sie Git und GitHub mit AI-Tools. Criar pull requests de forma eficiente usando comandos Git e seguindo convenções de título e formato de corpo Создание pull request эффективно с помощью команд Git и соблюдение конвенций названия и формата тела إنشاء طلبات السحب بفعالية باستخدام أوامر Git ومتابعة اتفاقيات العنوان وتنسيق الجسم how to create a pull request creating-pull-request setup guide git pull request conventions collaborative coding best practices creating-pull-request vs git flow install creating-pull-request creating-pull-request alternative what is creating-pull-request creating-pull-request tutorial 创建拉取请求 Git 命令 CLI 工具 仓库管理 分支管理 提交日志 PR 标题格式 AIエージェント工具 Displays current repository state using gh repo view and git branch commands Shows commits on the current branch using git log Provides remote repository information using git remote Follows PR title conventions outlined in docs/CONTRIBUTING.md Uses template.md for PR body format References .claude/c for type lists, regex patterns, and label mappings creating-pull-request is a skill that automates the process of creating pull requests using git commands and following specific conventions');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Matt-Aurora-Ventures/Jarvis/verification-before-completion', 'community', 'Matt-Aurora-Ventures', 'Jarvis', 'Matt-Aurora-Ventures/Jarvis', 'verification-before-completion', 55, 5, 44, '2026-03-01T02:56:32Z', '2026-03-06T06:35:28.075Z', 'ea52d15aabaf72bc6b558efe2c126f161b53961090ddcd712000273bfe8c7b6c', '{"id":"Matt-Aurora-Ventures/Jarvis/verification-before-completion","name":"verification-before-completion","description":{"en":"The verification-before-completion skill ensures accuracy by requiring fresh verification evidence before claiming completion, benefiting developers and AI agents alike","zh":"Verification Before Completion 是一个强调 Evidence before claims 的开发原则，确保代码质量和开发效率。","ja":"Verification Before Completion は、Evidence before claims を重視する開発原則で、コード品質と開発効率を向上させる。","ko":"Verification Before Completion는 Evidence before claims를 강조하는 개발 원칙으로 코드 품질과 개발 효율성을 높입니다.","es":"La verificación antes de la finalización es un principio fundamental para garantizar la integridad del trabajo en proyectos de Agentes de IA","fr":"La vérification avant achèvement est un principe fondamental pour garantir l''intégrité du travail dans les projets d''Outils d''IA","de":"Die Verifizierung vor Abschluss ist ein grundlegendes Prinzip, um die Integrität der Arbeit in KI-Agents-Projekten zu gewährleisten","pt":"A verificação antes de concluir é um princípio fundamental que exige evidência antes de reivindicações, garantindo a integridade do processo","ru":"Верификация перед завершением является основным принципом, требующим доказательств перед заявлениями, гарантирующим целостность процесса","ar":"التحقق قبل الإكمال هو مبدأ أساسي يطلب أدلة قبل المطالبات، مما يضمن سلامة العملية"},"seo":{"title":{"en":"Verification-Before-Completion: Setup Guide for AI Agents","zh":"Verification Before Completion 设置指南 - AI智能代理工具","ja":"Verification Before Completion のベストプラクティス - AIエージェント","ko":"Verification Before Completion 구축 가이드 - AI 에이전트 툴","es":"Guía de configuración de verificación antes de finalizaci...","fr":"Guide de mise en oeuvre de la vérification avant achèveme...","de":"Einrichtungsleitfaden für Verifizierung vor Abschluss für...","pt":"Guia de Configuração de Verificação Antes de Conclusão pa...","ru":"Руководство по настройке верификации перед завершением дл...","ar":"دليل إعداد التحقق قبل الإكمال لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient verification with our AI agent skill. Learn how to implement the iron law and gate function for reliable completion claims","zh":"了解 Verification Before Completion 的核心原则和铁律，提高代码质量和开发效率 - AI智能代理工具","ja":"Verification Before Completion の鉄律とコアプリンシプルを学び、コード品質と開発効率を向上させる - AIエージェント","ko":"Verification Before Completion의 핵심 원칙과 철법을 익히고 코드 품질 및 개발 효율성을 높여보세요 - AI 에이전트 툴","es":"Aprende a implementar la verificación antes de la finalización en tus proyectos de Agentes de IA para asegurar la integridad del trabajo","fr":"Découvrez comment mettre en oeuvre la vérification avant achèvement dans vos projets d''Outils d''IA pour garantir l''intégrité du travail","de":"Erfahren Sie, wie Sie die Verifizierung vor Abschluss in Ihren KI-Agents-Projekten implementieren, um die Integrität der Arbeit zu gewährleisten","pt":"Aprenda a implementar a verificação antes de concluir com o princípio de evidência antes de reivindicações, sempre","ru":"Узнайте, как реализовать верификацию перед завершением с принципом доказательств перед заявлениями","ar":"تعرف على كيفية تنفيذ التحقق قبل الإكمال مع مبدأ الأدلة قبل المطالبات"},"definition":{"en":"Verification-before-completion is a principle that mandates evidence before claims, always, to prevent dishonest completion claims","zh":"Verification Before Completion 是一种开发原则，要求在claim代码完成之前提供验证证据。","ja":"Verification Before Completion は、コードを完成したと主張する前に検証証拠を提供することを要求する開発原則です。","ko":"Verification Before Completion는 코드를 완료했다고 주장하기 전에 검증 증거를 제공하도록 요구하는 개발 원칙입니다.","es":"La verificación antes de la finalización es un proceso que requiere evidencia fresca antes de reclamar la finalización de un trabajo","fr":"La vérification avant achèvement est un processus qui nécessite des preuves fraîches avant de revendiquer l''achèvement d''un travail","de":"Die Verifizierung vor Abschluss ist ein Prozess, der frische Beweise erfordert, bevor die Fertigstellung einer Arbeit beansprucht wird","pt":"Verificação antes de concluir é um princípio que exige a execução de comandos de verificação antes de reivindicar a conclusão","ru":"Верификация перед завершением является принципом, требующим выполнения команд верификации перед заявлением о завершении","ar":"التحقق قبل الإكمال هو مبدأ يطلب تنفيذ أوامر التحقق قبل المطالبة بالإكمال"},"features":{"en":["Enforces the iron law: NO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE","Implements the gate function to verify status before expression","Requires running the verification command for accurate completion claims","Prevents violating the spirit of the verification principle","Ensures evidence-based completion claims for reliable results","Supports adherence to the core principle: Evidence before claims, always"],"zh":["强调 Evidence before claims 的开发原则","确保代码质量和开发效率","提供验证证据以支持代码完成主张","遵循铁律：NO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE","支持 Gate Function 以验证代码状态"],"ja":["Evidence before claims を重視する開発原則","コード品質と開発効率を向上させる","検証証拠を提供してコード完成主張をサポートする","鉄律：NO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE に従う","Gate Function をサポートしてコード状態を検証する"],"ko":["Evidence before claims를 강조하는 개발 원칙","코드 품질과 개발 효율성을 높임","검증 증거를 제공하여 코드 완료 주장을 지원함","철법：NO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE를 따름","Gate Function을 지원하여 코드 상태를 검증함"],"es":["Requiere evidencia fresca antes de reclamar la finalización","Implementa la función de puerta para garantizar la verificación","Utiliza el comando de verificación para garantizar la integridad del trabajo","Seguimiento del principio de evidencia antes de reclamos","Integración con herramientas de desarrollo como CLI"],"fr":["Nécessite des preuves fraîches avant de revendiquer l''achèvement","Mise en oeuvre de la fonction de porte pour garantir la vérification","Utilisation de la commande de vérification pour garantir l''intégrité du travail","Suivi du principe de preuves avant les réclamations","Intégration avec des outils de développement comme CLI"],"de":["Erfordert frische Beweise, bevor die Fertigstellung beansprucht wird","Implementierung der Gate-Funktion, um die Verifizierung zu gewährleisten","Verwendung des Verifizierungsbefehls, um die Integrität der Arbeit zu gewährleisten","Verfolgung des Prinzips der Beweise vor den Ansprüchen","Integration mit Entwicklungstools wie CLI"],"pt":["Princípio de evidência antes de reivindicações","Execução de comandos de verificação antes de concluir","Garantia de integridade do processo","Prevenção de reivindicações falsas","Integração com CLI para verificação automática"],"ru":["Принцип доказательств перед заявлениями","Выполнение команд верификации перед завершением","Гарантия целостности процесса","Предотвращение ложных заявлений","Интеграция с CLI для автоматической верификации"],"ar":["مبدأ الأدلة قبل المطالبات","تنفيذ أوامر التحقق قبل الإكمال","ضمان سلامة العملية","منع المطالبات الكاذبة","التكامل مع CLI للتحقق التلقائي"]},"keywords":{"en":["how to use verification-before-completion","verification-before-completion setup guide","what is verification-before-completion","verification-before-completion alternative","verification-before-completion vs manual verification","verification-before-completion install","implementation of the iron law","gate function in verification","fresh verification evidence"],"zh":["Verification Before Completion","AI智能代理工具","代码质量","开发效率","Evidence before claims","铁律","Gate Function","代码完成主张","验证证据"],"ja":["Verification Before Completion","AIエージェント","コード品質","開発効率","Evidence before claims","鉄律","Gate Function","コード完成主張","検証証拠"],"ko":["Verification Before Completion","AI 에이전트 툴","코드 품질","개발 효율성","Evidence before claims","철법","Gate Function","코드 완료 주장","검증 증거"],"es":["verificación antes de finalización","Agentes de IA","integridad del trabajo","evidencia fresca","función de puerta","comando de verificación","desarrollo de software","herramientas de desarrollo"],"fr":["vérification avant achèvement","Outils d''IA","intégrité du travail","preuves fraîches","fonction de porte","commande de vérification","développement de logiciels","outils de développement"],"de":["Verifizierung vor Abschluss","KI-Agents","Integrität der Arbeit","frische Beweise","Gate-Funktion","Verifizierungsbefehl","Software-Entwicklung","Entwicklungstools"],"pt":["verificação antes de concluir","ferramentas de ia","princípio de evidência","comandos de verificação","integridade do processo","prevenção de reivindicações falsas","cli para verificação automática"],"ru":["верификация перед завершением","ии агенты","принцип доказательств","команды верификации","целостность процесса","предотвращение ложных заявлений","cli для автоматической верификации"],"ar":["التحقق قبل الإكمال","أدوات الذكاء الاصطناعي","مبدأ الأدلة","أوامر التحقق","سلامة العملية","منع المطالبات الكاذبة","cli للتحقق التلقائي"]}},"owner":"Matt-Aurora-Ventures","repo":"Jarvis","repoPath":"Matt-Aurora-Ventures/Jarvis","stars":55,"forks":5,"updatedAt":"2026-03-01T02:56:32Z","topics":[],"category":"community","skillMd":{"name":"verification-before-completion","description":"Use when about to claim work is complete, fixed, or passing, before committing or creating PRs - requires running verification commands and confirming output before making any success claims; evidence before assertions always","bodyPreview":"# Verification Before Completion\n\n## Overview\n\nClaiming work is complete without verification is dishonesty, not efficiency.\n\n**Core principle:** Evidence before claims, always.\n\n**Violating the letter of this rule is violating the spirit of this rule.**\n\n## The Iron Law\n\n```\nNO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE\n```\n\nIf you haven''t run the verification command in this message, you cannot claim it passes.\n\n## The Gate Function\n\n```\nBEFORE claiming any status or expressing sati","body":"# Verification Before Completion\n\n## Overview\n\nClaiming work is complete without verification is dishonesty, not efficiency.\n\n**Core principle:** Evidence before claims, always.\n\n**Violating the letter of this rule is violating the spirit of this rule.**\n\n## The Iron Law\n\n```\nNO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE\n```\n\nIf you haven''t run the verification command in this message, you cannot claim it passes.\n\n## The Gate Function\n\n```\nBEFORE claiming any status or expressing satisfaction:\n\n1. IDENTIFY: What command proves this claim?\n2. RUN: Execute the FULL command (fresh, complete)\n3. READ: Full output, check exit code, count failures\n4. VERIFY: Does output confirm the claim?\n   - If NO: State actual status with evidence\n   - If YES: State claim WITH evidence\n5. ONLY THEN: Make the claim\n\nSkip any step = lying, not verifying\n```\n\n## Common Failures\n\n| Claim | Requires | Not Sufficient |\n|-------|----------|----------------|\n| Tests pass | Test command output: 0 failures | Previous run, \"should pass\" |\n| Linter clean | Linter output: 0 errors | Partial check, extrapolation |\n| Build succeeds | Build command: exit 0 | Linter passing, logs look good |\n| Bug fixed | Test original symptom: passes | Code changed, assumed fixed |\n| Regression test works | Red-green cycle verified | Test passes once |\n| Agent completed | VCS diff shows changes | Agent reports \"success\" |\n| Requirements met | Line-by-line checklist | Tests passing |\n\n## Red Flags - STOP\n\n- Using \"should\", \"probably\", \"seems to\"\n- Expressing satisfaction before verification (\"Great!\", \"Perfect!\", \"Done!\", etc.)\n- About to commit/push/PR without verification\n- Trusting agent success reports\n- Relying on partial verification\n- Thinking \"just this once\"\n- Tired and wanting work over\n- **ANY wording implying success without having run verification**\n\n## Rationalization Prevention\n\n| Excuse | Reality |\n|--------|---------|\n| \"Should work now\" | RUN the verification |\n| \"I''m confident\" | Confidence ≠ evidence |\n| \"Just this once\" | No exceptions |\n| \"Linter passed\" | Linter ≠ compiler |\n| \"Agent said success\" | Verify independently |\n| \"I''m tired\" | Exhaustion ≠ excuse |\n| \"Partial check is enough\" | Partial proves nothing |\n| \"Different words so rule doesn''t apply\" | Spirit over letter |\n\n## Key Patterns\n\n**Tests:**\n```\n✅ [Run test command] [See: 34/34 pass] \"All tests pass\"\n❌ \"Should pass now\" / \"Looks correct\"\n```\n\n**Regression tests (TDD Red-Green):**\n```\n✅ Write → Run (pass) → Revert fix → Run (MUST FAIL) → Restore → Run (pass)\n❌ \"I''ve written a regression test\" (without red-green verification)\n```\n\n**Build:**\n```\n✅ [Run build] [See: exit 0] \"Build passes\"\n❌ \"Linter passed\" (linter doesn''t check compilation)\n```\n\n**Requirements:**\n```\n✅ Re-read plan → Create checklist → Verify each → Report gaps or completion\n❌ \"Tests pass, phase complete\"\n```\n\n**Agent delegation:**\n```\n✅ Agent reports success → Check VCS diff → Verify changes → Report actual state\n❌ Trust agent report\n```\n\n## Why This Matters\n\nFrom 24 failure memories:\n- your human partner said \"I don''t believe you\" - trust broken\n- Undefined functions shipped - would crash\n- Missing requirements shipped - incomplete features\n- Time wasted on false completion → redirect → rework\n- Violates: \"Honesty is a core value. If you lie, you''ll be replaced.\"\n\n## When To Apply\n\n**ALWAYS before:**\n- ANY variation of success/completion claims\n- ANY expression of satisfaction\n- ANY positive statement about work state\n- Committing, PR creation, task completion\n- Moving to next task\n- Delegating to agents\n\n**Rule applies to:**\n- Exact phrases\n- Paraphrases and synonyms\n- Implications of success\n- ANY communication suggesting completion/correctness\n\n## The Bottom Line\n\n**No shortcuts for verification.**\n\nRun the command. Read the output. THEN claim the result.\n\nThis is non-negotiable.\n"},"lastSynced":"2026-03-06T06:35:28.075Z","agentAnalysis":{"suitability":{"en":"Perfect for Reliability-focused Agents needing rigorous verification and validation protocols","zh":"非常适合需要严格验证和验证协议的可靠性专注的Agent","ja":"信頼性に重点を置くエージェントが、厳格な検証とバリデーションのプロトコルを必要とする場合に最適","ko":"严格한 검증 및 검사 프로토콜이 필요한 신뢰성 중심 에이전트에 적합","es":"Perfecto para agentes enfocados en la confiabilidad que necesitan protocolos rigurosos de verificación y validación","fr":"Parfait pour les agents axés sur la fiabilité nécessitant des protocoles de vérification et de validation rigoureux","de":"Perfekt für zuverlässigkeitsorientierte Agenten, die strenge Verifizierungs- und Validierungsprotokolle benötigen","pt":"Perfeito para Agentes focados em Confiabilidade que necessitam de protocolos rigorosos de verificação e validação","ru":"Идеально для агентов, ориентированных на надежность, которым необходимы строгие протоколы верификации и проверки","ar":"مثالي للوكلاء الذين يركزون على الموثوقية وهم بحاجة إلى بروتوكولات صارمة للتأكيد والتحقق"},"recommendation":{"en":"Empowers agents to ensure accuracy by enforcing the core principle of evidence before claims, utilizing fresh verification evidence and adhering to the Iron Law of NO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE, thereby enhancing reliability and trustworthiness through strict gate functions","zh":"赋予代理人通过执行证据优先于声明的核心原则、利用新鲜的验证证据并遵守无新鲜验证证据不做声明的铁律，从而通过严格的门控函数增强可靠性和可信度","ja":"エージェントに、主張の前の証拠というコアの原則を適用し、新鮮な検証証拠を利用し、証拠なしには主張しないという鉄の法則に従うことで、厳格なゲート関数を通じて信頼性と信頼性を高めることを可能にする","ko":"에이전트가 증거를 먼저 확인하고 새로운 검증 증거를 사용하며 신선한 검증 증거 없이 완료 주장을 하지 않는다는 철의 법칙을 지키는 것을 통해 엄격한 게이트 함수를 통하여 신뢰성과 신뢰도를 향상 시킬 수 있도록 함","es":"Habilita a los agentes para garantizar la precisión al aplicar el principio fundamental de evidencia antes de las reclamaciones, utilizando evidencia de verificación fresca y ajustándose a la Ley de Hierro de NO RECLAMACIONES DE FINALIZACIÓN SIN EVIDENCIA DE VERIFICACIÓN FRESCA, lo que mejora la confiabilidad y la confianza a través de funciones de puerta estrictas","fr":"Habilite les agents à garantir l''exactitude en appliquant le principe fondamental de preuve avant les réclamations, en utilisant des preuves de vérification fraîches et en se conformant à la Loi de Fer de PAS DE RÉCLAMATIONS DE COMPLÉTION SANS PREUVES DE VÉRIFICATION FRAÎCHES, ce qui améliore la fiabilité et la confiance à travers des fonctions de portail strictes","de":"Ermächtigt die Agenten, die Genauigkeit zu gewährleisten, indem sie das Kernprinzip der Beweise vor den Ansprüchen durchsetzen, frische Verifizierungsbeweise nutzen und sich an das Eisernes Gesetz von KEINE VOLLSTÄNDIGKEITSANSPRÜCHEN OHNE FRESCHE VERIFIZIERUNGSBEWEISE halten, wodurch die Zuverlässigkeit und Vertrauenswürdigkeit durch strenge Torfunktionen verbessert wird","pt":"Habilita os agentes a garantir a precisão, aplicando o princípio fundamental de evidências antes de reivindicações, utilizando evidências de verificação recente e aderindo à Lei de Ferro de NENHUMA REIVINDICAÇÃO DE CONCLUSÃO SEM EVIDÊNCIA DE VERIFICAÇÃO RECENTE, melhorando assim a confiabilidade e a credibilidade por meio de funções de porta rigorosas","ru":"Наделяет агентов возможностью обеспечить точность, соблюдая основной принцип доказательств до заявлений, используя свежие доказательства верификации и придерживаясь Железного закона НЕТ ЗАЯВЛЕНИЙ О ЗАВЕРШЕНИИ БЕЗ СВЕЖИХ ДОКАЗАТЕЛЬСТВ ВЕРИФИКАЦИИ, тем самым повышая надежность и достоверность посредством строгих функций шлюза","ar":"يمنح الوكلاء القدرة على ضمان الدقة من خلال تطبيق المبدأ الأساسي للأدلة قبل المطالبات، باستخدام أدلة التحقق الطازجة والامتثال لقانون الحديد لا مطالبات إكمال بدون أدلة تحقق طازجة، وبالتالي تعزيز الموثوقية والموثوقية من خلال وظائف البوابة الصارمة"},"useCases":{"en":["Enforcing strict verification protocols for task completion","Validating claims with fresh evidence","Preventing premature completion claims"],"zh":["执行任务完成的严格验证协议","用新鲜证据验证声明","防止过早的完成声明"],"ja":["タスク完了のための厳格な検証プロトコルを適用する","新鮮な証拠を用いて主張を検証する","早期の完了主張を防止する"],"ko":["작업 완료를 위한 엄격한 검증 프로토콜 적용","신선한 증거를 사용하여 주장을 검증","조기 완료 주장을 방지"],"es":["Aplicar protocolos de verificación estrictos para la finalización de tareas","Validar reclamaciones con evidencia fresca","Prevenir reclamaciones de finalización prematuras"],"fr":["Mettre en œuvre des protocoles de vérification stricts pour l''achèvement des tâches","Valider les réclamations avec des preuves fraîches","Prévenir les réclamations de complétion prématurées"],"de":["Strenge Verifizierungsprotokolle für die Aufgabenabgeschlossenheit durchsetzen","Ansprüche mit frischen Beweisen überprüfen","Vorzeitige Vollendungsansprüche verhindern"],"pt":["Aplicar protocolos de verificação rigorosos para conclusão de tarefas","Validar reivindicações com evidências recentes","Prevenir reivindicações de conclusão prematuras"],"ru":["Применять строгие протоколы верификации для завершения задач","Проверять заявления со свежими доказательствами","Предотвращать преждевременные заявления о завершении"],"ar":["تطبيق بروتوكولات التحقق الصارمة لإكمال المهام","التحقق من المطالبات بالأدلة الطازجة","منع مطالبات الإكمال المسبق"]},"limitations":{"en":["Requires implementation of the Iron Law","Mandatory fresh verification evidence for all claims","Strict adherence to the gate function protocol"],"zh":["需要实施铁律","所有声明都需要新鲜的验证证据","严格遵守门控函数协议"],"ja":["鉄の法則の実装が必要","すべての主張に対して新鮮な検証証拠が必要","ゲート関数プロトコルの厳格な遵守"],"ko":["철의 법칙을 구현해야 함","모든 주장에 대해서 신선한 검증 증거가 필요","게이트 함수 프로토콜을 엄격히 지켜야 함"],"es":["Requiere la implementación de la Ley de Hierro","Evidencia de verificación fresca obligatoria para todas las reclamaciones","Estricta adhesión al protocolo de función de puerta"],"fr":["Nécessite la mise en œuvre de la Loi de Fer","Preuves de vérification fraîches obligatoires pour toutes les réclamations","Conformité stricte au protocole de fonction de portail"],"de":["Erfordert die Umsetzung des Eisernen Gesetzes","Frische Verifizierungsbeweise für alle Ansprüche obligatorisch","Strenges Befolgen des Torfunktionprotokolls"],"pt":["Exige implementação da Lei de Ferro","Evidência de verificação recente obrigatória para todas as reivindicações","Adesão estrita ao protocolo de função de porta"],"ru":["Требует реализации Железного закона","Обязательные свежие доказательства верификации для всех заявлений","Строгое соблюдение протокола функции шлюза"],"ar":["يتطلب تنفيذ قانون الحديد","أدلة تحقق طازجة مطلوبة لجميع المطالبات","الامتثال الصارم لبروتوكول وظيفة البوابة"]},"version":4},"contentHash":"ea52d15aabaf72bc6b558efe2c126f161b53961090ddcd712000273bfe8c7b6c","qualityScore":44}');
