INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Matt-Aurora-Ventures/Jarvis/verification-before-completion', 'verification-before-completion', 'Matt-Aurora-Ventures', 'Jarvis', 'community', 'verification-before-completion Matt-Aurora-Ventures Jarvis community The verification-before-completion skill ensures accuracy by requiring fresh verification evidence before claiming completion, benefiting developers and AI agents alike Verification Before Completion 是一个强调 Evidence before claims 的开发原则，确保代码质量和开发效率。 Verification Before Completion は、Evidence before claims を重視する開発原則で、コード品質と開発効率を向上させる。 Verification Before Completion는 Evidence before claims를 강조하는 개발 원칙으로 코드 품질과 개발 효율성을 높입니다. La verificación antes de la finalización es un principio fundamental para garantizar la integridad del trabajo en proyectos de Agentes de IA La vérification avant achèvement est un principe fondamental pour garantir l''intégrité du travail dans les projets d''Outils d''IA Die Verifizierung vor Abschluss ist ein grundlegendes Prinzip, um die Integrität der Arbeit in KI-Agents-Projekten zu gewährleisten A verificação antes de concluir é um princípio fundamental que exige evidência antes de reivindicações, garantindo a integridade do processo Верификация перед завершением является основным принципом, требующим доказательств перед заявлениями, гарантирующим целостность процесса التحقق قبل الإكمال هو مبدأ أساسي يطلب أدلة قبل المطالبات، مما يضمن سلامة العملية how to use verification-before-completion verification-before-completion setup guide what is verification-before-completion verification-before-completion alternative verification-before-completion vs manual verification verification-before-completion install implementation of the iron law gate function in verification fresh verification evidence Verification Before Completion AI智能代理工具 代码质量 开发效率 Evidence before claims 铁律 Gate Function 代码完成主张 验证证据 Enforces the iron law: NO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE Implements the gate function to verify status before expression Requires running the verification command for accurate completion claims Prevents violating the spirit of the verification principle Ensures evidence-based completion claims for reliable results Supports adherence to the core principle: Evidence before claims, always Verification-before-completion is a principle that mandates evidence before claims, always, to prevent dishonest completion claims');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rwjdk/AgentFrameworkToolkit/create-agent-provider', 'community', 'rwjdk', 'AgentFrameworkToolkit', 'rwjdk/AgentFrameworkToolkit', 'create-agent-provider', 53, 5, 44, '2026-02-28T20:30:08Z', '2026-03-06T06:35:33.444Z', '1af877d6f124656b51ce905e161daa2e16fccf6f61c29f4ed782ea469fa86efd', '{"id":"rwjdk/AgentFrameworkToolkit/create-agent-provider","name":"create-agent-provider","description":{"en":"The create-agent-provider skill helps developers create a new Agent Provider NuGet package for the AgentFrameworkToolkit, enabling integration with various LLM services. It benefits developers working with Microsoft Agent Framework.","zh":"Create Agent Provider Skill是一个基于Microsoft Agent Framework的C#工具包，帮助开发者创建新的Agent Provider NuGet包","ja":"Create Agent Provider SkillはMicrosoft Agent Frameworkを基盤としたC# Toolkitで、開発者が新しいAgent Provider NuGetパッケージを作成することを支援します","ko":"Create Agent Provider Skill은 Microsoft Agent Framework를 기반으로 하는 C# 툴킷으로, 개발자가 새로운 에이전트 공급자 NuGet 패키지를 생성하는 것을 지원합니다","es":"El kit de herramientas create-agent-provider facilita la creación de proveedores de agentes para el AgentFrameworkToolkit, permitiendo la integración con servicios LLM como OpenAI","fr":"Le kit d''outils create-agent-provider facilite la création de fournisseurs d''agents pour le AgentFrameworkToolkit, permettant l''intégration avec des services LLM tels que OpenAI","de":"Das create-agent-provider-Toolkit erleichtert die Erstellung von Agenten-Anbietern für das AgentFrameworkToolkit, ermöglicht die Integration mit LLM-Diensten wie OpenAI","pt":"O Create Agent Provider é uma ferramenta em C# que facilita a criação de provedores de agente para o AgentFrameworkToolkit, permitindo a integração com diferentes serviços de LLM","ru":"Create Agent Provider - это инструмент на C#, который упрощает создание провайдеров агентов для AgentFrameworkToolkit, позволяя интегрироваться с различными сервисами LLM","ar":"Create Agent Provider هو أداة باللغة C# تسهل إنشاء مزودي وكلاء ل AgentFrameworkToolkit، مما يسمح بالتكامل مع خدمات LLM المختلفة"},"seo":{"title":{"en":"create-agent-provider: Setup Guide for AI Agents | AI Age...","zh":"AI工具创建代理提供者设置指南","ja":"AIエージェントのCreate Agent Providerセットアップガイド","ko":"AI 에이전트 생성 공급자 설정 가이드","es":"Guía de Configuración de create-agent-provider para Agent...","fr":"Guide de Mise en Place de create-agent-provider pour les ...","de":"Einrichtungsanleitung für create-agent-provider für KI-Ag...","pt":"Guia de Configuração do Create Agent Provider para Ferram...","ru":"Настройка Create Agent Provider для ИИ Агентов","ar":"دليل إعداد Create Agent Provider لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create a new Agent Provider NuGet package with create-agent-provider and integrate with LLM services like Anthropic and OpenAI. Get started now!","zh":"使用Create Agent Provider Skill创建新的Agent Provider NuGet包，实现LLM服务集成","ja":"Create Agent Provider Skillを使用して新しいAgent Provider NuGetパッケージを作成し、LLMサービスを統合する","ko":"Create Agent Provider Skill을 사용하여 새로운 에이전트 공급자 NuGet 패키지를 생성하고 LLM 서비스를 통합합니다","es":"Aprende a crear un proveedor de agentes para el AgentFrameworkToolkit con create-agent-provider y aprovecha las API de LLM de OpenAI y otros","fr":"Découvrez comment créer un fournisseur d''agents pour le AgentFrameworkToolkit avec create-agent-provider et profitez des API LLM d''OpenAI et d''autres","de":"Erfahren Sie, wie Sie einen Agenten-Anbieter für das AgentFrameworkToolkit mit create-agent-provider erstellen und die OpenAI- und andere LLM-APIs nutzen","pt":"Aprenda a criar um pacote NuGet de provedor de agente para o AgentFrameworkToolkit com este guia passo a passo","ru":"Узнайте, как создать пакет NuGet провайдера агента для AgentFrameworkToolkit с помощью этого пошагового руководства","ar":"تعرف على كيفية إنشاء حزمة NuGet لمزود وكيل ل AgentFrameworkToolkit باستخدام هذا الدليل الخطوة بخطوة"},"definition":{"en":"create-agent-provider is a C# Toolkit that simplifies the creation of Agent Provider NuGet packages for the AgentFrameworkToolkit, supporting integration with multiple LLM services.","zh":"Create Agent Provider Skill是一种帮助开发者创建新的Agent Provider NuGet包的C#工具包","ja":"Create Agent Provider Skillは新しいAgent Provider NuGetパッケージを作成するために開発者を支援するC# Toolkitです","ko":"Create Agent Provider Skill은 새로운 에이전트 공급자 NuGet 패키지를 생성하는 것을 지원하는 C# 툴킷입니다","es":"create-agent-provider es un kit de herramientas de C# para el AgentFrameworkToolkit que permite la creación de proveedores de agentes para servicios de LLM","fr":"create-agent-provider est un kit d''outils C# pour le AgentFrameworkToolkit qui permet la création de fournisseurs d''agents pour les services LLM","de":"create-agent-provider ist ein C#-Toolkit für das AgentFrameworkToolkit, das die Erstellung von Agenten-Anbietern für LLM-Dienste ermöglicht","pt":"O Create Agent Provider é uma ferramenta de código aberto em C# que permite criar provedores de agente para o AgentFrameworkToolkit","ru":"Create Agent Provider - это открытое решение на C#, которое позволяет создавать провайдеров агентов для AgentFrameworkToolkit","ar":"Create Agent Provider هو أداة مفتوحة المصدر باللغة C# تتيح إنشاء مزودي وكلاء ل AgentFrameworkToolkit"},"features":{"en":["Supports OpenAI-compatible API for seamless integration with services like OpenRouter and Cohere","Enables creation of Agent Provider NuGet packages for the AgentFrameworkToolkit","Allows integration with different LLM services, including Anthropic and Google","Provides an OpenAI-Compatible Template for easy implementation","Facilitates the development of custom Agent Providers for specific LLM services"],"zh":["支持OpenAI兼容API的LLM服务集成","提供OpenAI-Compatible Template","支持创建新的Agent Provider NuGet包","基于Microsoft Agent Framework","使用C#开发","集成多个LLM服务（例如Anthropic、OpenAI、Google、Mistral）"],"ja":["OpenAI互換APIのLLMサービス統合をサポート","OpenAI-Compatible Templateを提供","新しいAgent Provider NuGetパッケージの作成をサポート","Microsoft Agent Frameworkを基盤としている","C#で開発","複数のLLMサービス（例：Anthropic、OpenAI、Google、Mistral）を統合"],"ko":["OpenAI 호환 API의 LLM 서비스 통합을 지원","OpenAI-Compatible Template을 제공","新的 에이전트 공급자 NuGet 패키지의 생성을 지원","Microsoft Agent Framework를 기반으로 함","C#로 개발","여러개의 LLM 서비스（예：Anthropic、OpenAI、Google、Mistral）를 통합"],"es":["Compatibilidad con API de OpenAI","Soporte para servicios LLM como Anthropic y Google","Creación de proveedores de agentes para el AgentFrameworkToolkit","Implementación de plantillas para proveedores de OpenAI","Integración con el AgentFrameworkToolkit"],"fr":["Compatibilité avec l''API OpenAI","Prise en charge des services LLM tels qu''Anthropic et Google","Création de fournisseurs d''agents pour le AgentFrameworkToolkit","Mise en œuvre de modèles pour les fournisseurs OpenAI","Intégration avec le AgentFrameworkToolkit"],"de":["Kompatibilität mit der OpenAI-API","Unterstützung für LLM-Dienste wie Anthropic und Google","Erstellung von Agenten-Anbietern für das AgentFrameworkToolkit","Implementierung von Vorlagen für OpenAI-Anbieter","Integration mit dem AgentFrameworkToolkit"],"pt":["Criação de pacotes NuGet de provedor de agente","Integração com serviços de LLM como OpenAI e Anthropic","Compatibilidade com a API do OpenAI","Modelo de template para provedores compatíveis com OpenAI","Suporte ao AgentFrameworkToolkit"],"ru":["Создание пакетов NuGet провайдера агента","Интеграция с сервисами LLM, такими как OpenAI и Anthropic","Совместимость с API OpenAI","Шаблон для провайдеров, совместимых с OpenAI","Поддержка AgentFrameworkToolkit"],"ar":["إنشاء حزم NuGet لمزود وكيل","التكامل مع خدمات LLM مثل OpenAI و Anthropic","التوافق مع واجهة برمجة التطبيقات OpenAI","قالب لمزودي وكلاء متوافقي مع OpenAI","دعم AgentFrameworkToolkit"]},"keywords":{"en":["how to use create-agent-provider","create-agent-provider setup guide","create-agent-provider alternative","create-agent-provider vs Microsoft Agent Framework","what is create-agent-provider","create-agent-provider install","AgentFrameworkToolkit integration","LLM service integration","OpenAI-compatible API"],"zh":["Create Agent Provider Skill","AI工具","Microsoft Agent Framework","C#","LLM服务","OpenAI兼容API","Agent Provider NuGet包","AI开发","AI集成"],"ja":["Create Agent Provider Skill","AIエージェント","Microsoft Agent Framework","C#","LLMサービス","OpenAI互換API","Agent Provider NuGetパッケージ","AI開発","AI統合"],"ko":["Create Agent Provider Skill","AI 에이전트","Microsoft Agent Framework","C#","LLM 서비스","OpenAI 호환 API","에이전트 공급자 NuGet 패키지","AI 개발","AI 통합"],"es":["create-agent-provider","AgentFrameworkToolkit","OpenAI","LLM","proveedores de agentes","integración con servicios de LLM","desarrollo de agentes de IA","herramientas de C# para IA","Guía de configuración de create-agent-provider"],"fr":["create-agent-provider","AgentFrameworkToolkit","OpenAI","LLM","fournisseurs d''agents","intégration avec les services LLM","développement d''outils d''IA","outils C# pour l''IA","Guide de mise en place de create-agent-provider"],"de":["create-agent-provider","AgentFrameworkToolkit","OpenAI","LLM","Agenten-Anbieter","Integration mit LLM-Diensten","Entwicklung von KI-Agents","C#-Tools für KI","Einrichtungsanleitung für create-agent-provider"],"pt":["create agent provider","ferramentas de ia","agentframeworktoolkit","provedor de agente","nuget","openai","anthropic","llm","c#","desenvolvimento de software"],"ru":["create agent provider","ии агенты","agentframeworktoolkit","провайдер агента","nuget","openai","anthropic","llm","c#","разработка программного обеспечения"],"ar":["create agent provider","أدوات الذكاء الاصطناعي","agentframeworktoolkit","مزود وكيل","nuget","openai","anthropic","llm","c#","تطوير البرمجيات"]}},"owner":"rwjdk","repo":"AgentFrameworkToolkit","repoPath":"rwjdk/AgentFrameworkToolkit","stars":53,"forks":5,"updatedAt":"2026-02-28T20:30:08Z","topics":["microsoft-agent-framework"],"category":"community","skillMd":{"name":"create-agent-provider","description":"Instructions for creating a new Agent Provider NuGet package for AgentFrameworkToolkit","bodyPreview":"# Create Agent Provider Package\n\nThis skill guides you through creating a new Agent Provider NuGet package for the AgentFrameworkToolkit. Agent Providers enable integration with different LLM services (e.g., Anthropic, OpenAI, Google, Mistral).\n\n## Quick Decision Guide\n\n**Choose implementation approach:**\n\n1. **OpenAI-Compatible Provider** - If the LLM service has an OpenAI-compatible API:\n   - Examples: OpenRouter, XAI (Grok), Cohere\n   - See: [OpenAI-Compatible Template](references/OpenAICompa","body":"# Create Agent Provider Package\n\nThis skill guides you through creating a new Agent Provider NuGet package for the AgentFrameworkToolkit. Agent Providers enable integration with different LLM services (e.g., Anthropic, OpenAI, Google, Mistral).\n\n## Quick Decision Guide\n\n**Choose implementation approach:**\n\n1. **OpenAI-Compatible Provider** - If the LLM service has an OpenAI-compatible API:\n   - Examples: OpenRouter, XAI (Grok), Cohere\n   - See: [OpenAI-Compatible Template](references/OpenAICompatibleTemplate.md)\n   - Faster implementation (reuses existing OpenAI code)\n\n2. **Custom Provider** - If the LLM service has a unique API:\n   - Examples: Anthropic (Claude), Google (Gemini), GitHub Models, Mistral\n   - See: [Custom Provider Template](references/CustomProviderTemplate.md)\n   - Full control, follows standard patterns\n\n## Core Provider Components\n\nMost provider packages include these components (OpenAI-compatible providers reuse `AgentFrameworkToolkit.OpenAI.AgentOptions`):\n\n### 1. Connection Class (`<Provider>Connection`)\n- Manages API credentials and configuration\n- Creates and configures the SDK client\n- Supports network timeout and custom endpoints (if applicable)\n- Provides raw HTTP call inspection hooks (if possible)\n\n### 2. Agent Factory (`<Provider>AgentFactory`)\n- Creates agent instances from options (or from simplified overloads)\n- Builds the inner `ChatClientAgent` (custom providers)\n- Applies middleware via `AgentFrameworkToolkit.MiddlewareHelper`\n\n### 3. Agent Options (`<Provider>AgentOptions`) (custom providers only)\n- Configuration for agent creation (model, instructions, tools, max tokens, etc.)\n- Provider-specific settings (e.g., thinking budget)\n- Middleware configuration (raw HTTP/tool inspection, tool-calling middleware, OpenTelemetry, logging)\n\n### 4. Agent Wrapper (`<Provider>Agent`)\n- Inherits from `AIAgent`\n- Delegates to an inner agent instance\n- Exposes an `InnerAgent` property\n\n### 5. Chat Models Constants (`<Provider>ChatModels`) (only if provider is specific. if it offers multiple LLMs don''t include such)\n- Constants for available model IDs\n- Makes model selection discoverable\n\n## Implementation Steps\n\n### Step 1: Project Setup\n\n```bash\nmkdir src/AgentFrameworkToolkit.<Provider>\n```\n\n**Important repo conventions (don’t fight the build system):**\n- `src/*` projects inherit defaults from `Directory.Build.props` (currently `net8.0`).\n- NuGet packaging defaults are imported via `nuget-package.props` in each `src/*` `.csproj`.\n- Central package versions are in `Directory.Packages.props` (no versions in `.csproj`).\n\n### Step 2: Implement Core Components\n\nFollow existing providers:\n- **OpenAI-compatible**: `src/AgentFrameworkToolkit.OpenRouter/`, `src/AgentFrameworkToolkit.XAI/`, `src/AgentFrameworkToolkit.Cohere/`\n- **Custom**: `src/AgentFrameworkToolkit.Anthropic/`, `src/AgentFrameworkToolkit.GitHub/`, `src/AgentFrameworkToolkit.Google/`, `src/AgentFrameworkToolkit.Mistral/`\n\n### Step 3: Add Service Extensions\n\nCreate `ServiceCollectionExtensions.cs` for dependency injection using the repo naming convention:\n- `Add<Provider>AgentFactory(this IServiceCollection services, string apiKey)`\n- `Add<Provider>AgentFactory(this IServiceCollection services, <Provider>Connection connection)`\n\n### Step 4: Write Tests (Integration Tests)\n\nProvider tests live in `development/Tests/` and make real API calls.\nSee [Testing Guide](references/TestingGuide.md) for the repo’s concrete pattern.\n\n**Quick checklist:**\n1. Add provider project references:\n   - `development/Tests/Tests.csproj`\n   - `development/Sandbox/Sandbox.csproj`\n2. Add provider to the shared test harness:\n   - Add a value to `AgentProvider` enum in `development/Tests/TestBase.cs`\n   - Add a `case` to `GetAgentForScenarioAsync(...)` in `development/Tests/TestBase.cs`\n3. Create `development/Tests/<Provider>Tests.cs`:\n   - Call the shared scenario tests (`SimpleAgentTestsAsync`, `NormalAgentTestsAsync`, etc.)\n   - Add DI tests for `Add<Provider>AgentFactory(...)`\n4. Add a sandbox runner in `development/Sandbox/Providers/<Provider>.cs` and optionally wire it in `development/Sandbox/Program.cs`\n5. Add your API key to user-secrets:\n   - Update `development/Secrets/Secrets.cs` and `development/Secrets/SecretsManager.cs`\n   - Set the secret using `dotnet user-secrets` for the `development/Secrets/Secrets.csproj` project\n\n### Step 5: Repository Integration\n\n1. Add the project to `AgentFrameworkToolkit.slnx` under `/Packages/`\n2. Add any new SDK package versions to `Directory.Packages.props`\n3. Update documentation:\n   - Main `README.md` provider table\n   - Provider-specific `src/AgentFrameworkToolkit.<Provider>/README.md`\n   - `CHANGELOG.md`\n\n### Step 6: Validation\n\n```bash\ndotnet build --configuration Release\n```\n\n## Key Architectural Patterns\n\n### Middleware Configuration (custom providers)\n\nUse the shared helper instead of re-implementing ordering rules:\n- `AgentFrameworkToolkit.MiddlewareHelper.ApplyMiddleware(...)`\n\n### Agent Factory Pattern (custom providers)\n\n```csharp\npublic class <Provider>AgentFactory\n{\n    public <Provider>Connection Connection { get; }\n\n    public <Provider>AgentFactory(string apiKey);\n    public <Provider>AgentFactory(<Provider>Connection connection);\n\n    public <Provider>Agent CreateAgent(<Provider>AgentOptions options)\n    {\n        // 1. Get SDK client from connection\n        // 2. Build IChatClient (or use SDK-provided one)\n        // 3. Create ChatClientAgent\n        // 4. Apply middleware via MiddlewareHelper\n        // 5. Wrap in provider-specific agent\n    }\n}\n```\n\n## Common Pitfalls\n\n1. Missing XML documentation (warnings are errors in this repo)\n2. Putting versions in `.csproj` instead of `Directory.Packages.props`\n3. Forgetting to update `AgentFrameworkToolkit.slnx` and `README.md`\n4. Forgetting to add provider to `development/Tests/TestBase.cs` test harness\n5. Hardcoding API keys instead of using user-secrets (`development/Secrets/SecretsManager.cs`)\n\n## Reference Documentation\n\n- [OpenAI-Compatible Provider Template](references/OpenAICompatibleTemplate.md)\n- [Custom Provider Template](references/CustomProviderTemplate.md)\n- [Unit Testing Guide](references/TestingGuide.md)\n- [Provider Implementation Checklist](references/ProviderChecklist.md)\n"},"lastSynced":"2026-03-06T06:35:33.444Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing seamless integration with various LLM services through the AgentFrameworkToolkit","zh":"适合需要通过 AgentFrameworkToolkit 与各种 LLM 服务实现无缝集成的 AI Agents","ja":"AgentFrameworkToolkit を使用してさまざまな LLM サービスとシームレスに統合する必要がある AI エージェントに適しています","ko":"AgentFrameworkToolkit를 사용하여 다양한 LLM 서비스와 무결점 통합이 필요한 AI 에이전트에 적합합니다","es":"Perfecto para Agentes de IA que necesitan una integración sin problemas con varios servicios LLM a través de AgentFrameworkToolkit","fr":"Parfait pour les agents IA qui nécessitent une intégration transparente avec différents services LLM via AgentFrameworkToolkit","de":"Perfekt für KI-Agents, die eine nahtlose Integration mit verschiedenen LLM-Diensten über das AgentFrameworkToolkit benötigen","pt":"Perfeito para Agentes de IA que precisam de integração sem problemas com vários serviços de LLM por meio do AgentFrameworkToolkit","ru":"Идеально для агентов ИИ, которым требуется бесшовная интеграция с различными сервисами LLM через AgentFrameworkToolkit","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى دمج متوائم مع خدمات LLM المختلفة من خلال AgentFrameworkToolkit"},"recommendation":{"en":"Empowers agents to create a new Agent Provider NuGet package, enabling integration with different LLM services like Anthropic, OpenAI, and Google, using the AgentFrameworkToolkit and supporting OpenAI-compatible APIs","zh":"赋予代理创建新的 Agent Provider NuGet 包的能力，从而可以使用 AgentFrameworkToolkit 和支持 OpenAI 兼容的 API 与不同的 LLM 服务（如 Anthropic、OpenAI 和 Google）集成","ja":"エージェントが新しい Agent Provider NuGet パッケージを作成し、AgentFrameworkToolkit と OpenAI 互換の API を使用して、Anthropic、OpenAI、Google などのさまざまな LLM サービスと統合できるようにします","ko":"에이전트가 새로운 에이전트 제공자 NuGet 패키지를 만들 수 있도록 해주어 AgentFrameworkToolkit와 OpenAI 호환 API를 사용하여 Anthropic, OpenAI, Google 등의 다양한 LLM 서비스와 통합할 수 있습니다","es":"Habilita a los agentes a crear un nuevo paquete de proveedor de agentes NuGet, lo que permite la integración con diferentes servicios LLM como Anthropic, OpenAI y Google, utilizando AgentFrameworkToolkit y compatibles con APIs de OpenAI","fr":"Permet aux agents de créer un nouveau package de fournisseur d''agent NuGet, permettant l''intégration avec différents services LLM comme Anthropic, OpenAI et Google, en utilisant AgentFrameworkToolkit et en prenant en charge les API compatibles OpenAI","de":"Ermöglicht es Agents, ein neues Agent-Provider-NuGet-Paket zu erstellen, wodurch die Integration mit verschiedenen LLM-Diensten wie Anthropic, OpenAI und Google über das AgentFrameworkToolkit und die Unterstützung von OpenAI-kompatiblen APIs ermöglicht wird","pt":"Habilita os agentes a criar um novo pacote do Fornecedor de Agente NuGet, permitindo a integração com diferentes serviços de LLM, como Anthropic, OpenAI e Google, usando o AgentFrameworkToolkit e suportando APIs compatíveis com o OpenAI","ru":"Наделяет агентов возможностью создать новый пакет провайдера агента NuGet, что позволяет интегрироваться с различными сервисами LLM, такими как Anthropic, OpenAI и Google, используя AgentFrameworkToolkit и поддерживая API, совместимые с OpenAI","ar":"يمنح الوكلاء القدرة على إنشاء حزمة جديدة لمقدم الوكيل NuGet، مما يسمح بالدمج مع خدمات LLM المختلفة مثل Anthropic و OpenAI و Google، باستخدام AgentFrameworkToolkit ودعم APIs متوافقة مع OpenAI"},"useCases":{"en":["Creating custom Agent Provider packages for specific LLM services","Integrating OpenAI-compatible LLM services with the AgentFrameworkToolkit","Developing NuGet packages for the AgentFrameworkToolkit to support various LLM services"],"zh":["为特定 LLM 服务创建自定义的 Agent Provider 包","将 OpenAI 兼容的 LLM 服务与 AgentFrameworkToolkit 集成","开发支持各种 LLM 服务的 NuGet 包用于 AgentFrameworkToolkit"],"ja":["特定の LLM サービス用のカスタム Agent Provider パッケージを作成する","OpenAI 互換の LLM サービスを AgentFrameworkToolkit と統合する","AgentFrameworkToolkit 用のさまざまな LLM サービスをサポートする NuGet パッケージを開発する"],"ko":["특정 LLM 서비스를 위한 사용자 정의 에이전트 제공자 패키지를 생성하는 것","OpenAI 호환 LLM 서비스를 AgentFrameworkToolkit와 통합하는 것","AgentFrameworkToolkit 용으로 다양한 LLM 서비스를 지원하는 NuGet 패키지를 개발하는 것"],"es":["Creación de paquetes de proveedores de agentes personalizados para servicios LLM específicos","Integración de servicios LLM compatibles con OpenAI con AgentFrameworkToolkit","Desarrollo de paquetes NuGet para AgentFrameworkToolkit para admitir varios servicios LLM"],"fr":["Création de packages de fournisseurs d''agent personnalisés pour des services LLM spécifiques","Intégration de services LLM compatibles OpenAI avec AgentFrameworkToolkit","Développement de packages NuGet pour AgentFrameworkToolkit pour prendre en charge différents services LLM"],"de":["Erstellung von benutzerdefinierten Agent-Provider-Paketen für bestimmte LLM-Dienste","Integration von OpenAI-kompatiblen LLM-Diensten mit AgentFrameworkToolkit","Entwicklung von NuGet-Paketen für AgentFrameworkToolkit zur Unterstützung verschiedener LLM-Dienste"],"pt":["Criar pacotes personalizados do Fornecedor de Agente para serviços de LLM específicos","Integrar