INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rwjdk/AgentFrameworkToolkit/create-agent-provider', 'create-agent-provider', 'rwjdk', 'AgentFrameworkToolkit', 'community', 'create-agent-provider rwjdk AgentFrameworkToolkit community microsoft-agent-framework The create-agent-provider skill helps developers create a new Agent Provider NuGet package for the AgentFrameworkToolkit, enabling integration with various LLM services. It benefits developers working with Microsoft Agent Framework. Create Agent Provider Skill是一个基于Microsoft Agent Framework的C#工具包，帮助开发者创建新的Agent Provider NuGet包 Create Agent Provider SkillはMicrosoft Agent Frameworkを基盤としたC# Toolkitで、開発者が新しいAgent Provider NuGetパッケージを作成することを支援します Create Agent Provider Skill은 Microsoft Agent Framework를 기반으로 하는 C# 툴킷으로, 개발자가 새로운 에이전트 공급자 NuGet 패키지를 생성하는 것을 지원합니다 El kit de herramientas create-agent-provider facilita la creación de proveedores de agentes para el AgentFrameworkToolkit, permitiendo la integración con servicios LLM como OpenAI Le kit d''outils create-agent-provider facilite la création de fournisseurs d''agents pour le AgentFrameworkToolkit, permettant l''intégration avec des services LLM tels que OpenAI Das create-agent-provider-Toolkit erleichtert die Erstellung von Agenten-Anbietern für das AgentFrameworkToolkit, ermöglicht die Integration mit LLM-Diensten wie OpenAI O Create Agent Provider é uma ferramenta em C# que facilita a criação de provedores de agente para o AgentFrameworkToolkit, permitindo a integração com diferentes serviços de LLM Create Agent Provider - это инструмент на C#, который упрощает создание провайдеров агентов для AgentFrameworkToolkit, позволяя интегрироваться с различными сервисами LLM Create Agent Provider هو أداة باللغة C# تسهل إنشاء مزودي وكلاء ل AgentFrameworkToolkit، مما يسمح بالتكامل مع خدمات LLM المختلفة how to use create-agent-provider create-agent-provider setup guide create-agent-provider alternative create-agent-provider vs Microsoft Agent Framework what is create-agent-provider create-agent-provider install AgentFrameworkToolkit integration LLM service integration OpenAI-compatible API Create Agent Provider Skill AI工具 Microsoft Agent Framework C# LLM服务 OpenAI兼容API Agent Provider NuGet包 AI开发 AI集成 Supports OpenAI-compatible API for seamless integration with services like OpenRouter and Cohere Enables creation of Agent Provider NuGet packages for the AgentFrameworkToolkit Allows integration with different LLM services, including Anthropic and Google Provides an OpenAI-Compatible Template for easy implementation Facilitates the development of custom Agent Providers for specific LLM services create-agent-provider is a C# Toolkit that simplifies the creation of Agent Provider NuGet packages for the AgentFrameworkToolkit, supporting integration with multiple LLM services.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('carere/zaidan/react-to-solid', 'community', 'carere', 'zaidan', 'carere/zaidan', 'react-to-solid', 45, 1, 44, '2026-02-28T23:00:52Z', '2026-03-06T06:36:13.272Z', 'f83de1a085747c5244374214de4d9e76f11b34a535211cc5833259fbbc4bc12d', '{"id":"carere/zaidan/react-to-solid","name":"react-to-solid","description":{"en":"The react-to-solid skill provides a single source of truth for React-to-SolidJS transformations, benefiting AI agents and developers working with Shadcn UI and SolidJS.","zh":"React-to-Solid是一个知识资源，提供React组件到SolidJS的转换规则和映射","ja":"React-to-Solidは知識リソースであり、ReactコンポーネントをSolidJSに変換するルールとマッピングを提供する","ko":"React-to-Solid는 지식 자원으로, React 컴포넌트를 SolidJS로 변환하는 규칙과 매핑을 제공합니다","es":"El conjunto de reglas React-to-Solid proporciona una fuente única de verdad para transformar componentes React en SolidJS","fr":"L''ensemble de règles React-to-Solid fournit une source unique de vérité pour convertir des composants React en SolidJS","de":"Der Satz von Regeln React-to-Solid bietet eine einzige Quelle der Wahrheit für die Umwandlung von React-Komponenten in SolidJS","pt":"O skill react-to-solid fornece regras de transformação para converter componentes React em SolidJS, permitindo a criação de aplicações personalizadas","ru":"Навык react-to-solid предоставляет правила трансформации для преобразования компонентов React в SolidJS, позволяя создавать настраиваемые приложения","ar":"المهارة react-to-solid توفر قواعد التحويل لتحويل مكونات React إلى SolidJS، مما يسمح بإنشاء تطبيقات مخصصة"},"seo":{"title":{"en":"react-to-solid: Transformation Rules for AI Agents | AI A...","zh":"React-to-Solid Setup Guide: Shadcn Registry for SolidJS","ja":"React-to-Solid の設定方法: AIエージェントによるShadcn Registry for SolidJS","ko":"React-to-Solid 설정 가이드: Shadcn Registry for SolidJS","es":"Guía de transformación React-to-Solid para desarrolladores",