INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('carere/zaidan/react-to-solid', 'react-to-solid', 'carere', 'zaidan', 'community', 'react-to-solid carere zaidan community shadcn-ui solidjs The react-to-solid skill provides a single source of truth for React-to-SolidJS transformations, benefiting AI agents and developers working with Shadcn UI and SolidJS. React-to-Solid是一个知识资源，提供React组件到SolidJS的转换规则和映射 React-to-Solidは知識リソースであり、ReactコンポーネントをSolidJSに変換するルールとマッピングを提供する React-to-Solid는 지식 자원으로, React 컴포넌트를 SolidJS로 변환하는 규칙과 매핑을 제공합니다 El conjunto de reglas React-to-Solid proporciona una fuente única de verdad para transformar componentes React en SolidJS L''ensemble de règles React-to-Solid fournit une source unique de vérité pour convertir des composants React en SolidJS Der Satz von Regeln React-to-Solid bietet eine einzige Quelle der Wahrheit für die Umwandlung von React-Komponenten in SolidJS O skill react-to-solid fornece regras de transformação para converter componentes React em SolidJS, permitindo a criação de aplicações personalizadas Навык react-to-solid предоставляет правила трансформации для преобразования компонентов React в SolidJS, позволяя создавать настраиваемые приложения المهارة react-to-solid توفر قواعد التحويل لتحويل مكونات React إلى SolidJS، مما يسمح بإنشاء تطبيقات مخصصة how to use react-to-solid react-to-solid transformation rules react-to-solid vs Shadcn UI react-to-solid install guide what is react-to-solid react-to-solid setup for AI agents react-to-solid alternative for SolidJS react-to-solid best practices react-to-solid for Shadcn registry React-to-Solid Shadcn Registry for SolidJS React组件转换 SolidJS开发 AI工具 前端开发 JavaScript开发 Provides reusable context for React-to-SolidJS transformations Offers a single source of truth for transformation rules in the Zaidan project Supports Shadcn UI and SolidJS technologies Enables AI agents to reference transformation tables for accurate conversions Includes critical rules for seamless React-to-SolidJS conversions react-to-solid is a knowledge resource providing transformation rules for converting React components to SolidJS equivalents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('carrotwaxr/peek-stash-browser/release-workflow', 'community', 'carrotwaxr', 'peek-stash-browser', 'carrotwaxr/peek-stash-browser', 'release-workflow', 25, 4, 44, '2026-02-27T00:57:04Z', '2026-03-06T06:40:17.037Z', '2f74f557efafd15422d11e226b9e7f6af59509e5dc3042a0d3e26c1152db8c66', '{"id":"carrotwaxr/peek-stash-browser/release-workflow","name":"release-workflow","description":{"en":"The release-workflow skill automates deployment for media browser apps, utilizing GitHub Actions and Docker Hub. It benefits developers by simplifying the release process.","zh":"release-workflow 是一个自动化发布流程，使用 GitHub Actions 和 Docker Hub 实现版本管理和发布","ja":"release-workflow は GitHub Actions と Docker Hub を使用してバージョン管理と公開を自動化するツールです","ko":"release-workflow는 GitHub Actions와 Docker Hub를 사용하여 버전 관리와 배포를 자동화하는 도구입니다","es":"Release-workflow es una herramienta que automatiza la creación y publicación de imágenes Docker mediante GitHub Actions","fr":"Release-workflow est un outil qui automatise la création et la publication d''images Docker via GitHub Actions","de":"Release-workflow ist ein Tool, das die Erstellung und Veröffentlichung von Docker-Images mittels GitHub Actions automatisiert","pt":"O release-workflow é um fluxo de trabalho que automatiza o lançamento do aplicativo, incluindo validação pré-lançamento e publicação de imagens Docker.","ru":"Release-workflow - это рабочий процесс, который автоматизирует выпуск приложения, включая предварительную проверку и публикацию образов Docker.","ar":"release-workflow هو تدفق عمل يتلقيم إصدار التطبيق، بما في ذلك التحقق المسبق للإصدار ونشر صور Docker."},"seo":{"title":{"en":"release-workflow: Automated Deployment Setup Guide | AI A...","zh":"release-workflow 设置指南：自动化 Docker 镜像发布","ja":"release-workflow 導入ガイド：GitHub Actions による Docker イメージ自動公開","ko":"release-workflow 설정 가이드: 자동화 된 Docker 이미지 배포","es":"Guía de Configuración de release-workflow para Desarrolla...","fr":"Configurer le release-workflow pour les Développeurs","de":"Release-Workflow Einrichtung für Entwickler","pt":"Guia de Configuração do release-workflow: Automatize o Fl...","ru":"Настройка release-workflow: Автоматизация Процесса Выпуск...","ar":"دليل إعداد release-workflow: تلقيم تدفق الإصدار للوكلاء ا..."},"description":{"en":"Streamline your media browser app deployment with release-workflow. Learn how to automate GitHub Actions and Docker Hub publishing. Get started now!","zh":"了解 release-workflow 的自动化发布流程，使用 GitHub Actions 和 Docker Hub 实现版本管理和发布","ja":"release-workflow を使用して GitHub Actions と Docker Hub でバージョン管理と公開を自動化する方法を学びます","ko":"release-workflow를 사용하여 GitHub Actions와 Docker Hub로 버전 관리와 배포를 자동화하는 방법을 알아보세요","es":"Aprende a configurar release-workflow con GitHub Actions y Docker Hub para una entrega de software eficiente","fr":"Découvrez comment configurer release-workflow avec GitHub Actions et Docker Hub pour une livraison de logiciels efficace","de":"Erfahren Sie, wie Sie release-workflow mit GitHub Actions und Docker Hub für eine effiziente Softwarelieferung einrichten","pt":"Aprenda a configurar o release-workflow para automatizar o fluxo de lançamento do seu aplicativo, incluindo validação pré-lançamento e publicação de imagens ...","ru":"Узнайте, как настроить release-workflow, чтобы автоматизировать процесс выпуска вашего приложения, включая предварительную проверку и публикацию образов Docker","ar":"تعلم كيفية إعداد release-workflow لتلقيم تدفق الإصدار لتطبيقك، بما في ذلك التحقق المسبق للإصدار ونشر صور Docker"},"definition":{"en":"release-workflow is a media browser app deployment automation tool using GitHub Actions and Docker Hub, triggered by git tags.","zh":"release-workflow 是一个自动化发布流程工具，用于管理和发布软件版本","ja":"release-workflow はソフトウェアのバージョン管理と公開を自動化するツールです","ko":"release-workflow는 소프트웨어 버전 관리와 배포를 자동화하는 도구입니다","es":"Release-workflow es un proceso automatizado que utiliza GitHub Actions y Docker Hub para entregar software","fr":"Release-workflow est un processus automatisé qui utilise GitHub Actions et Docker Hub pour livrer des logiciels","de":"Release-workflow ist ein automatisierter Prozess, der GitHub Actions und Docker Hub für die Softwarelieferung verwendet","pt":"O que é release-workflow? É um fluxo de trabalho que automatiza o lançamento do aplicativo.","ru":"Что такое release-workflow? Это рабочий процесс, который автоматизирует выпуск приложения.","ar":"ما هو release-workflow؟ هو تدفق عمل يتلقيم إصدار التطبيق."},"features":{"en":["Triggers releases by pushing git tags","Automates Docker image builds and publishing via GitHub Actions","Supports stable and beta version schemes (X.Y.Z and X.Y.Z-beta.N)","Requires identical versions in client/package.json and server/package.json","Uses a specific tag format (vX.Y.Z or vX.Y.Z-beta.N)"],"zh":["自动化发布流程","使用 GitHub Actions 和 Docker Hub","支持稳定版和 beta 版本","版本号格式为 X.Y.Z 或 X.Y.Z-beta.N","支持 pre-release 验证"],"ja":["自動化された公開プロセス","GitHub Actions と Docker Hub を使用","安定版とベータ版のサポート","バージョン番号形式は X.Y.Z または X.Y.Z-beta.N","pre-release 検証のサポート"],"ko":["자동화된 배포 프로세스","GitHub Actions와 Docker Hub 사용","안정 버전과 베타 버전 지원","버전 번호 형식은 X.Y.Z 또는 X.Y.Z-beta.N","pre-release 검증 지원"],"es":["Automatización de la creación y publicación de imágenes Docker","Integración con GitHub Actions para la creación y publicación automática","Soporte para versiones estándar y beta","Formato de etiqueta personalizable (vX.Y.Z o vX.Y.Z-beta.N)","Validación previa a la publicación para garantizar la calidad del software"],"fr":["Automatisation de la création et de la publication d''images Docker","Intégration avec GitHub Actions pour la création et la publication automatique","Prise en charge des versions standard et bêta","Format d''étiquette personnalisable (vX.Y.Z ou vX.Y.Z-beta.N)","Validation préalable à la publication pour garantir la qualité du logiciel"],"de":["Automatisierung der Erstellung und Veröffentlichung von Docker-Images","Integration mit GitHub Actions für die automatische Erstellung und Veröffentlichung","Unterstützung für Standard- und Beta-Versionen","Anpassbares Label-Format (vX.Y.Z oder vX.Y.Z-beta.N)","Vorab-Validierung zur Gewährleistung der Softwarequalität"],"pt":["Validação pré-lançamento automática","Publicação de imagens Docker via GitHub Actions","Esquema de versão estável e beta","Formato de tag personalizável","Integração com client/package.json e server/package.json"],"ru":["Автоматическая предварительная проверка","Публикация образов Docker через GitHub Actions","Схема версий стабильной и бета-версии","Настраиваемый формат тега","Интеграция с client/package.json и server/package.json"],"ar":["التحقق المسبق الآلي للإصدار","نشر صور Docker عبر GitHub Actions","مخطط إصدار مستقر وبيتا","تنسيق علامة قابل للتعديل","التكامل مع client/package.json و server/package.json"]},"keywords":{"en":["release-workflow setup guide","automated deployment with GitHub Actions","Docker Hub publishing tutorial","what is release-workflow","release-workflow alternative","how to use release-workflow with Docker","release-workflow vs manual deployment","release-workflow install","media browser app deployment automation"],"zh":["release-workflow","自动化发布流程","GitHub Actions","Docker Hub","版本管理","软件发布","AI工具","自动化部署"],"ja":["release-workflow","自動化された公開プロセス","GitHub Actions","Docker Hub","バージョン管理","ソフトウェア公開","AIエージェント","自動化デプロイ"],"ko":["release-workflow","자동화된 배포 프로세스","GitHub Actions","Docker Hub","버전 관리","소프트웨어 배포","AI 에이전트","자동화 배포"],"es":["release-workflow","GitHub Actions","Docker Hub","automatización de software","entrega de software","versiones de software","etiquetas de versión","validación de software","desarrollo de software"],"fr":["release-workflow","GitHub Actions","Docker Hub","automatisation de logiciels","livraison de logiciels","versions de logiciels","étiquettes de version","validation de logiciels","développement de logiciels"],"de":["release-workflow","GitHub Actions","Docker Hub","Software-Automatisierung","Software-Lieferung","Software-Versionen","Versionsetiketten","Software-Validierung","Software-Entwicklung"],"pt":["release-workflow","fluxo de lançamento","automatização de lançamento","validação pré-lançamento","publicação de imagens Docker","GitHub Actions","esquema de versão","formato de tag"],"ru":["release-workflow","процесс выпуска","автоматизация выпуска","предварительная проверка","публикация образов Docker","GitHub Actions","схема версий","формат тега"],"ar":["release-workflow","تدفق الإصدار","تلقيم الإصدار","التحقق المسبق للإصدار","نشر صور Docker","GitHub Actions","مخطط إصدار","تنسيق علامة"]}},"owner":"carrotwaxr","repo":"peek-stash-browser","repoPath":"carrotwaxr/peek-stash-browser","stars":25,"forks":4,"updatedAt":"2026-02-27T00:57:04Z","topics":[],"category":"community","skillMd":{"name":"release-workflow","description":"Use when preparing or executing a release of peek-stash-browser. Covers the full release lifecycle from validation through Docker image publishing.","bodyPreview":"# Release Workflow\n\n## Overview\n\nReleases are triggered by pushing git tags. GitHub Actions builds and publishes Docker images automatically.\n\n```\nPre-release validation → Version bump → Commit → Tag → Push → GitHub Actions → Docker Hub\n```\n\n## Version Scheme\n\n- **Stable**: `X.Y.Z` (e.g., `3.3.1`)\n- **Beta**: `X.Y.Z-beta.N` (e.g., `3.3.2-beta.1`)\n- **Tag format**: `vX.Y.Z` or `vX.Y.Z-beta.N`\n\nBoth `client/package.json` and `server/package.json` must always have identical versions.\n\n## Step 1: Pr","body":"# Release Workflow\n\n## Overview\n\nReleases are triggered by pushing git tags. GitHub Actions builds and publishes Docker images automatically.\n\n```\nPre-release validation → Version bump → Commit → Tag → Push → GitHub Actions → Docker Hub\n```\n\n## Version Scheme\n\n- **Stable**: `X.Y.Z` (e.g., `3.3.1`)\n- **Beta**: `X.Y.Z-beta.N` (e.g., `3.3.2-beta.1`)\n- **Tag format**: `vX.Y.Z` or `vX.Y.Z-beta.N`\n\nBoth `client/package.json` and `server/package.json` must always have identical versions.\n\n## Step 1: Pre-Release Validation\n\nRun `/pre-release` to execute all checks:\n\n1. Server unit tests: `cd server && npm test`\n2. Server linting: `cd server && npm run lint`\n3. Client unit tests: `cd client && npm test`\n4. Client linting: `cd client && npm run lint`\n5. Integration tests: `cd server && npm run test:integration`\n6. Client build: `cd client && npm run build`\n7. Docker production build: `docker build -f Dockerfile.production -t peek:test .`\n\nAll 7 checks must pass before proceeding.\n\n## Step 2: Version Bump & Tag\n\n### Beta Release\n\nRun `/release-beta`:\n\n- Increment beta number: `3.3.2-beta.1` → `3.3.2-beta.2`\n- Or start new beta: `3.3.1` → `3.3.2-beta.1`\n\n### Stable Release\n\nRun `/release-stable`:\n\n- Remove beta suffix: `3.3.2-beta.8` → `3.3.2`\n- Or increment: `3.3.2` → `3.3.3` or `3.4.0`\n\n### What the Release Skills Do\n\n1. Verify on `main` branch and up to date\n2. Update version in `client/package.json` and `server/package.json`\n3. Commit: `chore: bump version to X.Y.Z`\n4. Push commit to main\n5. Create tag: `git tag vX.Y.Z`\n6. Push tag: `git push origin vX.Y.Z`\n\n## Step 3: Automated CI/CD\n\nGitHub Actions (`.github/workflows/docker-build.yml`) triggers on `v*` tags:\n\n1. **Build**: Multi-stage Dockerfile.production (frontend → backend → runtime)\n2. **Platforms**: `linux/amd64` + `linux/arm64`\n3. **Push to Docker Hub**: `carrotwaxr/peek-stash-browser`\n4. **Tag strategy**:\n   - Semver: `3.3.2`\n   - Major.minor: `3.3`\n   - `latest` (stable releases only)\n   - `stable` (stable releases only)\n   - `beta` (beta releases only)\n5. **GitHub Release**: Auto-created with generated release notes, marked as prerelease if beta\n\n## Docker Hub Tags After Release\n\n| Release Type | Tags Applied |\n|-------------|-------------|\n| `v3.3.2` (stable) | `3.3.2`, `3.3`, `latest`, `stable` |\n| `v3.3.2-beta.1` | `3.3.2-beta.1`, `beta` |\n\n## Updating on unRAID\n\nAfter GitHub Actions completes:\n\n```bash\n# SSH to your deployment server\nssh root@<server-ip>\n\n# Pull new image\ndocker pull carrotwaxr/peek-stash-browser:latest  # or :beta\n\n# Restart container via unRAID WebGUI or CLI\ndocker stop peek-stash-browser && docker start peek-stash-browser\n```\n\n## Semantic Versioning Guide\n\n- **Patch** (3.3.X): Bug fixes, minor tweaks, no new features\n- **Minor** (3.X.0): New features, backward-compatible changes\n- **Major** (X.0.0): Breaking changes (rare — major UI overhauls, API changes)\n"},"lastSynced":"2026-03-06T06:40:17.037Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents automating media browser app deployments using GitHub Actions and Docker Hub.","zh":"适用于使用 GitHub Actions 和 Docker Hub 自动化媒体浏览器应用程序部署的 DevOps 代理。","ja":"GitHub Actions と Docker Hub を使用してメディア ブラウザ アプリのデプロイを自動化するための DevOps エージェントに最適です。","ko":"GitHub Actions와 Docker Hub를 사용하여 미디어 브라우저 앱의 배포를 자동화하는 데 적합한 DevOps 에이전트입니다.","es":"Ideal para agentes de DevOps que automatizan implementaciones de aplicaciones de navegador de medios utilizando GitHub Actions y Docker Hub.","fr":"Idéal pour les agents DevOps qui automatisent les déploiements d''applications de navigateur de médias à l''aide de GitHub Actions et Docker Hub.","de":"Ideal für DevOps-Agents, die Medienbrowser-App-Deployments mit GitHub Actions und Docker Hub automatisieren.","pt":"Ideal para agentes DevOps que automatizam implantações de aplicativos de navegador de mídia usando GitHub Actions e Docker Hub.","ru":"Идеально подходит для агентов DevOps, автоматизирующих развертывание медиа-браузерных приложений с использованием GitHub Actions и Docker Hub.","ar":"مثالي لعميل DevOps الذي يؤتمة عمليات نشر تطبيقات متصفح الوسائط باستخدام GitHub Actions و Docker Hub."},"recommendation":{"en":"Empowers agents to automate the release process for media browser apps, utilizing GitHub Actions for building and publishing Docker images, and adhering to a strict version scheme with formats like vX.Y.Z or vX.Y.Z-beta.N.","zh":"赋予代理自动化媒体浏览器应用程序的发布过程的能力，利用 GitHub Actions 来构建和发布 Docker 镜像，并遵循严格的版本方案，如 vX.Y.Z 或 vX.Y.Z-beta.N。","ja":"エージェントにメディア ブラウザ アプリのリリース プロセスを自動化する能力を与え、GitHub Actions を使用して Docker イメージをビルドおよび公開し、vX.Y.Z または vX.Y.Z-beta.N などの厳格なバージョン スキームに従います。","ko":"에이전트가 미디어 브라우저 앱의 릴리즈 프로세스를 자동화할 수 있도록 해주며, GitHub Actions를 사용하여 Docker 이미지를 빌드하고公開하며, vX.Y.Z 또는 vX.Y.Z-beta.N과 같은 엄격한 버전 체계를 따릅니다.","es":"Permite a los agentes automatizar el proceso de lanzamiento de aplicaciones de navegador de medios, utilizando GitHub Actions para compilar y publicar imágenes de Docker, y adherirse a un esquema de versión estricto con formatos como vX.Y.Z o vX.Y.Z-beta.N.","fr":"Permet aux agents d''automatiser le processus de publication d''applications de navigateur de médias, en utilisant GitHub Actions pour construire et publier des images Docker, et en respectant un schéma de version strict avec des formats tels que vX.Y.Z ou vX.Y.Z-beta.N.","de":"Ermächtigt Agents, den Release-Prozess für Medienbrowser-Apps zu automatisieren, indem GitHub Actions zum Erstellen und Veröffentlichen von Docker-Images verwendet werden und einem strengen Versionschema mit Formaten wie vX.Y.Z oder vX.Y.Z-beta.N entsprochen wird.","pt":"Permite que os agentes automatem o processo de lançamento para aplicativos de navegador de mídia, utilizando GitHub Actions para compilar e publicar imagens Docker, e aderindo a um esquema de versão rigoroso com formatos como vX.Y.Z ou vX.Y.Z-beta.N.","ru":"Позволяет агентам автоматизировать процесс выпуска медиа-браузерных приложений, используя GitHub Actions для сборки и публикации образов Docker, и придерживаясь строгой схемы версий с форматами типа vX.Y.Z или vX.Y.Z-beta.N.","ar":"تمكين العميل من أتمتة عملية إصدار تطبيقات متصفح الوسائط، باستخدام GitHub Actions لبناء ونشر صور Docker، والالتزام بخطط إصدار صارمة بأشكال مثل vX.Y.Z أو vX.Y.Z-beta.N."},"useCases":{"en":["Automating deployment for media browser apps","Validating pre-release versions using GitHub Actions","Publishing Docker images to Docker Hub"],"zh":["自动化媒体浏览器应用程序的部署","使用 GitHub Actions 验证预发布版本","将 Docker 镜像发布到 Docker Hub"],"ja":["メディア ブラウザ アプリのデプロイを自動化する","GitHub Actions を使用してプレリリース バージョンを検証する","Docker イメージを Docker Hub に公開する"],"ko":["미디어 브라우저 앱의 배포를 자동화하는 것","GitHub Actions를 사용하여 프리 릴리즈 버전을 검증하는 것","Docker 이미지를 Docker Hub에 게시하는 것"],"es":["Automatizar la implementación de aplicaciones de navegador de medios","Validar versiones prelanzamiento utilizando GitHub Actions","Publicar imágenes de Docker en Docker Hub"],"fr":["Automatiser le déploiement d''applications de navigateur de médias","Valider les versions préalables à l''aide de GitHub Actions","Publier des images Docker sur Docker Hub"],"de":["Automatisierung der Bereitstellung von Medienbrowser-Apps","Validierung von Vorabversionen mit GitHub Actions","Veröffentlichung von Docker-Images auf Docker Hub"],"pt":["Automatizar implantação para aplicativos de navegador de mídia","Validar versões pré-lançamento usando GitHub Actions","Publicar imagens Docker no Docker Hub"],"ru":["Автоматизация развертывания медиа-браузерных приложений","Проверка предварительных версий с использованием GitHub Actions","Публикация образов Docker в Docker Hub"],"ar":["أتمتة نشر تطبيقات متصفح الوسائط","التحقق من الإصدارات قبل الإصدار باستخدام GitHub Actions","نشر صور Docker في Docker Hub"]},"limitations":{"en":["Requires GitHub repository access","Docker Hub account needed","Version scheme adherence (X.Y.Z or X.Y.Z-beta.N)"],"zh":["需要 GitHub 仓库访问权限","需要 Docker Hub 账户","需要遵循版本方案（X.Y.Z 或 X.Y.Z-beta.N）"],"ja":["GitHub リポジトリへのアクセスが必要","Docker Hub アカウントが必要","バージョン スキーム (X.Y.Z または X.Y.Z-beta.N) に従う必要がある"],"ko":["GitHub 저장소 액세스가 필요함","Docker Hub 계정이 필요함","버전 체계(X.Y.Z 또는 X.Y.Z-beta.N)를 따르는 것이 필요함"],"es":["Requiere acceso al repositorio de GitHub","Se necesita una cuenta de Docker Hub","Cumplimiento del esquema de versión (X.Y.Z o X.Y.Z-beta.N)"],"fr":["Nécessite un accès au référentiel GitHub","Un compte Docker Hub est